--
-- Name: abandon_specialty_session(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.abandon_specialty_session(p_queue_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result JSONB;
  v_staff_id UUID;
  v_is_admin BOOLEAN;
  v_queue RECORD;
BEGIN
  -- Get current staff
  SELECT id, role::text IN ('super_admin', 'admin', 'medical_director', 'Admin', 'System_Admin', 'Medical_Director')
  INTO v_staff_id, v_is_admin
  FROM staff 
  WHERE user_id = auth.uid();
  
  IF v_staff_id IS NULL THEN
    RAISE EXCEPTION 'Staff not found for current user';
  END IF;
  
  -- Get queue entry
  SELECT * INTO v_queue
  FROM queue
  WHERE id = p_queue_id
  FOR UPDATE;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Queue entry not found'
    );
  END IF;
  
  -- Only allow abandoning In Progress sessions
  IF v_queue.status != 'In Progress' THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Session is not in progress',
      'current_status', v_queue.status
    );
  END IF;
  
  -- Check permission: only session owner or admin can abandon
  IF NOT v_is_admin AND v_queue.assigned_to != v_staff_id THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Only the session owner or an admin can abandon this session'
    );
  END IF;
  
  -- Revert to Waiting status
  UPDATE queue
  SET status = 'Waiting',
      called_at = NULL,
      assigned_to = NULL,
      session_started_at = NULL,
      session_staff_id = NULL,
      updated_at = NOW()
  WHERE id = p_queue_id;
  
  RETURN jsonb_build_object(
    'success', true,
    'message', 'Session abandoned - patient returned to waiting queue',
    'queue_id', p_queue_id,
    'new_status', 'Waiting'
  );
END;
$$;


--
-- Name: accept_specialty_referral(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_specialty_referral(p_request_id uuid, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
  v_staff_id uuid;
  v_specialty_code varchar(50);
BEGIN
  -- Get current staff
  SELECT id, specialty_code INTO v_staff_id, v_specialty_code
  FROM staff WHERE user_id = auth.uid();
  
  IF v_staff_id IS NULL THEN
    RAISE EXCEPTION 'Staff not found for current user';
  END IF;
  
  -- Update referral with audit fields
  UPDATE clinical_requests SET
    status = 'In_Progress',
    referral_accepted_at = now(),
    referral_accepted_by = v_staff_id,
    notes = COALESCE(p_notes, notes),
    updated_at = now()
  WHERE id = p_request_id
    AND request_type = 'Referral'
    AND target_specialty_code = v_specialty_code
    AND status IN ('Pending', 'Approved')
  RETURNING jsonb_build_object(
    'id', id, 
    'status', status, 
    'accepted_at', referral_accepted_at,
    'accepted_by', v_staff_id
  ) INTO v_result;
  
  IF v_result IS NULL THEN
    RAISE EXCEPTION 'Referral not found or access denied';
  END IF;
  
  RETURN v_result;
END;
$$;


