--
-- Name: approve_outgoing_referral(uuid, character varying, character varying, character varying, text, date, date, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_outgoing_referral(p_queue_id uuid, p_nhis_referral_code character varying, p_destination_facility_name character varying, p_destination_facility_nhis_id character varying DEFAULT NULL::character varying, p_destination_facility_address text DEFAULT NULL::text, p_referral_valid_from date DEFAULT CURRENT_DATE, p_referral_valid_to date DEFAULT NULL::date, p_processing_notes text DEFAULT NULL::text, p_processed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_result JSONB;
    v_queue_record RECORD;
BEGIN
    -- Get the queue record
    SELECT * INTO v_queue_record
    FROM nhis_referral_queue
    WHERE id = p_queue_id AND referral_direction = 'outgoing';
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Outgoing referral not found'
        );
    END IF;
    
    IF v_queue_record.status != 'pending' THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Referral is not in pending status'
        );
    END IF;
    
    -- Validate required fields
    IF p_nhis_referral_code IS NULL OR p_nhis_referral_code = '' THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'NHIS Referral Code is required'
        );
    END IF;
    
    IF p_destination_facility_name IS NULL OR p_destination_facility_name = '' THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Destination Facility Name is required'
        );
    END IF;
    
    -- Set default validity period (30 days if not specified)
    IF p_referral_valid_to IS NULL THEN
        p_referral_valid_to := p_referral_valid_from + INTERVAL '30 days';
    END IF;
    
    -- Update the queue record
    UPDATE nhis_referral_queue
    SET 
        status = 'approved',
        nhis_referral_code = p_nhis_referral_code,
        destination_facility_name = p_destination_facility_name,
        destination_facility_nhis_id = p_destination_facility_nhis_id,
        destination_facility_address = p_destination_facility_address,
        referral_valid_from = p_referral_valid_from,
        referral_valid_to = p_referral_valid_to,
        processing_notes = p_processing_notes,
        processed_by = p_processed_by,
        processed_at = NOW(),
        updated_at = NOW()
    WHERE id = p_queue_id;
    
    RETURN jsonb_build_object(
        'success', true,
        'message', 'Outgoing referral approved successfully',
        'queue_id', p_queue_id,
        'nhis_referral_code', p_nhis_referral_code,
        'destination_facility', p_destination_facility_name,
        'valid_until', p_referral_valid_to
    );
END;
$$;


--
-- Name: archive_old_audit_logs(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_old_audit_logs(p_older_than_days integer DEFAULT 90) RETURNS TABLE(table_name text, rows_archived bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cutoff        TIMESTAMPTZ := now() - (p_older_than_days || ' days')::INTERVAL;
  v_archived_al   BIGINT := 0;
  v_archived_nhis BIGINT := 0;
  v_archived_bill BIGINT := 0;
BEGIN
  -- Archive audit_logs
  WITH moved AS (
    DELETE FROM audit_logs
    WHERE created_at < v_cutoff
    RETURNING *
  )
  INSERT INTO audit_logs_archive SELECT * FROM moved;
  GET DIAGNOSTICS v_archived_al = ROW_COUNT;

  -- Archive nhis_audit_log
  WITH moved AS (
    DELETE FROM nhis_audit_log
    WHERE performed_at < v_cutoff
    RETURNING *
  )
  INSERT INTO nhis_audit_log_archive SELECT * FROM moved;
  GET DIAGNOSTICS v_archived_nhis = ROW_COUNT;

  -- Archive billing_audit_log
  WITH moved AS (
    DELETE FROM billing_audit_log
    WHERE performed_at < v_cutoff
    RETURNING *
  )
  INSERT INTO billing_audit_log_archive SELECT * FROM moved;
  GET DIAGNOSTICS v_archived_bill = ROW_COUNT;

  RETURN QUERY VALUES
    ('audit_logs',          v_archived_al),
    ('nhis_audit_log',      v_archived_nhis),
    ('billing_audit_log',   v_archived_bill);
END;
$$;


--
-- Name: assign_bed_on_admission(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_bed_on_admission() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
    -- If a bed is being assigned
    IF NEW.current_bed_id IS NOT NULL AND (OLD.current_bed_id IS NULL OR NEW.current_bed_id != OLD.current_bed_id) THEN
        -- Release old bed if there was one
        IF OLD.current_bed_id IS NOT NULL THEN
            UPDATE beds
            SET status = 'Available', -- Changed from 'Cleaning' to 'Available'
                current_patient_id = NULL,
                current_admission_id = NULL,
                updated_at = NOW()
            WHERE id = OLD.current_bed_id;
        END IF;

        -- Assign new bed
        UPDATE beds
        SET status = 'Occupied',
            current_patient_id = NEW.patient_id,
            current_admission_id = NEW.id,
            updated_at = NOW()
        WHERE id = NEW.current_bed_id;
    END IF;

    -- If admission is being discharged, release the bed
    IF NEW.admission_status IN ('discharged', 'transferred', 'deceased')
       AND OLD.admission_status NOT IN ('discharged', 'transferred', 'deceased') THEN
        UPDATE beds
        SET status = 'Available', -- Changed from 'Cleaning' to 'Available'
            current_patient_id = NULL,
            current_admission_id = NULL,
            updated_at = NOW()
        WHERE id = NEW.current_bed_id;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: assign_visit_facility_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_visit_facility_id() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
  v_facility_id uuid;
BEGIN
  IF NEW.facility_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- Resolve from current user facility
  IF v_facility_id IS NULL THEN
    v_facility_id := public.get_user_facility_id();
  END IF;

  -- Final fallback to default facility
  IF v_facility_id IS NULL THEN
    SELECT id INTO v_facility_id
    FROM public.facilities
    ORDER BY created_at NULLS LAST, id
    LIMIT 1;
  END IF;

  NEW.facility_id := v_facility_id;
  RETURN NEW;
END;
$$;


--
-- Name: audit_lab_request_changes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_lab_request_changes() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_action audit_action;
    v_description TEXT;
    v_old_values JSONB;
    v_new_values JSONB;
BEGIN
    IF TG_OP = 'INSERT' THEN
        v_action := 'CREATE';
        v_description := 'Lab test ordered: ' || COALESCE(
            (SELECT name FROM lab_test_catalogue WHERE id = NEW.test_id),
            'Unknown test'
        );
        v_new_values := to_jsonb(NEW);
        
    ELSIF TG_OP = 'UPDATE' THEN
        -- Detect specific status changes
        IF OLD.status != NEW.status THEN
            CASE NEW.status
                WHEN 'Accepted' THEN v_action := 'UPDATE'; v_description := 'Lab request accepted';
                WHEN 'Rejected' THEN v_action := 'UPDATE'; v_description := 'Lab request rejected: ' || COALESCE(NEW.rejection_reason, 'No reason');
                WHEN 'Sample Collected' THEN v_action := 'UPDATE'; v_description := 'Sample collected for lab request';
                WHEN 'In Progress' THEN v_action := 'UPDATE'; v_description := 'Lab test processing started';
                WHEN 'Completed' THEN v_action := 'UPDATE'; v_description := 'Lab results entered';
                ELSE v_action := 'UPDATE'; v_description := 'Lab request status changed to ' || NEW.status;
            END CASE;
        ELSE
            v_action := 'UPDATE';
            v_description := 'Lab request updated';
        END IF;
        v_old_values := to_jsonb(OLD);
        v_new_values := to_jsonb(NEW);
        
    ELSIF TG_OP = 'DELETE' THEN
        v_action := 'DELETE';
        v_description := 'Lab request deleted';
        v_old_values := to_jsonb(OLD);
    END IF;
    
    PERFORM log_audit_event(
        'order'::audit_category,
        v_action,
        'lab_request',
        COALESCE(NEW.request_id, OLD.request_id)::TEXT,
        v_description,
        CASE WHEN NEW.is_critical THEN 'alert'::audit_severity ELSE 'info'::audit_severity END,
        (SELECT id FROM staff WHERE staff_id = COALESCE(NEW.ordered_by, OLD.ordered_by)),
        COALESCE(NEW.patient_id, OLD.patient_id),
        COALESCE(NEW.encounter_id, OLD.encounter_id),
        NULL,
        v_old_values,
        v_new_values
    );
    
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    ELSE
        RETURN NEW;
    END IF;
END;
$$;


--
-- Name: audit_nursing_intervention_create(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_nursing_intervention_create() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
    INSERT INTO audit_logs (
        action,
        entity_type,
        entity_id,
        user_id,
        new_values,
        created_at
    ) VALUES (
        'CREATE',
        'nursing_intervention',
        NEW.id::TEXT,
        NEW.nurse_id::TEXT,
        jsonb_build_object(
            'encounter_id', NEW.encounter_id,
            'patient_id', NEW.patient_id,
            'ward_id', NEW.ward_id,
            'category_code', NEW.category_code,
            'intervention_code', NEW.intervention_code,
            'performed_at', NEW.performed_at,
            'shift', NEW.shift
        ),
        NOW()
    );
    RETURN NEW;
EXCEPTION
    WHEN OTHERS THEN
        -- Don't fail the main operation if audit logging fails
        RETURN NEW;
END;
$$;


--
-- Name: audit_prescription_changes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_prescription_changes() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_action audit_action;
    v_description TEXT;
    v_drug_name TEXT;
BEGIN
    -- Get drug name
    SELECT name INTO v_drug_name
    FROM drug_catalogue WHERE id = COALESCE(NEW.drug_id, OLD.drug_id);
    
    IF TG_OP = 'INSERT' THEN
        v_action := 'CREATE';
        v_description := 'Prescription created: ' || COALESCE(v_drug_name, NEW.drug_name, 'Unknown drug');
        
    ELSIF TG_OP = 'UPDATE' THEN
        IF OLD.status != NEW.status THEN
            CASE NEW.status
                WHEN 'Dispensed' THEN v_action := 'UPDATE'; v_description := 'Medication dispensed: ' || COALESCE(v_drug_name, NEW.drug_name);
                WHEN 'Cancelled' THEN v_action := 'UPDATE'; v_description := 'Prescription cancelled: ' || COALESCE(v_drug_name, NEW.drug_name);
                ELSE v_action := 'UPDATE'; v_description := 'Prescription status: ' || NEW.status;
            END CASE;
        ELSE
            v_action := 'UPDATE';
            v_description := 'Prescription updated: ' || COALESCE(v_drug_name, NEW.drug_name);
        END IF;
        
    ELSIF TG_OP = 'DELETE' THEN
        v_action := 'DELETE';
        v_description := 'Prescription deleted: ' || COALESCE(v_drug_name, OLD.drug_name);
    END IF;
    
    PERFORM log_audit_event(
        'prescription'::audit_category,
        v_action,
        'prescription',
        COALESCE(NEW.prescription_id, OLD.prescription_id)::TEXT,
        v_description,
        'info'::audit_severity,
        (SELECT id FROM staff WHERE staff_id = COALESCE(NEW.doctor_id, OLD.doctor_id)),
        COALESCE(NEW.patient_id, OLD.patient_id),
        COALESCE(NEW.encounter_id, OLD.encounter_id)
    );
    
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    ELSE
        RETURN NEW;
    END IF;
END;
$$;


--
-- Name: audit_vitals_changes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_vitals_changes() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_action audit_action;
    v_description TEXT;
    v_alerts TEXT[] := ARRAY[]::TEXT[];
BEGIN
    IF TG_OP = 'INSERT' THEN
        v_action := 'CREATE';
        
        -- Check for abnormal values
        IF NEW.blood_pressure_systolic > 180 OR NEW.blood_pressure_systolic < 90 THEN
            v_alerts := array_append(v_alerts, 'Abnormal BP');
        END IF;
        IF NEW.pulse > 120 OR NEW.pulse < 50 THEN
            v_alerts := array_append(v_alerts, 'Abnormal HR');
        END IF;
        IF NEW.temperature > 39 OR NEW.temperature < 35 THEN
            v_alerts := array_append(v_alerts, 'Abnormal Temp');
        END IF;
        IF NEW.oxygen_saturation < 92 THEN
            v_alerts := array_append(v_alerts, 'Low SpO2');
        END IF;
        
        v_description := 'Vital signs recorded' || 
            CASE WHEN array_length(v_alerts, 1) > 0 
                 THEN ' [ALERTS: ' || array_to_string(v_alerts, ', ') || ']'
                 ELSE '' END;
        
    ELSIF TG_OP = 'UPDATE' THEN
        v_action := 'UPDATE';
        v_description := 'Vital signs updated';
        
    ELSIF TG_OP = 'DELETE' THEN
        v_action := 'DELETE';
        v_description := 'Vital signs deleted';
    END IF;
    
    PERFORM log_audit_event(
        'vitals'::audit_category,
        v_action,
        'vitals',
        COALESCE(NEW.id, OLD.id)::TEXT,
        v_description,
        CASE WHEN array_length(v_alerts, 1) > 0 THEN 'alert'::audit_severity ELSE 'info'::audit_severity END,
        COALESCE(NEW.nurse_id, OLD.nurse_id),
        (SELECT p.patient_id FROM patients p WHERE p.id = COALESCE(NEW.patient_id, OLD.patient_id)),
        COALESCE(NEW.encounter_id, OLD.encounter_id),
        NULL,
        CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN to_jsonb(OLD) ELSE NULL END,
        CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN to_jsonb(NEW) ELSE NULL END,
        NULL,
        NULL,
        CASE WHEN array_length(v_alerts, 1) > 0 
             THEN jsonb_build_object('alerts', v_alerts) 
             ELSE '{}'::jsonb END
    );
    
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    ELSE
        RETURN NEW;
    END IF;
END;
$$;


--
-- Name: auto_add_on_call_to_care_team(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_add_on_call_to_care_team() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_staff_record RECORD;
    v_encounter_record RECORD;
BEGIN
    -- When on-call schedule is activated, add doctor to active encounters in that department
    IF TG_OP = 'INSERT' OR (TG_OP = 'UPDATE' AND OLD.is_active = false AND NEW.is_active = true) THEN
        
        -- Get staff details
        SELECT * INTO v_staff_record
        FROM staff
        WHERE id = NEW.staff_id;
        
        -- Add to active encounters in the department
        FOR v_encounter_record IN 
            SELECT v.id as encounter_id
            FROM visits v
            JOIN clinics c ON c.clinic_id = v.clinic_id::text
            WHERE c.clinic_name = NEW.department
              AND v.status = 'Active'
              AND NOT EXISTS (
                  SELECT 1 FROM encounter_care_team ect
                  WHERE ect.encounter_id = v.id
                    AND ect.staff_id = NEW.staff_id
                    AND ect.is_active = true
              )
        LOOP
            INSERT INTO encounter_care_team (
                encounter_id,
                staff_id,
                staff_name,
                role,
                department,
                assigned_by,
                expires_at,
                is_active,
                notes
            ) VALUES (
                v_encounter_record.encounter_id,
                NEW.staff_id,
                v_staff_record.first_name || ' ' || v_staff_record.last_name,
                'on_call_doctor',
                NEW.department,
                NEW.created_by,
                NEW.end_time,
                true,
                'Auto-added via on-call schedule'
            )
            ON CONFLICT (encounter_id, staff_id, role) DO NOTHING;
        END LOOP;
    END IF;
    
    RETURN NEW;
END;
$$;


--
-- Name: auto_assign_shift_to_note(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_assign_shift_to_note() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
    -- Auto-assign shift if not provided
    IF NEW.shift IS NULL THEN
        NEW.shift := get_current_shift(NEW.created_at::TIME);
    END IF;
    
    -- Auto-assign shift date if not provided
    IF NEW.shift_date IS NULL THEN
        NEW.shift_date := get_shift_date(NEW.created_at);
    END IF;
    
    RETURN NEW;
END;
$$;


--
-- Name: auto_create_nhis_approval_for_referral(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_create_nhis_approval_for_referral() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
    -- REFERRALS: Always set to 'not_required' at creation time.
    -- The app code (createReferralEncounter) will set 'pending' after
    -- the referral is booked and an encounter is created.
    -- This prevents referrals from appearing in the NHIS Specialty 
    -- Approval Queue before going through the booking workflow.
    IF NEW.request_type = 'Referral' THEN
        NEW.nhis_approval_status := 'not_required';
        RETURN NEW;
    END IF;

    -- For non-referral request types, keep existing behavior
    RETURN NEW;
END;
$$;


--
-- Name: auto_create_nhis_referral_queue_for_clinical_request(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_create_nhis_referral_queue_for_clinical_request() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_is_nhis BOOLEAN := FALSE;
    v_patient_record RECORD;
    v_encounter_record RECORD;
    v_consultation_record RECORD;
    v_queue_id UUID;
    v_service_type TEXT;
    v_request_type TEXT;
BEGIN
    -- Only process Referral and Admission type requests
    IF NEW.request_type NOT IN ('Referral', 'Admission') THEN
        RETURN NEW;
    END IF;

    -- Get patient insurance info
    SELECT 
        p.id,
        p.insurance_type,
        p.patient_category,
        p.first_name || ' ' || COALESCE(p.middle_name || ' ', '') || p.surname AS full_name,
        p.patient_id AS emr_number,
        p.nhis_number,
        p.nhis_patient_source
    INTO v_patient_record
    FROM patients p
    WHERE p.id = NEW.patient_id;

    -- Check if patient is NHIS
    IF v_patient_record IS NOT NULL THEN
        IF v_patient_record.insurance_type IN ('Military_NHIS', 'Civilian_NHIS', 'GIFSHIP', 'DHML') THEN
            v_is_nhis := TRUE;
        END IF;
    END IF;

    -- Also check encounter payer type as fallback
    IF NOT v_is_nhis THEN
        SELECT payer_type, insurance_type INTO v_encounter_record FROM visits WHERE id = NEW.encounter_id;
        IF v_encounter_record.payer_type = 'nhis' 
           OR v_encounter_record.insurance_type IN ('Military_NHIS', 'Civilian_NHIS', 'GIFSHIP', 'DHML') THEN
            v_is_nhis := TRUE;
        END IF;
    END IF;

    -- If not NHIS, no queue entry needed
    IF NOT v_is_nhis THEN
        RETURN NEW;
    END IF;

    -- Get consultation data for this encounter (if any)
    SELECT 
        c.diagnosis,
        c.diagnosis_text,
        c.examination_findings,
        c.history_of_present_illness,
        c.complaints,
        c.treatment_plan,
        c.clinical_notes,
        v.chief_complaint
    INTO v_consultation_record
    FROM visits v
    LEFT JOIN consultations c ON c.encounter_id = v.id
    WHERE v.id = NEW.encounter_id;

    -- Determine service_type and request_type for queue
    IF NEW.request_type = 'Referral' THEN
        v_service_type := 'specialty_referral';
        v_request_type := 'internal_nhis_approval';
    ELSIF NEW.request_type = 'Admission' THEN
        v_service_type := 'admission';
        v_request_type := 'internal_admission';
    ELSE
        v_service_type := 'other';
        v_request_type := 'internal_nhis_approval';
    END IF;

    -- Create NHIS referral queue entry with clinical data
    INSERT INTO nhis_referral_queue (
        patient_id,
        request_type,
        clinical_request_id,
        status,
        priority,
        requested_by,
        requested_at,
        
        -- Clinical data from consultation
        chief_complaint,
        diagnosis,
        diagnosis_codes,
        examination_findings,
        history_of_present_illness,
        clinical_basis,
        clinical_notes,
        treatment_plan,
        
        -- Service details
        service_type,
        service_name,
        urgency,
        specialty_module,
        source_encounter_id,
        requesting_doctor_id,
        
        -- Admission-specific
        admission_type,
        level_of_care,
        expected_duration,
        
        -- Request notes
        request_notes
    ) VALUES (
        NEW.patient_id,
        v_request_type,
        NEW.id,
        'pending',
        CASE WHEN NEW.urgency = 'Emergency' THEN 'emergency' 
             WHEN NEW.urgency = 'Urgent' THEN 'urgent' 
             ELSE 'normal' END,
        NEW.requesting_doctor_id,
        NOW(),
        
        -- Clinical data
        COALESCE(v_consultation_record.chief_complaint, v_consultation_record.complaints),
        COALESCE(v_consultation_record.diagnosis_text, array_to_string(v_consultation_record.diagnosis, ', ')),
        v_consultation_record.diagnosis,
        v_consultation_record.examination_findings,
        v_consultation_record.history_of_present_illness,
        NEW.clinical_reason,  -- This is the "reason for referral/admission"
        v_consultation_record.clinical_notes,
        v_consultation_record.treatment_plan,
        
        -- Service details
        v_service_type,
        CASE 
            WHEN NEW.request_type = 'Referral' THEN INITCAP(NEW.specialty_module) || ' Referral'
            WHEN NEW.request_type = 'Admission' THEN 'Inpatient Admission'
            ELSE NEW.request_type
        END,
        NEW.urgency,
        NEW.specialty_module,
        NEW.encounter_id,
        NEW.requesting_doctor_id,
        
        -- Admission-specific
        NEW.admission_type,
        COALESCE(NEW.level_of_care, 'Ward'),
        NEW.expected_duration,
        
        -- Notes
        'Internal NHIS request for ' || v_patient_record.full_name || 
        ' - ' || NEW.request_type || 
        CASE WHEN NEW.specialty_module IS NOT NULL THEN ' (' || INITCAP(NEW.specialty_module) || ')' ELSE '' END
    )
    RETURNING id INTO v_queue_id;

    -- Update clinical request with queue link (if column exists)
    -- Note: This allows linking back from clinical_request to the queue item

    RAISE NOTICE 'Created NHIS referral queue entry % for clinical request %', v_queue_id, NEW.id;

    RETURN NEW;
END;
$$;


--
-- Name: auto_deactivate_expired_access(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_deactivate_expired_access() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
    -- Check if access has expired
    IF NEW.expires_at IS NOT NULL AND NEW.expires_at < NOW() AND NEW.is_active = true THEN
        NEW.is_active = false;
        NEW.updated_at = NOW();
        
        -- Log the expiration
        INSERT INTO encounter_access_logs (
            encounter_id, 
            user_id, 
            user_role, 
            action, 
            action_details, 
            was_authorized
        )
        VALUES (
            NEW.encounter_id,
            NEW.staff_id,
            NEW.role,
            'access_expired',
            'Temporary access expired for ' || NEW.staff_name,
            false
        );
    END IF;
    
    RETURN NEW;
END;
$$;


--
-- Name: auto_set_nhis_status_for_encounter(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_set_nhis_status_for_encounter() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_payment_category TEXT;
BEGIN
    -- Only clinical_requests has request_type. For that table, skip Referrals
    -- because they have their own workflow (app sets pending after encounter creation).
    IF TG_TABLE_NAME = 'clinical_requests' THEN
        IF NEW.request_type = 'Referral' THEN
            RETURN NEW;
        END IF;
    END IF;

    -- For all other tables/types, check if the encounter is NHIS
    SELECT payment_category INTO v_payment_category
    FROM visits 
    WHERE id = NEW.encounter_id;
    
    -- If NHIS encounter, set status to 'pending' instead of 'not_required'
    IF v_payment_category = 'NHIS' AND NEW.nhis_approval_status = 'not_required' THEN
        NEW.nhis_approval_status := 'pending';
    END IF;
    
    RETURN NEW;
END;
$$;


--
-- Name: book_referral_appointment(uuid, date, time without time zone, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.book_referral_appointment(p_referral_id uuid, p_appointment_date date, p_appointment_time time without time zone DEFAULT NULL::time without time zone, p_notes text DEFAULT NULL::text, p_booked_by uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
    UPDATE clinical_requests
    SET appointment_date = p_appointment_date,
        appointment_time = p_appointment_time,
        appointment_notes = p_notes,
        appointment_booked_by = p_booked_by,
        appointment_booked_at = NOW(),
        referral_workflow_status = 'Appointment_Booked',
        updated_at = NOW()
    WHERE id = p_referral_id
      AND request_type = 'Referral';
    
    IF NOT FOUND THEN
        RETURN FALSE;
    END IF;
    
    RETURN TRUE;
END;
$$;


--
-- Name: calculate_billing_coverage(public.billing_coverage_type_enum, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_billing_coverage(p_coverage_type public.billing_coverage_type_enum, p_service_category text, p_total_amount numeric) RETURNS TABLE(patient_amount numeric, insurance_amount numeric, is_covered boolean)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_rule RECORD;
BEGIN
    -- Get the applicable billing rule
    SELECT br.* INTO v_rule
    FROM billing_rules br
    WHERE br.coverage_type = p_coverage_type
    AND br.service_category = p_service_category
    AND br.effective_from <= CURRENT_DATE
    AND (br.effective_to IS NULL OR br.effective_to >= CURRENT_DATE)
    LIMIT 1;
    
    IF v_rule IS NULL THEN
        -- Default to 100% patient payment if no rule found
        patient_amount := p_total_amount;
        insurance_amount := 0;
        is_covered := FALSE;
    ELSE
        patient_amount := ROUND(p_total_amount * v_rule.patient_percentage / 100, 2);
        insurance_amount := ROUND(p_total_amount * v_rule.insurance_percentage / 100, 2);
        is_covered := v_rule.is_covered;
    END IF;
    
    RETURN NEXT;
END;
$$;


--
-- Name: calculate_next_vitals_due(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_next_vitals_due(p_schedule_id uuid, p_from_time timestamp with time zone DEFAULT now()) RETURNS timestamp with time zone
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_frequency INTEGER;
    v_custom_frequency INTEGER;
    v_acuity patient_acuity;
BEGIN
    -- Get the schedule's frequency
    SELECT 
        pvs.acuity_level,
        pvs.custom_frequency_minutes,
        vsc.frequency_minutes
    INTO v_acuity, v_custom_frequency, v_frequency
    FROM patient_vital_schedules pvs
    JOIN vital_schedule_configs vsc ON vsc.acuity_level = pvs.acuity_level
    WHERE pvs.id = p_schedule_id;
    
    -- Use custom frequency if set, otherwise default
    IF v_custom_frequency IS NOT NULL THEN
        v_frequency := v_custom_frequency;
    END IF;
    
    RETURN p_from_time + (v_frequency || ' minutes')::INTERVAL;
END;
$$;


--
-- Name: calculate_nhis_amounts(numeric, character varying, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_nhis_amounts(p_gross_amount numeric, p_insurance_type character varying, p_service_type character varying DEFAULT 'Other'::character varying, p_service_nhis_percentage integer DEFAULT NULL::integer) RETURNS TABLE(nhis_covered boolean, nhis_percentage integer, nhis_payable numeric, patient_payable numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
    v_config RECORD;
    v_coverage_pct INTEGER := 0;
    v_is_nhis BOOLEAN := FALSE;
    v_consultation_free BOOLEAN := FALSE;
    v_normalized VARCHAR;
    v_svc_lower VARCHAR;
BEGIN
    -- Normalize inputs
    v_normalized := LOWER(REPLACE(COALESCE(p_insurance_type, ''), '_', ' '));
    v_svc_lower := LOWER(COALESCE(p_service_type, 'other'));

    -- Look up full config row from nhis_config (single source of truth)
    SELECT nc.coverage_percentage,
           nc.consultation_fully_covered,
           nc.lab_coverage_percentage,
           nc.radiology_coverage_percentage,
           nc.pharmacy_coverage_percentage,
           nc.procedure_coverage_percentage,
           nc.bed_coverage_percentage
    INTO v_config
    FROM nhis_config nc
    WHERE nc.is_active = TRUE
      AND LOWER(REPLACE(nc.payment_category, '_', ' ')) = v_normalized
    LIMIT 1;

    IF v_config IS NOT NULL AND v_config.coverage_percentage > 0 THEN
        v_is_nhis := TRUE;
        v_consultation_free := COALESCE(v_config.consultation_fully_covered, FALSE);

        -- Priority 1: Service-level override from catalogue (nhis_percentage > 0)
        IF p_service_nhis_percentage IS NOT NULL AND p_service_nhis_percentage > 0 THEN
            v_coverage_pct := p_service_nhis_percentage;

        -- Priority 2: Per-service-category column from nhis_config
        ELSIF v_svc_lower IN ('laboratory', 'lab') AND COALESCE(v_config.lab_coverage_percentage, 0) > 0 THEN
            v_coverage_pct := v_config.lab_coverage_percentage;
        ELSIF v_svc_lower IN ('radiology', 'imaging') AND COALESCE(v_config.radiology_coverage_percentage, 0) > 0 THEN
            v_coverage_pct := v_config.radiology_coverage_percentage;
        ELSIF v_svc_lower IN ('pharmacy', 'medication', 'drug') AND COALESCE(v_config.pharmacy_coverage_percentage, 0) > 0 THEN
            v_coverage_pct := v_config.pharmacy_coverage_percentage;
        ELSIF v_svc_lower IN ('procedure', 'surgery', 'surgical') AND COALESCE(v_config.procedure_coverage_percentage, 0) > 0 THEN
            v_coverage_pct := v_config.procedure_coverage_percentage;
        ELSIF v_svc_lower IN ('bed', 'admission', 'ward') AND COALESCE(v_config.bed_coverage_percentage, 0) > 0 THEN
            v_coverage_pct := v_config.bed_coverage_percentage;

        -- Priority 3: Default coverage percentage
        ELSE
            v_coverage_pct := v_config.coverage_percentage;
        END IF;
    ELSIF v_config IS NULL THEN
        -- Fallback for categories not yet in nhis_config
        IF v_normalized IN ('military nhis', 'dhml') THEN
            v_coverage_pct := 100; v_consultation_free := TRUE; v_is_nhis := TRUE;
        ELSIF v_normalized IN ('civilian nhis', 'nhis', 'gifship') THEN
            v_coverage_pct := 90; v_consultation_free := TRUE; v_is_nhis := TRUE;
        ELSIF v_normalized IN ('security services nhis') THEN
            v_coverage_pct := 100; v_consultation_free := TRUE; v_is_nhis := TRUE;
        ELSIF v_normalized IN ('retainership', 'corporate') THEN
            v_coverage_pct := 100; v_consultation_free := TRUE; v_is_nhis := TRUE;
        ELSE
            v_coverage_pct := 0; v_is_nhis := FALSE;
        END IF;
    END IF;

    -- Special rule: Consultation is 100% free for ALL NHIS patients
    IF v_is_nhis AND v_consultation_free AND v_svc_lower = 'consultation' THEN
        v_coverage_pct := 100;
    END IF;

    -- Calculate amounts
    nhis_covered := v_is_nhis;
    nhis_percentage := COALESCE(v_coverage_pct, 0);
    nhis_payable := ROUND(p_gross_amount * COALESCE(v_coverage_pct, 0) / 100, 2);
    patient_payable := p_gross_amount - nhis_payable;

    RETURN NEXT;
END;
$$;


--
-- Name: can_access_encounter_facility(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_access_encounter_facility(p_encounter_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
  SELECT public.can_access_facility(v.facility_id)
  FROM public.visits v
  WHERE v.id = p_encounter_id
  LIMIT 1;
$$;


--
-- Name: can_access_facility(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_access_facility(p_facility_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
  v_role text;
  v_user_facility uuid;
BEGIN
  IF auth.role() = 'service_role' THEN
    RETURN true;
  END IF;

  v_role := public.get_user_role();

  IF v_role IN ('super_admin', 'admin', 'medical_director', 'config_admin') THEN
    RETURN true;
  END IF;

  v_user_facility := public.get_user_facility_id();

  RETURN p_facility_id IS NOT NULL
    AND v_user_facility IS NOT NULL
    AND p_facility_id = v_user_facility;
END;
$$;


--
-- Name: can_access_specialty(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_access_specialty(p_specialty_code character varying) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_role TEXT;
  v_user_specialty TEXT;
BEGIN
  SELECT role::TEXT, specialty_code INTO v_user_role, v_user_specialty
  FROM staff
  WHERE user_id = auth.uid();
  
  -- Admin roles can access ALL specialties
  IF v_user_role IN ('super_admin', 'admin', 'medical_director') THEN
    RETURN TRUE;
  END IF;
  
  -- Clinical staff can only access their assigned specialty
  RETURN v_user_specialty IS NOT NULL AND v_user_specialty = p_specialty_code;
END;
$$;


--
-- Name: can_execute_nhis_service(uuid, character varying, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_execute_nhis_service(p_encounter_id uuid, p_service_type character varying, p_service_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_encounter RECORD;
    v_approval_status nhis_approval_status;
BEGIN
    -- Get encounter
    SELECT * INTO v_encounter FROM visits WHERE id = p_encounter_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('can_execute', FALSE, 'reason', 'Encounter not found');
    END IF;
    
    -- Non-NHIS encounters can always execute
    IF v_encounter.payer_type != 'nhis' OR v_encounter.nhis_verification_status = 'not_applicable' THEN
        RETURN jsonb_build_object('can_execute', TRUE, 'reason', 'Non-NHIS encounter');
    END IF;
    
    -- Check encounter verification status
    IF v_encounter.nhis_verification_status NOT IN ('verified', 'emergency_override') THEN
        RETURN jsonb_build_object(
            'can_execute', FALSE,
            'reason', 'NHIS encounter not verified',
            'status', v_encounter.nhis_verification_status
        );
    END IF;
    
    -- Check service-level approval if required
    CASE p_service_type
        WHEN 'lab_request' THEN
            SELECT nhis_approval_status INTO v_approval_status FROM lab_requests WHERE request_id = p_service_id;
        WHEN 'radiology_request' THEN
            SELECT nhis_approval_status INTO v_approval_status FROM radiology_requests WHERE request_id = p_service_id;
        WHEN 'prescription' THEN
            SELECT nhis_approval_status INTO v_approval_status FROM prescriptions WHERE prescription_id = p_service_id;
        ELSE
            RETURN jsonb_build_object('can_execute', FALSE, 'reason', 'Unknown service type');
    END CASE;
    
    -- Check approval
    IF v_approval_status = 'pending' THEN
        RETURN jsonb_build_object('can_execute', FALSE, 'reason', 'Awaiting NHIS approval');
    ELSIF v_approval_status = 'rejected' THEN
        RETURN jsonb_build_object('can_execute', FALSE, 'reason', 'NHIS approval rejected');
    END IF;
    
    RETURN jsonb_build_object('can_execute', TRUE, 'reason', 'Service approved for execution');
END;
$$;


--
-- Name: can_transition_state(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_transition_state(p_entity_type text, p_from_state text, p_to_state text, p_user_role text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_allowed BOOLEAN;
BEGIN
    SELECT TRUE INTO v_allowed
    FROM state_transition_permissions
    WHERE entity_type = p_entity_type
    AND from_state = p_from_state
    AND to_state = p_to_state
    AND p_user_role = ANY(allowed_roles);
    
    RETURN COALESCE(v_allowed, FALSE);
END;
$$;


--
-- Name: check_billing_order_idempotency(public.idempotency_key_t, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_billing_order_idempotency(p_idempotency_key public.idempotency_key_t, p_idempotency_hash character varying DEFAULT NULL::character varying) RETURNS TABLE(existing_id uuid, hash_mismatch boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    bo.id AS existing_id,
    CASE 
      WHEN p_idempotency_hash IS NOT NULL AND bo.idempotency_hash IS NOT NULL 
           AND bo.idempotency_hash != p_idempotency_hash
      THEN TRUE 
      ELSE FALSE 
    END AS hash_mismatch
  FROM billing_orders bo
  WHERE bo.idempotency_key = p_idempotency_key
  LIMIT 1;
END;
$$;


--
-- Name: check_encounter_access(uuid, uuid, character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_encounter_access(p_encounter_id uuid, p_user_id uuid, p_user_role character varying, p_user_department character varying) RETURNS TABLE(has_access boolean, access_role character varying, access_reason text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_attending_doctor_id UUID;
    v_clinic_name VARCHAR(100);
    v_care_team_role VARCHAR(50);
    v_encounter_status VARCHAR(50);
BEGIN
    -- Get encounter details
    SELECT 
        v.attending_doctor_id,
        c.clinic_name,
        v.status
    INTO v_attending_doctor_id, v_clinic_name, v_encounter_status
    FROM visits v
    LEFT JOIN clinics c ON v.clinic_id::text = c.clinic_id
    WHERE v.id = p_encounter_id;
    
    -- Not found
    IF v_attending_doctor_id IS NULL AND v_clinic_name IS NULL THEN
        RETURN QUERY SELECT false, 'no_access'::VARCHAR, 'Encounter not found';
        RETURN;
    END IF;
    
    -- Super admin always has access
    IF p_user_role = 'super_admin' THEN
        RETURN QUERY SELECT true, 'super_admin'::VARCHAR, 'Super admin access';
        RETURN;
    END IF;
    
    -- Primary doctor
    IF v_attending_doctor_id = p_user_id THEN
        RETURN QUERY SELECT true, 'primary_doctor'::VARCHAR, 'Primary assigned doctor';
        RETURN;
    END IF;
    
    -- Check care team
    SELECT role INTO v_care_team_role
    FROM encounter_care_team
    WHERE encounter_id = p_encounter_id 
      AND staff_id = p_user_id 
      AND is_active = true
      AND (expires_at IS NULL OR expires_at > NOW());
    
    IF v_care_team_role IS NOT NULL THEN
        RETURN QUERY SELECT true, v_care_team_role::VARCHAR, 'Care team member';
        RETURN;
    END IF;
    
    -- Same department doctors (read-only)
    IF p_user_role IN ('doctor', 'medical_director') AND v_clinic_name = p_user_department THEN
        RETURN QUERY SELECT true, 'department_doctor'::VARCHAR, 'Same department - read only';
        RETURN;
    END IF;
    
    -- Medical director can view all
    IF p_user_role = 'medical_director' THEN
        RETURN QUERY SELECT true, 'department_doctor'::VARCHAR, 'Medical director oversight';
        RETURN;
    END IF;
    
    -- Service departments with pending orders
    IF p_user_role = 'lab_technician' THEN
        IF EXISTS (SELECT 1 FROM lab_requests WHERE encounter_id = p_encounter_id) THEN
            RETURN QUERY SELECT true, 'lab_technician'::VARCHAR, 'Has pending lab orders';
            RETURN;
        END IF;
    END IF;
    
    IF p_user_role = 'radiologist' THEN
        IF EXISTS (SELECT 1 FROM radiology_requests WHERE encounter_id = p_encounter_id) THEN
            RETURN QUERY SELECT true, 'radiologist'::VARCHAR, 'Has pending radiology orders';
            RETURN;
        END IF;
    END IF;
    
    IF p_user_role = 'pharmacist' THEN
        IF EXISTS (SELECT 1 FROM prescriptions WHERE encounter_id = p_encounter_id) THEN
            RETURN QUERY SELECT true, 'pharmacist'::VARCHAR, 'Has prescriptions';
            RETURN;
        END IF;
    END IF;
    
    -- Nurses on active encounters
    IF p_user_role = 'nurse' AND v_encounter_status = 'Active' THEN
        RETURN QUERY SELECT true, 'nurse'::VARCHAR, 'Nurse on active encounter';
        RETURN;
    END IF;
    
    -- No access
    RETURN QUERY SELECT false, 'no_access'::VARCHAR, 'No access rights';
END;
$$;


--
-- Name: check_nhis_approval_before_processing(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_nhis_approval_before_processing() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
  blocked_statuses text[] := ARRAY['pending', 'rejected', 'expired'];
  processing_statuses text[];
BEGIN
  -- Define which statuses indicate "processing" for each table
  -- These are statuses that should be blocked if NHIS approval is pending/rejected/expired
  
  IF TG_TABLE_NAME = 'lab_requests' THEN
    processing_statuses := ARRAY['Sample Collected', 'Processing', 'Completed', 'Verified'];
  ELSIF TG_TABLE_NAME = 'radiology_requests' THEN
    processing_statuses := ARRAY['In Progress', 'Completed', 'Reported'];
  ELSIF TG_TABLE_NAME = 'prescriptions' THEN
    processing_statuses := ARRAY['Dispensed', 'Partially Dispensed'];
  ELSIF TG_TABLE_NAME = 'procedure_requests' THEN
    processing_statuses := ARRAY['In Progress', 'Completed'];
  ELSE
    -- Unknown table, allow the operation
    RETURN NEW;
  END IF;
  
  -- Check if trying to transition to a processing status
  -- Note: status might be an enum, cast to text for comparison
  IF NEW.status::text = ANY(processing_statuses) AND 
     (OLD.status IS NULL OR OLD.status::text <> NEW.status::text) THEN
    
    -- Check if NHIS approval is required but not granted
    -- Note: nhis_approval_status is an enum, cast to text for comparison
    IF NEW.nhis_approval_status::text = ANY(blocked_statuses) THEN
      RAISE EXCEPTION 'NHIS pre-authorization required: Cannot process this service. Current NHIS status: %. Please wait for NHIS desk approval.', 
        NEW.nhis_approval_status;
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: check_nhis_approval_for_service(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_nhis_approval_for_service(p_service_type text, p_service_id uuid) RETURNS public.nhis_approval_status
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_status public.nhis_approval_status;
BEGIN
    CASE p_service_type
        WHEN 'lab_request' THEN
            SELECT nhis_approval_status INTO v_status FROM lab_requests WHERE request_id = p_service_id;
        WHEN 'radiology_request' THEN
            SELECT nhis_approval_status INTO v_status FROM radiology_requests WHERE request_id = p_service_id;
        WHEN 'prescription' THEN
            SELECT nhis_approval_status INTO v_status FROM prescriptions WHERE prescription_id = p_service_id;
        WHEN 'clinical_request', 'procedure', 'surgery', 'referral' THEN
            SELECT nhis_approval_status INTO v_status FROM clinical_requests WHERE id = p_service_id;
        WHEN 'dental_procedure' THEN
            SELECT nhis_approval_status INTO v_status FROM dental_procedures WHERE procedure_id = p_service_id;
        WHEN 'dental_prescription' THEN
            SELECT nhis_approval_status INTO v_status FROM dental_prescriptions WHERE prescription_id = p_service_id;
        WHEN 'eye_exam' THEN
            SELECT nhis_approval_status INTO v_status FROM eye_exams WHERE exam_id = p_service_id;
        WHEN 'eye_procedure' THEN
            SELECT nhis_approval_status INTO v_status FROM eye_procedures WHERE procedure_id = p_service_id;
        WHEN 'eye_prescription' THEN
            SELECT nhis_approval_status INTO v_status FROM eye_prescriptions WHERE prescription_id = p_service_id;
        WHEN 'consultation' THEN
            SELECT nhis_approval_status INTO v_status FROM consultations WHERE consultation_id = p_service_id;
        WHEN 'admission' THEN
            SELECT nhis_approval_status INTO v_status FROM admissions WHERE id = p_service_id;
        ELSE
            v_status := NULL;
    END CASE;
    
    RETURN v_status;
END;
$$;


--
-- Name: check_overdue_medications(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_overdue_medications() RETURNS TABLE(schedule_id uuid, encounter_id uuid, patient_id uuid, medication_name character varying, scheduled_time timestamp with time zone, minutes_overdue numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
    -- Update status to overdue for pending meds past window
    UPDATE medication_schedule ms
    SET status = 'overdue',
        updated_at = NOW()
    WHERE ms.status = 'pending'
      AND ms.is_active = TRUE
      AND ms.scheduled_time + (ms.window_minutes || ' minutes')::INTERVAL < NOW();

    -- Return overdue medications
    RETURN QUERY
    SELECT 
        ms.id AS schedule_id,
        ms.encounter_id,
        ms.patient_id,
        ms.medication_name,
        ms.scheduled_time,
        EXTRACT(EPOCH FROM (NOW() - ms.scheduled_time)) / 60 AS minutes_overdue
    FROM medication_schedule ms
    WHERE ms.status = 'overdue'
      AND ms.is_active = TRUE
      AND ms.acknowledged_at IS NULL
    ORDER BY ms.scheduled_time ASC;
END;
$$;


--
-- Name: check_overdue_vital_schedules(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_overdue_vital_schedules() RETURNS TABLE(schedule_id uuid, patient_id character varying, patient_name text, encounter_id uuid, acuity_level public.patient_acuity, minutes_overdue integer, assigned_nurse_id uuid)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
    RETURN QUERY
    WITH overdue_schedules AS (
        UPDATE patient_vital_schedules pvs
        SET 
            is_overdue = TRUE,
            overdue_since = COALESCE(overdue_since, next_vitals_due),
            updated_at = NOW()
        FROM vital_schedule_configs vsc
        WHERE pvs.acuity_level = vsc.acuity_level
        AND pvs.is_active = TRUE
        AND pvs.paused = FALSE
        AND pvs.next_vitals_due IS NOT NULL
        AND NOW() > (pvs.next_vitals_due + (vsc.grace_period_minutes || ' minutes')::INTERVAL)
        AND pvs.is_overdue = FALSE
        RETURNING pvs.*
    )
    SELECT 
        os.id,
        os.patient_id,
        CONCAT(p.first_name, ' ', p.surname)::TEXT,
        os.encounter_id,
        os.acuity_level,
        EXTRACT(EPOCH FROM (NOW() - os.next_vitals_due))::INTEGER / 60,
        os.assigned_nurse_id
    FROM overdue_schedules os
    JOIN patients p ON p.patient_id = os.patient_id;
END;
$$;


