--
-- Name: cleanup_expired_on_call_access(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_expired_on_call_access() RETURNS TABLE(deactivated_count integer, affected_encounters integer)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_deactivated_count INTEGER := 0;
    v_affected_encounters INTEGER := 0;
BEGIN
    -- Deactivate expired care team members
    WITH deactivated AS (
        UPDATE encounter_care_team
        SET is_active = false, updated_at = NOW()
        WHERE expires_at < NOW() 
          AND is_active = true
        RETURNING encounter_id
    )
    SELECT COUNT(*), COUNT(DISTINCT encounter_id)
    INTO v_deactivated_count, v_affected_encounters
    FROM deactivated;
    
    -- Log the cleanup action
    IF v_deactivated_count > 0 THEN
        INSERT INTO encounter_access_logs (
            encounter_id,
            user_id,
            user_role,
            action,
            action_details,
            was_authorized
        )
        SELECT 
            DISTINCT encounter_id,
            staff_id,
            'system',
            'cleanup_expired_access',
            'Deactivated ' || v_deactivated_count || ' expired access grants',
            true
        FROM encounter_care_team
        WHERE expires_at < NOW() AND is_active = false
        LIMIT 1;
    END IF;
    
    RETURN QUERY SELECT v_deactivated_count, v_affected_encounters;
END;
$$;


--
-- Name: cleanup_expired_radiology_images(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_expired_radiology_images(p_retention_days integer DEFAULT 60) RETURNS TABLE(deleted_scan_images integer, deleted_storage_objects integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'storage'
    AS $$
DECLARE
  v_retention_days INTEGER := GREATEST(COALESCE(p_retention_days, 60), 1);
  v_cutoff TIMESTAMPTZ := NOW() - make_interval(days => v_retention_days);
BEGIN
  RETURN QUERY
  WITH candidates AS (
    SELECT
      s.ctid AS row_ref,
      CASE
        WHEN s.image_path IS NULL THEN NULL
        WHEN s.image_path ~* '^https?://' THEN
          split_part(
            regexp_replace(
              s.image_path,
              '^https?://[^/]+/storage/v1/object/(public|sign)/radiology-images/',
              ''
            ),
            '?',
            1
          )
        ELSE split_part(ltrim(s.image_path, '/'), '?', 1)
      END AS object_name
    FROM public.scan_images s
    WHERE COALESCE(s.upload_date, s.created_at) < v_cutoff
  ),
  deleted_objects AS (
    DELETE FROM storage.objects o
    USING candidates c
    WHERE o.bucket_id = 'radiology-images'
      AND c.object_name IS NOT NULL
      AND c.object_name <> ''
      AND o.name = c.object_name
    RETURNING o.id
  ),
  deleted_rows AS (
    DELETE FROM public.scan_images s
    USING candidates c
    WHERE s.ctid = c.row_ref
    RETURNING 1
  )
  SELECT
    COALESCE((SELECT COUNT(*)::INTEGER FROM deleted_rows), 0) AS deleted_scan_images,
    COALESCE((SELECT COUNT(*)::INTEGER FROM deleted_objects), 0) AS deleted_storage_objects;
END;
$$;


--
-- Name: cleanup_old_queue_counters(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_old_queue_counters(days_to_keep integer DEFAULT 7) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_deleted integer;
BEGIN
    DELETE FROM public.queue_daily_counters
    WHERE counter_date < (now() AT TIME ZONE 'Africa/Lagos')::date - days_to_keep;
    
    GET DIAGNOSTICS v_deleted = ROW_COUNT;
    RETURN v_deleted;
END;
$$;


--
-- Name: cleanup_past_on_call_schedules(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_past_on_call_schedules() RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    UPDATE on_call_schedule
    SET is_active = false, updated_at = NOW()
    WHERE end_time < NOW() 
      AND is_active = true;
    
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$;


--
-- Name: cleanup_stale_queue_entries(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_stale_queue_entries(p_stale_hours integer DEFAULT 4) RETURNS TABLE(reset_count integer, visit_ids uuid[], message text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_stale_cutoff  TIMESTAMPTZ;
  v_reset_count   INTEGER;
  v_visit_ids     UUID[];
BEGIN
  v_stale_cutoff := now() - (p_stale_hours || ' hours')::INTERVAL;

  -- Collect stale entries before updating (for audit/return)
  SELECT
    array_agg(visit_id),
    COUNT(*)::INTEGER
  INTO v_visit_ids, v_reset_count
  FROM queue
  WHERE status = 'In Progress'
    AND started_at < v_stale_cutoff;

  IF v_reset_count = 0 THEN
    RETURN QUERY SELECT 0, ARRAY[]::UUID[], 'No stale queue entries found.'::TEXT;
    RETURN;
  END IF;

  -- Reset stale entries back to Waiting
  UPDATE queue
  SET
    status     = 'Waiting',
    assigned_to = NULL,
    started_at  = NULL,
    notes       = COALESCE(notes, '') ||
                  ' [AUTO-RESET: Stale In Progress entry reset at ' ||
                  to_char(now(), 'YYYY-MM-DD HH24:MI') || ']',
    updated_at  = now()
  WHERE status = 'In Progress'
    AND started_at < v_stale_cutoff;

  -- Log to nhis_audit_log equivalent — clinical_audit_log if it exists
  INSERT INTO audit_logs (
    category,
    action,
    resource_type,
    resource_id,
    description,
    metadata,
    created_at
  )
  SELECT
    'workflow'::audit_category,
    'update'::audit_action,
    'queue',
    v.id::TEXT,
    format('Stale queue entry auto-reset: visit %s was In Progress for >%s hours',
           v.id, p_stale_hours),
    jsonb_build_object(
      'reset_reason', 'stale_in_progress',
      'threshold_hours', p_stale_hours,
      'cutoff_time', v_stale_cutoff
    ),
    now()
  FROM unnest(v_visit_ids) AS v(id)
  ON CONFLICT DO NOTHING;

  RETURN QUERY SELECT
    v_reset_count,
    COALESCE(v_visit_ids, ARRAY[]::UUID[]),
    format('%s stale queue entr%s reset to Waiting.',
           v_reset_count,
           CASE WHEN v_reset_count = 1 THEN 'y' ELSE 'ies' END)::TEXT;
END;
$$;


--
-- Name: close_encounter(uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_encounter(p_encounter_id uuid, p_closed_by uuid, p_final_diagnosis text DEFAULT NULL::text, p_discharge_notes text DEFAULT NULL::text, p_closed_reason text DEFAULT 'Normal discharge'::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_result JSONB;
    v_current_status TEXT;
    v_user_role TEXT;
BEGIN
    -- Get current status
    SELECT status::TEXT INTO v_current_status
    FROM visits
    WHERE visit_id = p_encounter_id;
    
    IF v_current_status IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Encounter not found');
    END IF;
    
    IF v_current_status IN ('Completed', 'Closed', 'Cancelled') THEN
        RETURN jsonb_build_object('success', false, 'error', 'Encounter is already closed');
    END IF;
    
    -- Get user role
    SELECT role::TEXT INTO v_user_role
    FROM staff
    WHERE staff_id = p_closed_by;
    
    -- Only doctors, nurse managers, and admins can close encounters
    IF v_user_role NOT IN ('doctor', 'nurse', 'admin', 'super_admin', 'medical_director') THEN
        RETURN jsonb_build_object('success', false, 'error', 'Unauthorized to close encounter');
    END IF;
    
    -- Close the encounter
    UPDATE visits
    SET 
        status = 'Closed',
        current_stage = 'encounter_closed',
        end_time = NOW(),
        discharge_date = NOW(),
        discharge_notes = COALESCE(p_discharge_notes, discharge_notes),
        closed_by = p_closed_by,
        closed_reason = p_closed_reason,
        stage_updated_at = NOW(),
        stage_history = COALESCE(stage_history, '[]'::JSONB) || jsonb_build_object(
            'stage', 'encounter_closed',
            'timestamp', NOW(),
            'performed_by', p_closed_by,
            'notes', 'Encounter closed: ' || p_closed_reason
        )
    WHERE visit_id = p_encounter_id;
    
    -- Log the closure
    INSERT INTO clinical_audit_log (
        encounter_id, patient_id, action, entity_type, entity_id,
        new_value, performed_by, notes
    )
    SELECT 
        visit_id, patient_id, 'CLOSE', 'encounter', visit_id,
        jsonb_build_object(
            'final_diagnosis', p_final_diagnosis,
            'discharge_notes', p_discharge_notes,
            'closed_reason', p_closed_reason
        ),
        p_closed_by,
        'Encounter closed'
    FROM visits
    WHERE visit_id = p_encounter_id;
    
    RETURN jsonb_build_object(
        'success', true,
        'encounter_id', p_encounter_id,
        'status', 'Closed',
        'closed_at', NOW()
    );
END;
$$;


--
-- Name: complete_specialty_session(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_specialty_session(p_queue_id uuid, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
  v_staff_id uuid;
  v_staff_role text;
BEGIN
  SELECT id, role::text INTO v_staff_id, v_staff_role
  FROM staff WHERE user_id = auth.uid();
  
  IF v_staff_id IS NULL THEN
    RAISE EXCEPTION 'Staff not found for current user';
  END IF;
  
  -- Try strict match first: assigned to current user and In Progress
  UPDATE queue SET
    status = 'Completed',
    completed_at = now(),
    updated_at = now()
  WHERE id = p_queue_id
    AND assigned_to = v_staff_id
    AND status = 'In Progress'
  RETURNING jsonb_build_object(
    'queue_id', id,
    'status', status,
    'completed_at', completed_at
  ) INTO v_result;
  
  -- If strict match failed, try flexible match:
  -- Allow completing entries that are Waiting/Called/In Progress
  -- and either unassigned or assigned to the current user.
  -- This handles cases where patients were routed from Nursing
  -- without going through start_specialty_session.
  IF v_result IS NULL THEN
    UPDATE queue SET
      status = 'Completed',
      completed_at = now(),
      assigned_to = COALESCE(assigned_to, v_staff_id),
      updated_at = now()
    WHERE id = p_queue_id
      AND status IN ('Waiting', 'Called', 'In Progress')
      AND (
        assigned_to IS NULL 
        OR assigned_to = v_staff_id
        OR v_staff_role IN ('super_admin', 'admin', 'medical_director')
      )
    RETURNING jsonb_build_object(
      'queue_id', id,
      'status', status,
      'completed_at', completed_at
    ) INTO v_result;
  END IF;
  
  IF v_result IS NULL THEN
    RAISE EXCEPTION 'Queue entry not found, not assigned to you, or not in progress';
  END IF;
  
  RETURN v_result;
END;
$$;


--
-- Name: create_direct_booking(uuid, text, text, text, uuid, date, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_direct_booking(p_patient_id uuid, p_urgency text, p_clinical_reason text, p_notes text, p_target_department_id uuid, p_appointment_date date, p_appointment_time text, p_requesting_doctor_id uuid, p_created_by uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_visit_id    uuid;
  v_request_id  uuid;
BEGIN
  -- Step 1: Create a placeholder visit/encounter record.
  -- visit_id (varchar) is NOT NULL with no default, so we generate a compact unique value.
  -- status='Scheduled' distinguishes it from live encounters ('Active').
  INSERT INTO public.visits (
    visit_id,
    patient_id,
    visit_type,
    status,
    start_time,
    encounter_date,
    payer_type,
    registered_by
  ) VALUES (
    'BOOKING-' || upper(substr(extensions.uuid_generate_v4()::text, 1, 8)),
    p_patient_id,
    'Appointment',
    'Scheduled',
    COALESCE(
      (p_appointment_date::text || ' ' || COALESCE(p_appointment_time, '08:00'))::timestamp with time zone,
      now()
    ),
    p_appointment_date,
    'private',
    p_created_by
  )
  RETURNING id INTO v_visit_id;

  -- Step 2: Create the clinical_request linked to the placeholder visit.
  INSERT INTO public.clinical_requests (
    patient_id,
    encounter_id,
    request_type,
    urgency,
    clinical_reason,
    notes,
    target_department_id,
    status,
    referral_workflow_status,
    appointment_date,
    appointment_time,
    requesting_doctor_id,
    appointment_booked_by,
    appointment_booked_at,
    created_by
  ) VALUES (
    p_patient_id,
    v_visit_id,
    'Referral',
    p_urgency,
    p_clinical_reason,
    p_notes,
    p_target_department_id,
    'Approved',
    'Appointment_Booked',
    p_appointment_date,
    p_appointment_time,
    p_requesting_doctor_id,
    p_requesting_doctor_id,
    now(),
    p_created_by
  )
  RETURNING id INTO v_request_id;

  RETURN v_request_id;
END;
$$;


--
-- Name: create_enum_if_not_exists(text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_enum_if_not_exists(enum_name text, enum_values text[]) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$

BEGIN

    IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = enum_name) THEN

        EXECUTE format('CREATE TYPE %I AS ENUM (%s)', enum_name, array_to_string(array(SELECT quote_literal(x) FROM unnest(enum_values) x), ', '));

    END IF;

END;

$$;


--
-- Name: create_notification(character varying, character varying, text, character varying, uuid, character varying, character varying, uuid, character varying, character varying, uuid, character varying, character varying, uuid, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_notification(p_type character varying, p_title character varying, p_message text, p_priority character varying DEFAULT 'normal'::character varying, p_target_user_id uuid DEFAULT NULL::uuid, p_target_role character varying DEFAULT NULL::character varying, p_target_department character varying DEFAULT NULL::character varying, p_encounter_id uuid DEFAULT NULL::uuid, p_patient_id character varying DEFAULT NULL::character varying, p_reference_type character varying DEFAULT NULL::character varying, p_reference_id uuid DEFAULT NULL::uuid, p_action_url character varying DEFAULT NULL::character varying, p_action_label character varying DEFAULT NULL::character varying, p_created_by uuid DEFAULT NULL::uuid, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_notification_id UUID;
BEGIN
    INSERT INTO notifications (
        type, title, message, priority,
        target_user_id, target_role, target_department,
        encounter_id, patient_id,
        reference_type, reference_id,
        action_url, action_label,
        created_by, expires_at, metadata
    ) VALUES (
        p_type::notification_type, p_title, p_message, p_priority::notification_priority,
        p_target_user_id, p_target_role, p_target_department,
        p_encounter_id, p_patient_id,
        p_reference_type, p_reference_id,
        p_action_url, p_action_label,
        p_created_by, p_expires_at, p_metadata
    ) RETURNING id INTO v_notification_id;
    
    RETURN v_notification_id;
END;
$$;


--
-- Name: create_queue_ticket(text, uuid, uuid, uuid, uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_queue_ticket(p_dept text, p_patient_id uuid, p_visit_id uuid DEFAULT NULL::uuid, p_encounter_id uuid DEFAULT NULL::uuid, p_clinic_id uuid DEFAULT NULL::uuid, p_priority text DEFAULT 'Normal'::text, p_notes text DEFAULT NULL::text, p_created_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_ticket_number integer;
    v_queue_id uuid;
    v_today_lagos date;
    v_result jsonb;
    v_location queue_location;
    v_priority priority;
    v_enc_id uuid;
    v_completed_count integer;
BEGIN
    -- Get today's date in Africa/Lagos timezone
    v_today_lagos := (now() AT TIME ZONE 'Africa/Lagos')::date;
    
    -- Resolve the encounter ID (prefer p_encounter_id, fall back to p_visit_id)
    v_enc_id := COALESCE(p_encounter_id, p_visit_id);
    
    -- Cast text department to queue_location enum
    BEGIN
        v_location := p_dept::queue_location;
    EXCEPTION WHEN invalid_text_representation THEN
        v_location := 'Nursing'::queue_location;
    END;
    
    -- Cast text priority to priority enum
    BEGIN
        v_priority := COALESCE(p_priority, 'Normal')::priority;
    EXCEPTION WHEN invalid_text_representation THEN
        v_priority := 'Normal'::priority;
    END;
    
    -- ======================================================================
    -- DEDUPLICATION: Complete any existing active queue entries for this
    -- encounter at the SAME location. This prevents the unique index
    -- idx_queue_encounter_location_active from blocking the insert.
    -- ======================================================================
    IF v_enc_id IS NOT NULL THEN
        UPDATE queue
        SET status = 'Completed',
            completed_at = now()
        WHERE encounter_id = v_enc_id
          AND location = v_location
          AND status IN ('Waiting', 'Called', 'In Progress');
        
        GET DIAGNOSTICS v_completed_count = ROW_COUNT;
        IF v_completed_count > 0 THEN
            RAISE NOTICE 'create_queue_ticket: completed % existing active entries for encounter % at %',
                v_completed_count, v_enc_id, p_dept;
        END IF;
    END IF;
    
    -- Acquire advisory lock for this department+date combination to prevent race conditions
    PERFORM pg_advisory_xact_lock(hashtext('queue_counter_' || p_dept || '_' || v_today_lagos::text));
    
    -- Atomic upsert to get next ticket number
    INSERT INTO public.queue_daily_counters (department, counter_date, last_ticket_number)
    VALUES (p_dept, v_today_lagos, 1)
    ON CONFLICT (department, counter_date)
    DO UPDATE SET 
        last_ticket_number = queue_daily_counters.last_ticket_number + 1,
        updated_at = now()
    RETURNING last_ticket_number INTO v_ticket_number;
    
    -- Generate queue ID
    v_queue_id := extensions.uuid_generate_v4();
    
    -- Insert queue entry with the ticket number
    INSERT INTO public.queue (
        id,
        patient_id,
        visit_id,
        encounter_id,
        clinic_id,
        location,
        ticket_number,
        priority,
        status,
        notes,
        created_at
    ) VALUES (
        v_queue_id,
        p_patient_id,
        COALESCE(p_visit_id, p_encounter_id),
        p_encounter_id,
        p_clinic_id,
        v_location,
        v_ticket_number::text,
        v_priority,
        'Waiting',
        p_notes,
        now()
    );
    
    -- Build result JSON
    v_result := jsonb_build_object(
        'success', true,
        'queue_id', v_queue_id,
        'ticket_number', v_ticket_number,
        'department', p_dept,
        'patient_id', p_patient_id,
        'encounter_id', p_encounter_id,
        'status', 'Waiting',
        'created_at', now()
    );
    
    RETURN v_result;
    
EXCEPTION WHEN OTHERS THEN
    -- Return error info
    RETURN jsonb_build_object(
        'success', false,
        'error', SQLERRM,
        'error_detail', SQLSTATE
    );
END;
$$;


--
-- Name: create_referral_encounter(uuid, uuid, uuid, character varying, character varying, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_referral_encounter(p_referral_id uuid, p_clinic_id uuid, p_attending_doctor_id uuid, p_visit_type character varying DEFAULT 'Follow-up'::character varying, p_priority character varying DEFAULT 'Normal'::character varying, p_created_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_referral RECORD;
    v_clinic RECORD;
    v_new_encounter_id UUID;
    v_encounter_number VARCHAR;
    v_visit_id VARCHAR;
    v_today_prefix VARCHAR;
    v_next_seq INT;
    v_target_location VARCHAR;
BEGIN
    -- Get referral details
    SELECT 
        cr.*,
        p.emr_number,
        p.insurance_type,
        rd.first_name AS ref_doc_first,
        rd.last_name AS ref_doc_last
    INTO v_referral
    FROM clinical_requests cr
    JOIN patients p ON cr.patient_id = p.id
    LEFT JOIN staff rd ON cr.requesting_doctor_id = rd.id
    WHERE cr.id = p_referral_id
      AND cr.request_type = 'Referral';
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Referral not found');
    END IF;
    
    -- Check NHIS approval status for NHIS patients
    IF v_referral.insurance_type IN ('Military_NHIS', 'Civilian_NHIS', 'GIFSHIP', 'DHML') THEN
        IF v_referral.nhis_approval_status != 'approved' THEN
            RETURN jsonb_build_object('success', false, 'error', 'NHIS approval required before creating encounter');
        END IF;
    END IF;
    
    -- Check referral hasn't already been converted
    IF v_referral.referral_encounter_id IS NOT NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Referral already converted to encounter: ' || v_referral.referral_encounter_id);
    END IF;
    
    -- Get clinic info for specialty detection
    SELECT * INTO v_clinic FROM clinics WHERE id = p_clinic_id;
    
    -- Determine target location based on specialty_module
    v_target_location := CASE v_referral.specialty_module
        WHEN 'dental' THEN 'Dental'
        WHEN 'ophthalmology' THEN 'Eye Clinic'
        WHEN 'physiotherapy' THEN 'Physiotherapy'
        WHEN 'surgery' THEN 'Surgery'
        WHEN 'ent' THEN 'ENT'
        WHEN 'cardiology' THEN 'Cardiology'
        WHEN 'orthopedics' THEN 'Orthopedics'
        ELSE COALESCE(v_clinic.clinic_name, 'Consultation')
    END;
    
    -- Generate encounter number
    SELECT 'ENC-' || TO_CHAR(CURRENT_DATE, 'YYYYMMDD') || '-' || 
           LPAD((COALESCE(MAX(CAST(SUBSTRING(encounter_number FROM 14) AS INTEGER)), 0) + 1)::text, 4, '0')
    INTO v_encounter_number
    FROM visits
    WHERE encounter_number LIKE 'ENC-' || TO_CHAR(CURRENT_DATE, 'YYYYMMDD') || '-%';
    
    -- Generate visit_id
    v_today_prefix := 'S-' || TO_CHAR(CURRENT_DATE, 'YYYYMMDD') || '-';
    SELECT COALESCE(MAX(CAST(SUBSTRING(visit_id FROM LENGTH(v_today_prefix) + 1) AS INTEGER)), 0) + 1
    INTO v_next_seq
    FROM visits
    WHERE visit_id LIKE v_today_prefix || '%';
    v_visit_id := v_today_prefix || LPAD(v_next_seq::text, 5, '0');
    
    -- Create the new encounter
    INSERT INTO visits (
        patient_id,
        visit_id,
        clinic_id,
        attending_doctor_id,
        visit_type,
        priority,
        status,
        encounter_number,
        encounter_date,
        payment_category,
        insurance_type,
        nhis_verification_status,
        
        -- Referral-specific fields
        is_referral_encounter,
        source_referral_id,
        referring_doctor_id,
        referring_clinic_id,
        referral_reason,
        referral_clinical_notes,
        
        -- Chief complaint
        chief_complaint,
        
        created_at,
        updated_at
    ) VALUES (
        v_referral.patient_id,
        v_visit_id,
        p_clinic_id,
        p_attending_doctor_id,
        p_visit_type,
        p_priority,
        'Active',
        v_encounter_number,
        CURRENT_DATE,
        CASE WHEN v_referral.insurance_type IN ('Military_NHIS', 'Civilian_NHIS', 'GIFSHIP', 'DHML') 
             THEN 'NHIS'::payment_method ELSE 'Cash'::payment_method END,
        v_referral.insurance_type,
        'verified', -- Already NHIS approved
        
        TRUE,
        p_referral_id,
        v_referral.requesting_doctor_id,
        v_referral.source_clinic_id,
        v_referral.clinical_reason,
        v_referral.notes,
        
        'Referral from ' || COALESCE(v_referral.ref_doc_first || ' ' || v_referral.ref_doc_last, 'Unknown') || 
        ': ' || COALESCE(v_referral.clinical_reason, 'See referral notes'),
        
        NOW(),
        NOW()
    )
    RETURNING id INTO v_new_encounter_id;
    
    -- Update the referral with the new encounter ID
    UPDATE clinical_requests
    SET referral_encounter_id = v_new_encounter_id,
        referral_workflow_status = 'Encounter_Created',
        status = 'Approved',
        approved_at = NOW(),
        approved_by = p_created_by,
        updated_at = NOW()
    WHERE id = p_referral_id;
    
    -- ====================================================================
    -- FIX: Route to SPECIALTY CLINIC QUEUE directly (already NHIS approved)
    -- ====================================================================
    INSERT INTO queue (
        patient_id,
        visit_id,
        encounter_id,
        clinic_id,
        ticket_number,
        location,
        priority,
        status,
        notes,
        created_at,
        updated_at
    ) VALUES (
        v_referral.patient_id,
        v_new_encounter_id,
        v_new_encounter_id,
        p_clinic_id,
        'Q-' || LPAD((floor(random() * 9000) + 1000)::text, 4, '0'),
        v_target_location, -- Route to Specialty Clinic!
        p_priority,
        'Waiting',
        'Internal Referral - ' || v_target_location || ' appointment',
        NOW(),
        NOW()
    );
    
    RETURN jsonb_build_object(
        'success', true,
        'encounter_id', v_new_encounter_id,
        'encounter_number', v_encounter_number,
        'target_location', v_target_location,
        'message', 'Encounter created. Patient routed to ' || v_target_location || ' queue.'
    );
END;
$$;


--
-- Name: create_ssi_surveillance_schedule(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_ssi_surveillance_schedule() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
    IF NEW.status = 'Completed' 
       AND NEW.wound_classification IS NOT NULL 
       AND OLD.status != 'Completed' THEN
        -- Create wound care schedule
        INSERT INTO hygiene_care_schedules (
            encounter_id, patient_id, admission_id,
            activity_code, activity_name, frequency,
            start_date, linked_surgery_id, created_by
        )
        VALUES (
            NEW.encounter_id, NEW.patient_id, NEW.admission_id,
            'WOUND_SSI_CHECK', 'Surgical Site Inspection', 'twice_daily',
            CURRENT_DATE, NEW.id, COALESCE(NEW.updated_by, NEW.created_by)
        )
        ON CONFLICT DO NOTHING;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: create_staff_user(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_staff_user(email_address text, password text, first_name text, last_name text, user_role text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    new_user_id UUID;
    current_user_role TEXT;
    v_instance_id UUID;
BEGIN
    -- 1. Check if the executing user is an admin
    SELECT role INTO current_user_role
    FROM staff
    WHERE user_id = auth.uid();

    IF current_user_role NOT IN ('super_admin', 'admin', 'medical_director', 'config_admin') THEN
        RAISE EXCEPTION 'Access Denied: Only admins can create new users.';
    END IF;

    -- Get instance_id from current user or default
    SELECT instance_id INTO v_instance_id FROM auth.users WHERE id = auth.uid();
    IF v_instance_id IS NULL THEN
        v_instance_id := '00000000-0000-0000-0000-000000000000';
    END IF;

    -- 2. Generate new UUID using gen_random_uuid()
    new_user_id := gen_random_uuid();

    -- 3. Insert into auth.users
    INSERT INTO auth.users (
        instance_id,
        id,
        aud,
        role,
        email,
        encrypted_password,
        email_confirmed_at,
        raw_app_meta_data,
        raw_user_meta_data,
        created_at,
        updated_at,
        confirmation_token,
        recovery_token,
        is_super_admin
    ) VALUES (
        v_instance_id,
        new_user_id,
        'authenticated',
        'authenticated',
        email_address,
        crypt(password, gen_salt('bf')),
        NOW(),
        jsonb_build_object('provider', 'email', 'providers', ARRAY['email']),
        jsonb_build_object(
            'full_name', first_name || ' ' || last_name,
            'role', user_role
        ),
        NOW(),
        NOW(),
        NULL, -- Use NULL instead of empty string
        NULL, -- Use NULL instead of empty string
        FALSE
    );

    -- 4. Insert into auth.identities (Required for Supabase Auth to work correctly with email provider)
    INSERT INTO auth.identities (
        id,
        user_id,
        identity_data,
        provider,
        provider_id,
        last_sign_in_at,
        created_at,
        updated_at
    ) VALUES (
        gen_random_uuid(),
        new_user_id,
        jsonb_build_object(
            'sub', new_user_id,
            'email', email_address,
            'email_verified', true,
            'phone_verified', false
        ),
        'email',
        new_user_id::text,
        NOW(),
        NOW(),
        NOW()
    );

    RETURN new_user_id;
END;
$$;


--
-- Name: create_template_version(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_template_version(p_template_id uuid, p_change_notes text DEFAULT NULL::text, p_created_by uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
  v_new_template_id uuid;
  v_old_template RECORD;
  v_new_version integer;
BEGIN
  -- Get the current template
  SELECT * INTO v_old_template 
  FROM specialty_templates 
  WHERE id = p_template_id;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Template not found: %', p_template_id;
  END IF;
  
  -- Calculate new version number
  SELECT COALESCE(MAX(version), 0) + 1 INTO v_new_version
  FROM specialty_templates
  WHERE specialty_code = v_old_template.specialty_code
    AND opd_type = v_old_template.opd_type;
  
  -- Deactivate current active template
  UPDATE specialty_templates 
  SET is_active = false, 
      deprecated_at = NOW()
  WHERE specialty_code = v_old_template.specialty_code
    AND opd_type = v_old_template.opd_type
    AND is_active = true;
  
  -- Create new template version
  INSERT INTO specialty_templates (
    specialty_code,
    specialty_name,
    description,
    opd_type,
    icon_name,
    color_class,
    is_active,
    display_order,
    version,
    published_at,
    created_by,
    change_notes
  )
  VALUES (
    v_old_template.specialty_code,
    v_old_template.specialty_name,
    v_old_template.description,
    v_old_template.opd_type,
    v_old_template.icon_name,
    v_old_template.color_class,
    true,
    v_old_template.display_order,
    v_new_version,
    NOW(),
    p_created_by,
    p_change_notes
  )
  RETURNING id INTO v_new_template_id;
  
  -- Copy sections with their fields
  INSERT INTO specialty_template_sections (
    template_id,
    section_code,
    section_name,
    description,
    display_order,
    is_required,
    is_collapsible,
    default_expanded,
    fields
  )
  SELECT 
    v_new_template_id,
    section_code,
    section_name,
    description,
    display_order,
    is_required,
    is_collapsible,
    default_expanded,
    fields
  FROM specialty_template_sections
  WHERE template_id = p_template_id;
  
  RETURN v_new_template_id;
END;
$$;


--
-- Name: create_vital_schedule_on_admission(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_vital_schedule_on_admission() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
    -- Only create schedule for inpatient/emergency encounters
    -- visit_type values: 'New Visit', 'Follow-Up', 'Emergency', 'Inpatient', etc.
    IF NEW.visit_type IN ('Inpatient', 'Emergency', 'Admission') AND NEW.status = 'Active' THEN
        INSERT INTO patient_vital_schedules (
            patient_id,
            encounter_id,
            acuity_level,
            next_vitals_due,
            created_by
        ) VALUES (
            NEW.patient_id,
            NEW.id,
            CASE 
                WHEN NEW.visit_type = 'Emergency' THEN 'high'::patient_acuity
                ELSE 'medium'::patient_acuity
            END,
            NOW() + INTERVAL '30 minutes',  -- First vitals due in 30 min
            NEW.attending_doctor_id
        )
        ON CONFLICT (patient_id, encounter_id) DO NOTHING;
    END IF;
    
    RETURN NEW;
END;
$$;


--
-- Name: ctt_set_tsv(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ctt_set_tsv() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.tsv := to_tsvector(
        'english'::regconfig,
        coalesce(NEW.display_name, '') || ' ' ||
        coalesce(NEW.description, '') || ' ' ||
        coalesce(array_to_string(NEW.search_keywords, ' '), '')
    );
    RETURN NEW;
END;
$$;


--
-- Name: ctt_set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ctt_set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN NEW.updated_at = NOW(); RETURN NEW; END;
$$;


--
-- Name: decrement_batch_stock(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decrement_batch_stock(p_batch_id uuid, p_quantity numeric) RETURNS TABLE(new_quantity numeric, new_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_remaining NUMERIC;
    v_status TEXT;
BEGIN
    UPDATE drug_batches
    SET quantity_remaining = quantity_remaining - p_quantity,
        status = CASE
            WHEN quantity_remaining - p_quantity <= 0 THEN 'depleted'
            ELSE status
        END,
        updated_at = now()
    WHERE batch_id = p_batch_id
      AND quantity_remaining >= p_quantity
    RETURNING quantity_remaining, status INTO v_remaining, v_status;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Insufficient batch stock or batch not found: %', p_batch_id;
    END IF;

    new_quantity := v_remaining;
    new_status := v_status;
    RETURN NEXT;
END;
$$;


--
-- Name: decrement_drug_stock(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decrement_drug_stock(p_drug_id uuid, p_quantity integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
  UPDATE drug_catalogue
  SET stock_quantity = GREATEST(stock_quantity - p_quantity, 0),
      updated_at = NOW()
  WHERE id = p_drug_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Drug not found: %', p_drug_id;
  END IF;
END;
$$;


--
-- Name: decrement_drug_stock(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decrement_drug_stock(p_drug_id uuid, p_quantity numeric) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_new_qty NUMERIC;
    v_drug_name TEXT;
BEGIN
    -- Atomic: lock row, check, decrement in one statement
    UPDATE drug_catalogue
    SET stock_quantity = stock_quantity - p_quantity,
        updated_at = now()
    WHERE id = p_drug_id
      AND stock_quantity >= p_quantity
    RETURNING stock_quantity, name INTO v_new_qty, v_drug_name;

    IF NOT FOUND THEN
        -- Determine if drug doesn't exist or insufficient stock
        SELECT name INTO v_drug_name FROM drug_catalogue WHERE id = p_drug_id;
        IF v_drug_name IS NULL THEN
            RAISE EXCEPTION 'Drug not found: %', p_drug_id;
        ELSE
            RAISE EXCEPTION 'Insufficient stock for "%". Requested: %, Available stock is less.', v_drug_name, p_quantity;
        END IF;
    END IF;

    RETURN v_new_qty;
END;
$$;


--
-- Name: dismiss_notification(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dismiss_notification(p_notification_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
    UPDATE notifications
    SET is_dismissed = TRUE, dismissed_at = NOW()
    WHERE id = p_notification_id
    AND (target_user_id = p_user_id OR target_user_id IS NULL);
    
    RETURN FOUND;
END;
$$;


--
-- Name: enforce_clinical_staff_specialty(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_clinical_staff_specialty() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
  -- Clinical roles MUST have specialty_code when active
  -- Note: All specialists use role='doctor' with specialty_code differentiating them
  IF NEW.role = 'doctor'
     AND NEW.is_active = true
     AND NEW.specialty_code IS NULL
  THEN
    -- Allow insert but log warning - can be made strict later
    RAISE WARNING 'Doctor staff member should have a specialty_code assignment for user %', NEW.id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_consultation_sequence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_consultation_sequence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
    -- Validate state transitions
    IF NEW.consultation_state != OLD.consultation_state THEN
        CASE NEW.consultation_state
            WHEN 'Complaints_Entered' THEN
                IF OLD.consultation_state != 'Patient_Called' THEN
                    RAISE EXCEPTION 'Cannot enter complaints before patient is called';
                END IF;
                NEW.complaints_entered_at = NOW();
            WHEN 'Clinical_Notes_Entered' THEN
                IF OLD.consultation_state NOT IN ('Patient_Called', 'Complaints_Entered') THEN
                    RAISE EXCEPTION 'Cannot enter clinical notes before complaints';
                END IF;
                NEW.notes_entered_at = NOW();
            WHEN 'Diagnosis_Confirmed' THEN
                IF OLD.consultation_state NOT IN ('Complaints_Entered', 'Clinical_Notes_Entered') THEN
                    RAISE EXCEPTION 'Cannot confirm diagnosis before clinical notes';
                END IF;
                NEW.diagnosis_confirmed_at = NOW();
            WHEN 'Treatment_Plan_Created' THEN
                IF OLD.consultation_state != 'Diagnosis_Confirmed' THEN
                    RAISE EXCEPTION 'Cannot create treatment plan before diagnosis';
                END IF;
                NEW.treatment_plan_created_at = NOW();
            WHEN 'Orders_Placed' THEN
                IF OLD.consultation_state NOT IN ('Diagnosis_Confirmed', 'Treatment_Plan_Created') THEN
                    RAISE EXCEPTION 'Cannot place orders before diagnosis';
                END IF;
                NEW.orders_placed_at = NOW();
            WHEN 'Completed' THEN
                NEW.completed_at = NOW();
            ELSE
                -- Allow transition
        END CASE;
        
        -- Update state history
        NEW.state_history = OLD.state_history || jsonb_build_object(
            'from_state', OLD.consultation_state,
            'to_state', NEW.consultation_state,
            'changed_at', NOW(),
            'changed_by', current_setting('app.current_user_id', true)
        );
    END IF;
    
    RETURN NEW;
END;
$$;


--
-- Name: enforce_critical_lab_escalation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_critical_lab_escalation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF COALESCE(NEW.is_critical, false)
     AND lower(COALESCE(NEW.workflow_status, '')) IN ('approved', 'released')
     AND NEW.critical_notified_at IS NULL THEN
    RAISE EXCEPTION 'Critical lab results must include a notification timestamp before approval or release';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_nhis_billing_order(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_nhis_billing_order() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_insurance_type VARCHAR;
    v_service_type VARCHAR;
    v_calc RECORD;
BEGIN
    -- Only enforce on orders linked to an encounter
    IF NEW.encounter_id IS NULL THEN
        RETURN NEW;
    END IF;

    -- Get insurance type from the visit/encounter
    SELECT v.insurance_type::TEXT INTO v_insurance_type
    FROM visits v
    WHERE v.id = NEW.encounter_id;

    -- If no visit found or no insurance type, skip
    IF v_insurance_type IS NULL OR v_insurance_type = '' THEN
        RETURN NEW;
    END IF;

    -- Determine service type from source_module
    v_service_type := CASE
        WHEN NEW.source_module::TEXT = 'consultation' THEN 'Consultation'
        ELSE COALESCE(NEW.source_module::TEXT, 'Other')
    END;

    -- Calculate NHIS amounts using the DB function (reads nhis_config)
    SELECT * INTO v_calc
    FROM calculate_nhis_amounts(
        COALESCE(NEW.total_amount, 0),
        v_insurance_type,
        v_service_type
    );

    -- Apply calculated NHIS fields
    NEW.nhis_covered := v_calc.nhis_covered;
    NEW.nhis_percentage := v_calc.nhis_percentage;
    NEW.nhis_payable := v_calc.nhis_payable;
    NEW.patient_payable := v_calc.patient_payable;

    -- For 100% NHIS coverage: auto-set status and zero out balance
    IF v_calc.nhis_covered AND v_calc.nhis_percentage >= 100 THEN
        NEW.status := 'Paid_NHIS';
        NEW.payment_method := 'NHIS';
        NEW.balance_amount := 0;
        NEW.net_amount := COALESCE(NEW.total_amount, 0);
    ELSIF v_calc.nhis_covered THEN
        -- Partial coverage: patient balance is their portion
        NEW.balance_amount := v_calc.patient_payable;
        NEW.net_amount := COALESCE(NEW.total_amount, 0);
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: enforce_patient_duplicate_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_patient_duplicate_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_conflict_patient_id text;
BEGIN
  IF NEW.nhis_number IS NOT NULL AND btrim(NEW.nhis_number) <> '' THEN
    SELECT p.patient_id
    INTO v_conflict_patient_id
    FROM public.patients p
    WHERE p.id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)
      AND public.normalize_text_token(p.nhis_number) = public.normalize_text_token(NEW.nhis_number)
    LIMIT 1;

    IF v_conflict_patient_id IS NOT NULL THEN
      RAISE EXCEPTION 'Duplicate patient detected: NHIS number already exists for patient %', v_conflict_patient_id;
    END IF;
  END IF;

  IF NEW.national_id IS NOT NULL AND btrim(NEW.national_id) <> '' THEN
    SELECT p.patient_id
    INTO v_conflict_patient_id
    FROM public.patients p
    WHERE p.id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)
      AND public.normalize_text_token(p.national_id) = public.normalize_text_token(NEW.national_id)
    LIMIT 1;

    IF v_conflict_patient_id IS NOT NULL THEN
      RAISE EXCEPTION 'Duplicate patient detected: national ID already exists for patient %', v_conflict_patient_id;
    END IF;
  END IF;

  IF NEW.service_number IS NOT NULL AND btrim(NEW.service_number) <> '' THEN
    SELECT p.patient_id
    INTO v_conflict_patient_id
    FROM public.patients p
    WHERE p.id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)
      AND public.normalize_text_token(p.service_number) = public.normalize_text_token(NEW.service_number)
    LIMIT 1;

    IF v_conflict_patient_id IS NOT NULL THEN
      RAISE EXCEPTION 'Duplicate patient detected: service number already exists for patient %', v_conflict_patient_id;
    END IF;
  END IF;

  IF NEW.date_of_birth IS NOT NULL
     AND public.normalize_text_token(NEW.first_name) IS NOT NULL
     AND public.normalize_text_token(NEW.surname) IS NOT NULL
     AND (
       public.normalize_text_token(NEW.contact_phone) IS NOT NULL
       OR public.normalize_text_token(NEW.email) IS NOT NULL
     ) THEN
    SELECT p.patient_id
    INTO v_conflict_patient_id
    FROM public.patients p
    WHERE p.id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)
      AND public.normalize_text_token(p.first_name) = public.normalize_text_token(NEW.first_name)
      AND public.normalize_text_token(p.surname) = public.normalize_text_token(NEW.surname)
      AND p.date_of_birth = NEW.date_of_birth
      AND p.gender = NEW.gender
      AND (
        (
          public.normalize_text_token(NEW.contact_phone) IS NOT NULL
          AND public.normalize_text_token(p.contact_phone) = public.normalize_text_token(NEW.contact_phone)
        )
        OR (
          public.normalize_text_token(NEW.email) IS NOT NULL
          AND public.normalize_text_token(p.email) = public.normalize_text_token(NEW.email)
        )
      )
    LIMIT 1;

    IF v_conflict_patient_id IS NOT NULL THEN
      RAISE EXCEPTION 'Duplicate patient detected: matching name, DOB, gender, and contact details already exist for patient %', v_conflict_patient_id;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_single_active_lab_template(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_single_active_lab_template() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.is_active THEN
    UPDATE public.lab_form_templates
    SET is_active = false,
        updated_at = now()
    WHERE test_id = NEW.test_id
      AND id <> NEW.id
      AND is_active = true;
  END IF;

  NEW.updated_at = now();
  RETURN NEW;
END;
$$;


--
-- Name: enforce_single_primary_complaint(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_single_primary_complaint() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
    -- If setting as primary, unset others for this encounter
    IF NEW.is_primary = true THEN
        UPDATE patient_chief_complaints 
        SET is_primary = false, updated_at = NOW()
        WHERE encounter_id = NEW.encounter_id 
          AND id != NEW.id 
          AND is_primary = true;
    END IF;
    
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$;


--
-- Name: ensure_queue_entry_on_stage_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_queue_entry_on_stage_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_target_location VARCHAR;
  v_ticket_number VARCHAR;
  v_has_active_queue BOOLEAN;
  v_queue_producing_stages VARCHAR[] := ARRAY['queue_waiting', 'nursing_vitals', 'consultation'];
BEGIN
  -- Guard 1: Only trigger for queue-producing stages
  IF NOT (NEW.current_stage = ANY(v_queue_producing_stages)) THEN
    RETURN NEW;
  END IF;
  
  -- Guard 2: Only trigger when stage actually changed
  IF OLD.current_stage IS NOT DISTINCT FROM NEW.current_stage THEN
    RETURN NEW;
  END IF;
  
  -- Guard 3: Only for Active visits
  IF NEW.status != 'Active' THEN
    RETURN NEW;
  END IF;
  
  -- Guard 4: Check if an active queue entry already exists
  SELECT EXISTS(
    SELECT 1 FROM queue 
    WHERE encounter_id = NEW.id 
    AND status IN ('Waiting', 'Called', 'In Progress')
  ) INTO v_has_active_queue;
  
  -- Guard 5: If queue exists, skip (prevents duplicates)
  IF v_has_active_queue THEN
    RETURN NEW;
  END IF;
  
  -- Determine target location based on stage
  CASE NEW.current_stage
    WHEN 'queue_waiting' THEN v_target_location := 'Nursing';
    WHEN 'nursing_vitals' THEN v_target_location := 'Nursing';
    WHEN 'consultation' THEN v_target_location := 'Consultation';
    ELSE v_target_location := 'Nursing';
  END CASE;
  
  -- Generate ticket number
  SELECT COALESCE(MAX(CAST(ticket_number AS INTEGER)), 0) + 1 
  INTO v_ticket_number
  FROM queue 
  WHERE location = v_target_location
    AND created_at::date = CURRENT_DATE;
  
  v_ticket_number := COALESCE(v_ticket_number, '1');
  
  -- Insert with ON CONFLICT DO NOTHING to prevent duplicates
  INSERT INTO queue (
    patient_id,
    visit_id,
    encounter_id,
    clinic_id,
    ticket_number,
    location,
    priority,
    status,
    notes
  ) VALUES (
    NEW.patient_id,
    NEW.id,
    NEW.id,
    NEW.clinic_id,
    v_ticket_number,
    v_target_location,
    COALESCE(NEW.priority, 'Normal'),
    'Waiting',
    'Auto-created by safeguard trigger'
  )
  ON CONFLICT (encounter_id, location) 
  WHERE status IN ('Waiting', 'Called', 'In Progress')
  DO NOTHING;
  
  RETURN NEW;
END;
$$;


--
-- Name: fn_check_billing_gate(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_check_billing_gate(p_visit_id uuid, p_module text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
  v_payment_category TEXT;
  v_insurance_type   TEXT;
  v_paid_count       INT;
  v_skip             TEXT;
BEGIN
  -- Allow bypass via session variable (NHIS/retainership/test)
  v_skip := current_setting('app.skip_payment_gate', true);
  IF v_skip = 'true' THEN RETURN; END IF;

  SELECT payment_category, insurance_type
    INTO v_payment_category, v_insurance_type
  FROM visits
  WHERE id = p_visit_id;

  -- NHIS and retainership patients are exempt from upfront payment gate
  IF v_payment_category IN ('NHIS', 'Retainership') THEN RETURN; END IF;
  IF v_insurance_type ILIKE '%nhis%' OR v_insurance_type ILIKE '%military%' THEN RETURN; END IF;

  -- For cash/POS patients, check for a paid billing order
  SELECT COUNT(*) INTO v_paid_count
  FROM billing_orders
  WHERE visit_id  = p_visit_id
    AND source_module = p_module
    AND status IN ('Paid', 'Paid_NHIS', 'Paid_Retainership', 'Waived');

  IF v_paid_count = 0 THEN
    RAISE EXCEPTION
      'Payment gate: no paid billing order found for module=% on visit=%. '
      'Set app.skip_payment_gate=true to bypass (NHIS/retainership/test only).',
      p_module, p_visit_id
      USING ERRCODE = 'P0001';
  END IF;
END;
$$;


--
-- Name: generate_admission_number(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_admission_number(facility_code character varying DEFAULT 'ADM'::character varying) RETURNS character varying
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    year_part VARCHAR(4);
    sequence_num INTEGER;
    new_number VARCHAR(50);
    prefix_length INTEGER;
BEGIN
    year_part := TO_CHAR(CURRENT_DATE, 'YYYY');
    -- 'ADM-2026-' has length: len(ADM) + 1 + 4 + 1 = len(ADM) + 6
    -- So the sequence starts at: len(ADM) + 7
    prefix_length := LENGTH(facility_code) + 6;

    SELECT COALESCE(MAX(
        -- Start substring from the character AFTER the prefix (prefix_length + 1)
        CAST(SUBSTRING(admission_number FROM prefix_length + 1) AS INTEGER)
    ), 0) + 1
    INTO sequence_num
    FROM admissions
    WHERE admission_number LIKE facility_code || '-' || year_part || '-%';

    new_number := facility_code || '-' || year_part || '-' || LPAD(sequence_num::TEXT, 6, '0');
    RETURN new_number;
END;
$$;


--
-- Name: generate_beds_for_ward(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_beds_for_ward(p_ward_id uuid) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_ward_record RECORD;
    v_bed_count INTEGER;
    v_beds_created INTEGER := 0;
    v_i INTEGER;
BEGIN
    SELECT * INTO v_ward_record FROM wards WHERE id = p_ward_id;

    IF NOT FOUND THEN
        RETURN 0;
    END IF;

    -- Count existing beds
    SELECT COUNT(*) INTO v_bed_count FROM beds WHERE ward_id = p_ward_id;

    -- Create missing beds
    IF v_bed_count < v_ward_record.total_beds THEN
        FOR v_i IN (v_bed_count + 1)..v_ward_record.total_beds LOOP
            INSERT INTO beds (
                ward_id,
                bed_number,
                bed_type,
                status,
                daily_rate,
                features,
                is_active
            ) VALUES (
                p_ward_id,
                v_ward_record.code || '-' || LPAD(v_i::TEXT, 3, '0'),
                CASE
                    WHEN v_ward_record.ward_type = 'icu' THEN 'icu'
                    WHEN v_ward_record.ward_type = 'pediatric' THEN 'pediatric'
                    WHEN v_ward_record.ward_type = 'maternity' THEN 'standard'
                    ELSE 'standard'
                END,
                'available',
                CASE
                    WHEN v_ward_record.ward_type = 'icu' THEN 500.00
                    WHEN v_ward_record.ward_type = 'pediatric' THEN 150.00
                    WHEN v_ward_record.ward_type = 'maternity' THEN 200.00
                    ELSE 100.00
                END,
                CASE
                    WHEN v_ward_record.ward_type = 'icu' THEN '["oxygen", "suction", "cardiac_monitor", "ventilator"]'::jsonb
                    WHEN v_ward_record.ward_type = 'maternity' THEN '["fetal_monitor"]'::jsonb
                    ELSE '["oxygen", "call_bell"]'::jsonb
                END,
                TRUE
            ) ON CONFLICT (ward_id, bed_number) DO NOTHING;
            v_beds_created := v_beds_created + 1;
        END LOOP;
    END IF;

    RETURN v_beds_created;
END;
$$;


--
-- Name: generate_category_invoice_number(public.invoice_category); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_category_invoice_number(p_category public.invoice_category) RETURNS character varying
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_prefix character varying(4);
    v_year character varying(2);
    v_month character varying(2);
    v_sequence integer;
    v_invoice_number character varying(50);
BEGIN
    -- Get category prefix
    v_prefix := CASE p_category
        WHEN 'Pharmacy' THEN 'PH'
        WHEN 'Laboratory' THEN 'LB'
        WHEN 'Radiology' THEN 'RD'
        WHEN 'Procedures' THEN 'PR'
        WHEN 'Consultation' THEN 'CN'
        WHEN 'Nursing' THEN 'NR'
        WHEN 'Admission' THEN 'AD'
        WHEN 'Supplies' THEN 'SP'
        ELSE 'OT'
    END;

    -- Get current year and month
    v_year := to_char(CURRENT_DATE, 'YY');
    v_month := to_char(CURRENT_DATE, 'MM');

    -- Get next sequence number for this category this month
    SELECT COALESCE(MAX(
        NULLIF(regexp_replace(invoice_number, '^INV-' || v_prefix || '-' || v_year || v_month || '-', ''), '')::integer
    ), 0) + 1
    INTO v_sequence
    FROM "public"."category_invoices"
    WHERE invoice_number LIKE 'INV-' || v_prefix || '-' || v_year || v_month || '-%';

    -- Generate invoice number: INV-PH-2601-00001
    v_invoice_number := 'INV-' || v_prefix || '-' || v_year || v_month || '-' || lpad(v_sequence::text, 5, '0');

    RETURN v_invoice_number;
END;
$$;


--
-- Name: generate_category_receipt_number(public.invoice_category); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_category_receipt_number(p_category public.invoice_category) RETURNS character varying
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_prefix character varying(4);
    v_year character varying(2);
    v_month character varying(2);
    v_sequence integer;
    v_receipt_number character varying(50);
BEGIN
    -- Get category prefix
    v_prefix := CASE p_category
        WHEN 'Pharmacy' THEN 'PH'
        WHEN 'Laboratory' THEN 'LB'
        WHEN 'Radiology' THEN 'RD'
        WHEN 'Procedures' THEN 'PR'
        WHEN 'Consultation' THEN 'CN'
        WHEN 'Nursing' THEN 'NR'
        WHEN 'Admission' THEN 'AD'
        WHEN 'Supplies' THEN 'SP'
        ELSE 'OT'
    END;

    -- Get current year and month
    v_year := to_char(CURRENT_DATE, 'YY');
    v_month := to_char(CURRENT_DATE, 'MM');

    -- Get next sequence number
    SELECT COALESCE(MAX(
        NULLIF(regexp_replace(receipt_number, '^RCP-' || v_prefix || '-' || v_year || v_month || '-', ''), '')::integer
    ), 0) + 1
    INTO v_sequence
    FROM "public"."category_receipts"
    WHERE receipt_number LIKE 'RCP-' || v_prefix || '-' || v_year || v_month || '-%';

    -- Generate receipt number: RCP-PH-2601-00001
    v_receipt_number := 'RCP-' || v_prefix || '-' || v_year || v_month || '-' || lpad(v_sequence::text, 5, '0');

    RETURN v_receipt_number;
END;
$$;


--
-- Name: generate_clinical_request_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_clinical_request_number() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
    IF NEW.request_number IS NULL THEN
        NEW.request_number := 'REQ-' || TO_CHAR(CURRENT_DATE, 'YYYYMMDD') || '-' || 
                              LPAD(nextval('clinical_request_seq')::TEXT, 4, '0');
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: generate_emr_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_emr_number() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_prefix text;
  v_padding integer;
  v_candidate text;
  v_next bigint;
BEGIN
  IF NEW.emr_number IS NOT NULL AND trim(NEW.emr_number) <> '' THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(NULLIF(trim(value), ''), 'NDC')
  INTO v_prefix
  FROM public.system_configurations
  WHERE key = 'facility.emr_prefix' AND is_active = true
  LIMIT 1;

  SELECT COALESCE(NULLIF(trim(value), '')::integer, 4)
  INTO v_padding
  FROM public.system_configurations
  WHERE key = 'facility.emr_padding' AND is_active = true
  LIMIT 1;

  v_prefix := upper(regexp_replace(COALESCE(v_prefix, 'NDC'), '[^A-Za-z0-9]', '', 'g'));
  IF v_prefix = '' THEN
    v_prefix := 'NDC';
  END IF;
  v_padding := GREATEST(COALESCE(v_padding, 4), 4);

  LOOP
    v_next := nextval('public.facility_emr_number_seq');
    v_candidate := v_prefix || '-' || lpad(v_next::text, v_padding, '0');
    EXIT WHEN NOT EXISTS (
      SELECT 1 FROM public.patients WHERE emr_number = v_candidate
    );
  END LOOP;

  NEW.emr_number := v_candidate;
  RETURN NEW;
END;
$$;


