-- Name: get_drug_available_stock(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_drug_available_stock(p_drug_id uuid) RETURNS integer
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_total INTEGER;
BEGIN
    SELECT COALESCE(SUM(quantity_remaining), 0)
    INTO v_total
    FROM drug_batches
    WHERE drug_id = p_drug_id
      AND status = 'active'
      AND expiry_date > CURRENT_DATE;
    
    RETURN v_total;
END;
$$;


--
-- Name: get_effective_notification_settings(uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_effective_notification_settings(p_user_id uuid, p_notification_type character varying) RETURNS TABLE(is_enabled boolean, sound character varying, volume integer, show_popup boolean, show_in_center boolean, desktop_notification boolean, is_locked boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_global global_notification_settings%ROWTYPE;
    v_user user_notification_settings%ROWTYPE;
    v_master user_notification_master_settings%ROWTYPE;
BEGIN
    -- Get global settings
    SELECT * INTO v_global FROM global_notification_settings WHERE notification_type = p_notification_type;
    
    -- Get user settings
    SELECT * INTO v_user FROM user_notification_settings 
    WHERE user_id = p_user_id AND notification_type = p_notification_type;
    
    -- Get master settings
    SELECT * INTO v_master FROM user_notification_master_settings WHERE user_id = p_user_id;
    
    -- Return effective settings
    RETURN QUERY SELECT
        COALESCE(
            CASE WHEN v_global.is_locked THEN v_global.is_enabled 
                 ELSE COALESCE(v_user.is_enabled, v_global.is_enabled, TRUE) 
            END,
            TRUE
        ) AND COALESCE(v_master.notifications_enabled, TRUE) AS is_enabled,
        COALESCE(
            CASE WHEN v_global.is_locked THEN v_global.default_sound 
                 ELSE COALESCE(v_user.sound, v_global.default_sound, 'default') 
            END,
            'default'
        )::VARCHAR(20) AS sound,
        COALESCE(v_user.volume, v_master.master_volume, 80)::INTEGER AS volume,
        COALESCE(v_user.show_popup, TRUE) AS show_popup,
        COALESCE(v_user.show_in_center, TRUE) AS show_in_center,
        COALESCE(v_user.desktop_notification, v_master.desktop_notifications_enabled, TRUE) AS desktop_notification,
        COALESCE(v_global.is_locked, FALSE) AS is_locked;
END;
$$;


--
-- Name: get_encounter_access_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_encounter_access_summary(p_encounter_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_summary JSON;
BEGIN
    SELECT json_build_object(
        'encounter_id', p_encounter_id,
        'primary_doctor', (
            SELECT json_build_object(
                'id', v.attending_doctor_id,
                'name', s.first_name || ' ' || s.last_name,
                'department', s.department
            )
            FROM visits v
            JOIN staff s ON s.id = v.attending_doctor_id
            WHERE v.id = p_encounter_id
        ),
        'care_team', (
            SELECT COALESCE(json_agg(
                json_build_object(
                    'staff_id', ect.staff_id,
                    'staff_name', ect.staff_name,
                    'role', ect.role,
                    'department', ect.department,
                    'assigned_at', ect.assigned_at,
                    'expires_at', ect.expires_at,
                    'is_active', ect.is_active
                )
                ORDER BY ect.assigned_at DESC
            ), '[]'::json)
            FROM encounter_care_team ect
            WHERE ect.encounter_id = p_encounter_id
        ),
        'recent_access', (
            SELECT COALESCE(json_agg(
                json_build_object(
                    'user_id', eal.user_id,
                    'user_name', s.first_name || ' ' || s.last_name,
                    'action', eal.action,
                    'timestamp', eal.timestamp,
                    'was_authorized', eal.was_authorized
                )
                ORDER BY eal.timestamp DESC
            ), '[]'::json)
            FROM encounter_access_logs eal
            JOIN staff s ON s.id = eal.user_id
            WHERE eal.encounter_id = p_encounter_id
            LIMIT 20
        ),
        'transfer_history', (
            SELECT COALESCE(json_agg(
                json_build_object(
                    'from_doctor', sf.first_name || ' ' || sf.last_name,
                    'to_doctor', st.first_name || ' ' || st.last_name,
                    'type', et.transfer_type,
                    'status', et.status,
                    'transferred_at', et.transferred_at
                )
                ORDER BY et.transferred_at DESC
            ), '[]'::json)
            FROM encounter_transfers et
            JOIN staff sf ON sf.id = et.from_doctor_id
            JOIN staff st ON st.id = et.to_doctor_id
            WHERE et.encounter_id = p_encounter_id
        )
    ) INTO v_summary;
    
    RETURN v_summary;
END;
$$;


--
-- Name: get_encounter_complaints(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_encounter_complaints(p_encounter_id uuid) RETURNS TABLE(id uuid, complaint_id uuid, complaint_name character varying, complaint_code character varying, category public.complaint_category, is_primary boolean, duration_value integer, duration_unit public.duration_unit, notes text)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        pcc.id,
        ccc.complaint_id,
        ccc.complaint_name,
        ccc.complaint_code,
        ccc.category,
        pcc.is_primary,
        pcc.duration_value,
        pcc.duration_unit,
        pcc.notes
    FROM patient_chief_complaints pcc
    JOIN chief_complaint_catalogue ccc ON pcc.complaint_id = ccc.complaint_id
    WHERE pcc.encounter_id = p_encounter_id
    ORDER BY pcc.is_primary DESC, ccc.display_order;
END;
$$;


--
-- Name: get_icd10_code(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_icd10_code(p_code text) RETURNS TABLE(code text, description text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT i.code, i.description
    FROM public.icd10_codes i
    WHERE UPPER(i.code) = UPPER(TRIM(p_code))
    LIMIT 1;
END;
$$;


--
-- Name: get_icd10_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_icd10_stats() RETURNS TABLE(total_codes bigint, chapters_count bigint, last_updated timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        COUNT(*)::BIGINT AS total_codes,
        COUNT(DISTINCT SUBSTRING(i.code FROM 1 FOR 1))::BIGINT AS chapters_count,
        MAX(i.created_at) AS last_updated
    FROM public.icd10_codes i;
END;
$$;


--
-- Name: get_lab_statistics(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_lab_statistics(p_start_date timestamp with time zone DEFAULT (now() - '30 days'::interval), p_end_date timestamp with time zone DEFAULT now()) RETURNS TABLE(total_requests bigint, total_completed bigint, total_pending bigint, total_critical bigint, avg_turnaround_hours numeric, requests_by_category jsonb, completion_rate numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        COUNT(*)::bigint AS total_requests,
        COUNT(*) FILTER (WHERE lreq.status = 'Completed')::bigint AS total_completed,
        COUNT(*) FILTER (WHERE lreq.status IN ('Pending', 'Accepted', 'Sample_Collected', 'Processing'))::bigint AS total_pending,
        COUNT(*) FILTER (WHERE lreq.is_critical = true)::bigint AS total_critical,
        ROUND(AVG(EXTRACT(EPOCH FROM (lr.reported_at - lreq.created_at))/3600)::numeric, 2) AS avg_turnaround_hours,
        jsonb_object_agg(
            COALESCE(ltc.category, 'Unknown'),
            cat_counts.cnt
        ) AS requests_by_category,
        ROUND((COUNT(*) FILTER (WHERE lreq.status = 'Completed')::numeric / NULLIF(COUNT(*)::numeric, 0)) * 100, 2) AS completion_rate
    FROM lab_requests lreq
    LEFT JOIN lab_results lr ON lreq.request_id = lr.request_id
    LEFT JOIN lab_test_catalogue ltc ON lreq.test_id = ltc.id
    LEFT JOIN LATERAL (
        SELECT ltc2.category, COUNT(*) AS cnt
        FROM lab_requests lreq2
        LEFT JOIN lab_test_catalogue ltc2 ON lreq2.test_id = ltc2.id
        WHERE lreq2.created_at BETWEEN p_start_date AND p_end_date
        GROUP BY ltc2.category
    ) cat_counts ON ltc.category = cat_counts.category
    WHERE lreq.created_at BETWEEN p_start_date AND p_end_date;
END;
$$;


--
-- Name: get_next_queue_number(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_next_queue_number(dept text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    next_num integer;
    today_lagos date;
BEGIN
    -- Get today's date in Africa/Lagos timezone
    today_lagos := (now() AT TIME ZONE 'Africa/Lagos')::date;
    
    -- Atomic upsert: insert new counter or increment existing
    -- Uses advisory lock to prevent race conditions
    PERFORM pg_advisory_xact_lock(hashtext('queue_counter_' || dept || '_' || today_lagos::text));
    
    INSERT INTO public.queue_daily_counters (department, counter_date, last_ticket_number)
    VALUES (dept, today_lagos, 1)
    ON CONFLICT (department, counter_date)
    DO UPDATE SET 
        last_ticket_number = queue_daily_counters.last_ticket_number + 1,
        updated_at = now()
    RETURNING last_ticket_number INTO next_num;
    
    RETURN next_num;
END;
$$;


--
-- Name: get_next_queue_patient(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_next_queue_patient(p_clinic_id uuid) RETURNS TABLE(queue_entry_id uuid, patient_id uuid, patient_name text, priority public.queue_priority_enum, wait_time interval)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        qe.id,
        qe.patient_id,
        CONCAT(p.first_name, ' ', p.surname) as patient_name,
        qe.priority,
        NOW() - qe.wait_start_time as wait_time
    FROM queue qe
    JOIN patients p ON p.patient_id = qe.patient_id
    WHERE qe.clinic_id = p_clinic_id
    AND qe.status = 'Waiting'
    ORDER BY 
        CASE qe.priority 
            WHEN 'Emergency' THEN 1 
            WHEN 'Urgent' THEN 2 
            ELSE 3 
        END,
        qe.wait_start_time ASC
    LIMIT 1;
END;
$$;


--
-- Name: get_next_staff_id(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_next_staff_id(role_input text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
    prefix VARCHAR;
    seq INTEGER;
    formatted_seq VARCHAR;
    num_part TEXT;
BEGIN
    -- Determine prefix based on role
    CASE role_input
        WHEN 'super_admin' THEN prefix := 'ADM';
        WHEN 'admin' THEN prefix := 'ADM';
        WHEN 'medical_director' THEN prefix := 'MDR';
        WHEN 'doctor' THEN prefix := 'DOC';
        WHEN 'nurse' THEN prefix := 'NUR';
        WHEN 'lab_technician' THEN prefix := 'LAB';
        WHEN 'radiologist' THEN prefix := 'RAD';
        WHEN 'pharmacist' THEN prefix := 'PHM';
        WHEN 'billing_clerk' THEN prefix := 'BIL';
        WHEN 'receptionist' THEN prefix := 'REC';
        WHEN 'cashier' THEN prefix := 'CSH';
        WHEN 'customer_service' THEN prefix := 'CSV';
        WHEN 'inventory_manager' THEN prefix := 'INV';
        WHEN 'config_admin' THEN prefix := 'CFG';
        ELSE prefix := 'STF';
    END CASE;

    -- Find next sequence number for this prefix
    -- Use regexp_replace to extract digit portion after prefix, cast to integer for proper numeric MAX
    SELECT COALESCE(MAX(
        CASE 
            WHEN staff_id ~ ('^' || prefix || '-\d+$')
            THEN regexp_replace(staff_id, '^' || prefix || '-', '')::INTEGER
            ELSE 0
        END
    ), 0) + 1
    INTO seq
    FROM staff
    WHERE staff_id LIKE prefix || '-%';

    formatted_seq := LPAD(seq::TEXT, 3, '0');
    
    RETURN prefix || '-' || formatted_seq;
END;
$_$;


--
-- Name: get_nhis_profile_activity(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_nhis_profile_activity(p_profile_id uuid, p_limit integer DEFAULT 50) RETURNS TABLE(performed_at timestamp with time zone, action_type character varying, event_type character varying, user_name text, auth_code character varying, before_state jsonb, after_state jsonb, reason text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    naa.performed_at,
    naa.action_type,
    naa.event_type,
    COALESCE(s.first_name || ' ' || s.last_name, 'System') as user_name,
    naa.auth_code,
    naa.before_state,
    naa.after_state,
    naa.reason
  FROM nhis_activity_audit naa
  LEFT JOIN staff s ON s.id = naa.staff_id
  WHERE naa.profile_id = p_profile_id
  ORDER BY naa.performed_at DESC
  LIMIT p_limit;
END;
$$;


--
-- Name: get_notification_sound_config(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_notification_sound_config(p_sound_name character varying) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_sound notification_sounds%ROWTYPE;
BEGIN
    SELECT * INTO v_sound FROM notification_sounds WHERE name = p_sound_name AND is_active = TRUE;
    
    IF v_sound IS NULL THEN
        -- Return default sound config
        RETURN '{"frequencies": [523, 659], "duration": 0.1, "type": "sine", "volume": 0.1}'::jsonb;
    END IF;
    
    IF v_sound.is_programmatic THEN
        RETURN v_sound.sound_config;
    ELSE
        RETURN jsonb_build_object('file_url', v_sound.file_url, 'duration_ms', v_sound.duration_ms);
    END IF;
END;
$$;


--
-- Name: get_on_call_compliance_report(character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_on_call_compliance_report(p_department character varying DEFAULT NULL::character varying, p_days_back integer DEFAULT 30) RETURNS TABLE(department character varying, total_hours_scheduled numeric, gaps_count integer, overlaps_count integer, coverage_percentage numeric)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
    RETURN QUERY
    WITH schedule_stats AS (
        SELECT 
            ocs.department,
            SUM(EXTRACT(EPOCH FROM (ocs.end_time - ocs.start_time)) / 3600) as hours_scheduled,
            COUNT(*) FILTER (WHERE ocs.is_active) as active_schedules
        FROM on_call_schedule ocs
        WHERE ocs.start_time >= NOW() - (p_days_back || ' days')::INTERVAL
          AND (p_department IS NULL OR ocs.department = p_department)
        GROUP BY ocs.department
    )
    SELECT 
        ss.department,
        ROUND(ss.hours_scheduled, 2) as total_hours_scheduled,
        0 as gaps_count, -- Placeholder for gap detection
        0 as overlaps_count, -- Already prevented by constraint
        ROUND((ss.hours_scheduled / (p_days_back * 24.0)) * 100, 2) as coverage_percentage
    FROM schedule_stats ss
    ORDER BY ss.department;
END;
$$;


--
-- Name: get_online_doctors_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_online_doctors_count() RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
  SELECT COUNT(*)::INTEGER
  FROM staff
  WHERE role = 'doctor'
    AND is_active = true
    AND last_activity > NOW() - INTERVAL '5 minutes';
$$;


--
-- Name: get_overdue_vitals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_overdue_vitals() RETURNS TABLE(schedule_id uuid, patient_id character varying, patient_name text, encounter_id uuid, ward_name character varying, bed_number character varying, acuity_level public.patient_acuity, acuity_display_name character varying, acuity_color character varying, last_vitals_at timestamp with time zone, next_vitals_due timestamp with time zone, minutes_overdue integer, assigned_nurse_id uuid, assigned_nurse_name text, alert_priority character varying)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        pvs.id,
        pvs.patient_id,
        CONCAT(p.first_name, ' ', p.surname)::TEXT,
        pvs.encounter_id,
        w.name,
        b.bed_number,
        pvs.acuity_level,
        vsc.display_name,
        vsc.color,
        pvs.last_vitals_at,
        pvs.next_vitals_due,
        EXTRACT(EPOCH FROM (NOW() - pvs.next_vitals_due))::INTEGER / 60,
        pvs.assigned_nurse_id,
        CONCAT(s.first_name, ' ', s.last_name)::TEXT,
        vsc.alert_priority
    FROM patient_vital_schedules pvs
    JOIN patients p ON p.patient_id = pvs.patient_id
    JOIN visits v ON v.id = pvs.encounter_id
    JOIN vital_schedule_configs vsc ON vsc.acuity_level = pvs.acuity_level
    LEFT JOIN admissions a ON a.encounter_id = v.id
    LEFT JOIN beds b ON b.id = a.current_bed_id
    LEFT JOIN wards w ON w.id = b.ward_id
    LEFT JOIN staff s ON s.id = pvs.assigned_nurse_id
    WHERE pvs.is_active = TRUE
    AND pvs.paused = FALSE
    AND pvs.is_overdue = TRUE
    ORDER BY 
        CASE pvs.acuity_level 
            WHEN 'critical' THEN 1 
            WHEN 'high' THEN 2 
            WHEN 'medium' THEN 3 
            WHEN 'low' THEN 4 
            WHEN 'routine' THEN 5 
        END,
        pvs.next_vitals_due ASC;
END;
$$;


--
-- Name: get_patient_audit_trail(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_patient_audit_trail(p_patient_id uuid, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS TABLE(performed_at timestamp with time zone, action_type character varying, table_name character varying, description text, user_name text, user_role character varying, changed_fields text[], is_critical boolean, old_values jsonb, new_values jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    cal.performed_at,
    cal.action_type,
    cal.table_name,
    cal.description,
    COALESCE(s.first_name || ' ' || s.last_name, cal.user_email, 'System') as user_name,
    cal.user_role,
    cal.changed_fields,
    cal.is_critical,
    cal.old_values,
    cal.new_values
  FROM comprehensive_audit_log cal
  LEFT JOIN staff s ON s.id = cal.staff_id
  WHERE cal.patient_id = p_patient_id
  ORDER BY cal.performed_at DESC
  LIMIT p_limit OFFSET p_offset;
END;
$$;


--
-- Name: get_patient_clinical_context(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_patient_clinical_context(p_patient_id uuid, p_max_per_section integer DEFAULT 25) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_patient_varchar varchar(50);
  v_patient_uuid uuid;
  v_result jsonb;
  v_demographics jsonb;
  v_encounters jsonb;
  v_consultations jsonb;
  v_nursing_notes jsonb;
  v_vitals jsonb;
  v_lab_results jsonb;
  v_radiology jsonb;
  v_prescriptions jsonb;
  v_admissions jsonb;
  v_ward_rounds jsonb;
  v_progress_notes jsonb;
  v_procedures jsonb;
  v_referrals jsonb;
  v_triage jsonb;
  v_allergies jsonb;
BEGIN
  -- ── Resolve both ID formats ──
  SELECT p.id, p.patient_id INTO v_patient_uuid, v_patient_varchar
    FROM patients p WHERE p.id = p_patient_id;
  IF v_patient_uuid IS NULL THEN
    SELECT p.id, p.patient_id INTO v_patient_uuid, v_patient_varchar
      FROM patients p WHERE p.patient_id = p_patient_id::text;
  END IF;
  IF v_patient_uuid IS NULL THEN
    RAISE EXCEPTION 'Patient not found';
  END IF;

  -- ── 1. Demographics ──
  SELECT jsonb_build_object(
    'name', p.first_name || ' ' || COALESCE(p.middle_name || ' ', '') || p.surname,
    'emr_number', p.emr_number,
    'gender', p.gender::text,
    'date_of_birth', p.date_of_birth,
    'age_years', EXTRACT(YEAR FROM AGE(CURRENT_DATE, p.date_of_birth)),
    'blood_group', p.blood_group,
    'allergies', COALESCE(p.known_allergies, ARRAY[]::text[]),
    'phone', p.contact_phone,
    'category', p.patient_category::text,
    'insurance_type', p.insurance_type::text,
    'nhis_number', p.nhis_number,
    'occupation', p.occupation,
    'clinical_summary', p.clinical_summary,
    'nok_name', p.nok_name,
    'nok_phone', p.nok_phone,
    'nok_relationship', p.nok_relationship,
    'current_status', p.current_status
  ) INTO v_demographics
  FROM patients p WHERE p.id = v_patient_uuid;

  -- ── 2. Encounters (visits) ──
  SELECT COALESCE(jsonb_agg(enc ORDER BY enc->>'encounter_date' DESC), '[]'::jsonb) INTO v_encounters
  FROM (
    SELECT jsonb_build_object(
      'encounter_id', v.id,
      'visit_id', v.visit_id,
      'encounter_date', v.encounter_date,
      'visit_type', v.visit_type,
      'chief_complaint', v.chief_complaint,
      'status', v.status::text,
      'category', v.encounter_category,
      'priority', v.priority::text,
      'current_stage', v.current_stage,
      'attending_doctor', COALESCE(
        s.first_name || ' ' || s.last_name,
        'Not assigned'
      ),
      'attending_doctor_role', s.role::text,
      'clinic_name', cl.name,
      'ward_location', v.ward_location,
      'bed_number', v.bed_number,
      'discharge_date', v.discharge_date,
      'discharge_notes', v.discharge_notes
    ) AS enc
    FROM visits v
    LEFT JOIN staff s ON v.attending_doctor_id = s.id
    LEFT JOIN clinics cl ON v.clinic_id = cl.id
    WHERE v.patient_id = v_patient_uuid
    ORDER BY v.encounter_date DESC NULLS LAST
    LIMIT p_max_per_section
  ) sub;

  -- ── 3. Consultations (with doctor names) ──
  SELECT COALESCE(jsonb_agg(con ORDER BY con->>'consultation_date' DESC), '[]'::jsonb) INTO v_consultations
  FROM (
    SELECT jsonb_build_object(
      'consultation_id', c.consultation_id,
      'encounter_id', c.encounter_id,
      'consultation_date', c.consultation_date,
      'complaints', c.complaints,
      'history_of_present_illness', c.history_of_present_illness,
      'past_medical_history', c.past_medical_history,
      'family_history', c.family_history,
      'social_history', c.social_history,
      'review_of_systems', c.review_of_systems,
      'examination_findings', c.examination_findings,
      'physical_examination', c.physical_examination,
      'assessment', c.assessment,
      'plan', c.plan,
      'treatment_plan', c.treatment_plan,
      'diagnosis', c.diagnosis,
      'diagnosis_text', c.diagnosis_text,
      'differential_diagnosis', c.differential_diagnosis,
      'icd10_codes', c.icd10_codes,
      'clinical_notes', c.clinical_notes,
      'recommendations', c.recommendations,
      'follow_up_date', c.follow_up_date,
      'follow_up_notes', c.follow_up_notes,
      'doctor_name', COALESCE(s.first_name || ' ' || s.last_name, 'Unknown'),
      'doctor_role', s.role::text,
      'status', c.status::text
    ) AS con
    FROM consultations c
    JOIN visits v ON c.encounter_id = v.id
    LEFT JOIN staff s ON c.doctor_id = s.staff_id
    WHERE v.patient_id = v_patient_uuid
    ORDER BY c.consultation_date DESC NULLS LAST
    LIMIT p_max_per_section
  ) sub;

  -- ── 4. Nursing Notes (with nurse names) ──
  SELECT COALESCE(jsonb_agg(nn ORDER BY nn->>'created_at' DESC), '[]'::jsonb) INTO v_nursing_notes
  FROM (
    SELECT jsonb_build_object(
      'id', n.id,
      'encounter_id', n.encounter_id,
      'note_type', n.note_type,
      'title', n.title,
      'content', n.content,
      'patient_condition', n.patient_condition,
      'pain_level', n.pain_level,
      'interventions_performed', n.interventions_performed,
      'patient_response', n.patient_response,
      'is_critical', n.is_critical,
      'shift', n.shift,
      'created_at', n.created_at,
      'nurse_name', COALESCE(s.first_name || ' ' || s.last_name, 'Unknown'),
      'doctor_reviewed_by', COALESCE(s2.first_name || ' ' || s2.last_name, NULL),
      'doctor_reviewed_at', n.doctor_reviewed_at
    ) AS nn
    FROM nursing_notes n
    LEFT JOIN staff s ON n.recorded_by = s.id
    LEFT JOIN staff s2 ON n.doctor_reviewed_by = s2.id
    WHERE n.patient_id = v_patient_uuid
    ORDER BY n.created_at DESC
    LIMIT p_max_per_section
  ) sub;

  -- ── 5. Vitals (with recording nurse) ──
  SELECT COALESCE(jsonb_agg(vt ORDER BY vt->>'date_recorded' DESC), '[]'::jsonb) INTO v_vitals
  FROM (
    SELECT jsonb_build_object(
      'date_recorded', vt.date_recorded,
      'temperature', vt.temperature,
      'bp_systolic', vt.blood_pressure_systolic,
      'bp_diastolic', vt.blood_pressure_diastolic,
      'blood_pressure', vt.blood_pressure,
      'pulse', vt.pulse,
      'respiratory_rate', vt.respiratory_rate,
      'oxygen_saturation', vt.oxygen_saturation,
      'weight', vt.weight,
      'height', vt.height,
      'bmi', vt.bmi,
      'blood_glucose', vt.blood_glucose,
      'pain_level', vt.pain_level,
      'is_critical', vt.is_critical,
      'notes', vt.notes,
      'recorded_by', COALESCE(s.first_name || ' ' || s.last_name, 'Unknown')
    ) AS vt
    FROM vitals vt
    LEFT JOIN staff s ON vt.nurse_id = s.id
    WHERE vt.patient_id = v_patient_uuid
    ORDER BY vt.date_recorded DESC NULLS LAST
    LIMIT p_max_per_section
  ) sub;

  -- ── 6. Lab Results (with ordering doctor and technician) ──
  SELECT COALESCE(jsonb_agg(lr ORDER BY lr->>'created_at' DESC), '[]'::jsonb) INTO v_lab_results
  FROM (
    SELECT jsonb_build_object(
      'request_id', req.request_id,
      'created_at', req.created_at,
      'status', req.status::text,
      'priority', req.priority::text,
      'is_critical', req.is_critical,
      'clinical_notes', req.clinical_notes,
      'test_name', COALESCE(cat.name, 'Unknown Test'),
      'result_value', COALESCE(res.result_value, req.result_value::text),
      'unit', COALESCE(res.unit, req.result_unit),
      'reference_range', COALESCE(res.reference_range, req.reference_range),
      'is_abnormal', res.is_abnormal,
      'interpretation', COALESCE(res.interpretation, req.interpretation),
      'result_notes', req.result_notes,
      'result_date', COALESCE(res.reported_at, req.result_date),
      'ordered_by', COALESCE(s_ord.first_name || ' ' || s_ord.last_name, 'Unknown'),
      'technician', COALESCE(s_tech.first_name || ' ' || s_tech.last_name, NULL),
      'verified_by', COALESCE(s_ver.first_name || ' ' || s_ver.last_name, NULL)
    ) AS lr
    FROM lab_requests req
    JOIN visits v ON req.encounter_id = v.id
    LEFT JOIN lab_test_catalogue cat ON req.test_id = cat.id
    LEFT JOIN lab_results res ON res.request_id = req.request_id
    LEFT JOIN staff s_ord ON req.ordered_by = s_ord.staff_id
    LEFT JOIN staff s_tech ON res.technician_id = s_tech.id
    LEFT JOIN staff s_ver ON res.verified_by = s_ver.id
    WHERE v.patient_id = v_patient_uuid
    ORDER BY req.created_at DESC
    LIMIT p_max_per_section
  ) sub;

  -- ── 7. Radiology (with ordering doctor and radiologist) ──
  SELECT COALESCE(jsonb_agg(rx ORDER BY rx->>'created_at' DESC), '[]'::jsonb) INTO v_radiology
  FROM (
    SELECT jsonb_build_object(
      'request_id', r.request_id,
      'created_at', r.created_at,
      'imaging_type', r.imaging_type,
      'body_part', r.body_part,
      'clinical_indication', r.clinical_indication,
      'clinical_history', r.clinical_history,
      'status', r.status::text,
      'priority', r.priority::text,
      'findings', COALESCE(sr.findings, r.findings),
      'impression', COALESCE(sr.impression, r.impression),
      'recommendation', sr.recommendation,
      'report', r.report,
      'ordered_by', COALESCE(s_ord.first_name || ' ' || s_ord.last_name, 'Unknown'),
      'radiologist', COALESCE(s_rad.first_name || ' ' || s_rad.last_name, NULL),
      'performed_at', COALESCE(r.performed_at, r.scan_completed_at)
    ) AS rx
    FROM radiology_requests r
    JOIN visits v ON r.encounter_id = v.id
    LEFT JOIN scan_results sr ON sr.request_id = r.request_id
    LEFT JOIN staff s_ord ON r.ordered_by = s_ord.staff_id
    LEFT JOIN staff s_rad ON sr.radiologist_id = s_rad.id
    WHERE v.patient_id = v_patient_uuid
    ORDER BY r.created_at DESC
    LIMIT p_max_per_section
  ) sub;

  -- ── 8. Prescriptions / Medications (with prescribing doctor) ──
  SELECT COALESCE(jsonb_agg(px ORDER BY px->>'created_at' DESC), '[]'::jsonb) INTO v_prescriptions
  FROM (
    SELECT jsonb_build_object(
      'prescription_id', p.prescription_id,
      'created_at', p.created_at,
      'drug_name', COALESCE(p.drug_name, dc.name, 'Unknown Drug'),
      'dosage', p.dosage,
      'frequency', p.frequency,
      'duration', p.duration,
      'route', p.route,
      'quantity_prescribed', p.quantity_prescribed,
      'quantity_dispensed', p.quantity_dispensed,
      'instructions', p.instructions,
      'status', p.status::text,
      'clinical_notes', p.clinical_notes,
      'prescribed_by', COALESCE(s.first_name || ' ' || s.last_name, 'Unknown'),
      'dispensed_at', p.dispensed_at,
      'dispensed_by', COALESCE(s2.first_name || ' ' || s2.last_name, NULL)
    ) AS px
    FROM prescriptions p
    JOIN visits v ON p.encounter_id = v.id
    LEFT JOIN drug_catalogue dc ON p.drug_id = dc.id
    LEFT JOIN staff s ON p.doctor_id = s.staff_id
    LEFT JOIN staff s2 ON p.dispensed_by = s2.id
    WHERE v.patient_id = v_patient_uuid
    ORDER BY p.created_at DESC
    LIMIT p_max_per_section
  ) sub;

  -- ── 9. Admissions (with care team) ──
  SELECT COALESCE(jsonb_agg(adm ORDER BY adm->>'admission_date' DESC), '[]'::jsonb) INTO v_admissions
  FROM (
    SELECT jsonb_build_object(
      'id', a.id,
      'admission_number', a.admission_number,
      'admission_date', a.admission_date,
      'actual_discharge_date', a.actual_discharge_date,
      'admission_type', a.admission_type,
      'admission_status', a.admission_status,
      'acuity_level', a.acuity_level,
      'chief_complaint', a.chief_complaint,
      'reason_for_admission', a.reason_for_admission,
      'admitting_diagnosis', a.admitting_diagnosis,
      'admitting_diagnosis_icd10', a.admitting_diagnosis_icd10,
      'secondary_diagnoses', a.secondary_diagnoses,
      'discharge_diagnosis', a.discharge_diagnosis,
      'discharge_summary', a.discharge_summary,
      'discharge_instructions', a.discharge_instructions,
      'discharge_medications', a.discharge_medications,
      'code_status', a.code_status,
      'diet_type', a.diet_type,
      'activity_level', a.activity_level,
      'isolation_required', a.isolation_required,
      'allergies_snapshot', a.allergies_snapshot,
      'notes', a.notes,
      'admitting_doctor', COALESCE(s1.first_name || ' ' || s1.last_name, 'Unknown'),
      'attending_physician', COALESCE(s2.first_name || ' ' || s2.last_name, NULL),
      'primary_nurse', COALESCE(s3.first_name || ' ' || s3.last_name, NULL),
      'ward_name', w.name,
      'bed_number', b.bed_number
    ) AS adm
    FROM admissions a
    LEFT JOIN staff s1 ON a.admitting_doctor_id = s1.id
    LEFT JOIN staff s2 ON a.attending_physician_id = s2.id
    LEFT JOIN staff s3 ON a.primary_nurse_id = s3.id
    LEFT JOIN wards w ON a.current_ward_id = w.id
    LEFT JOIN beds b ON a.current_bed_id = b.id
    WHERE a.patient_id = v_patient_uuid
    ORDER BY a.admission_date DESC
    LIMIT p_max_per_section
  ) sub;

  -- ── 10. Ward Round Notes (with physician) ──
  SELECT COALESCE(jsonb_agg(wrn ORDER BY wrn->>'round_date' DESC), '[]'::jsonb) INTO v_ward_rounds
  FROM (
    SELECT jsonb_build_object(
      'id', w.id,
      'round_date', w.round_date,
      'round_type', w.round_type,
      'subjective_notes', w.subjective_notes,
      'objective_findings', w.objective_findings,
      'vital_signs', w.vital_signs,
      'assessment', w.assessment,
      'plan', w.plan,
      'nursing_instructions', w.nursing_instructions,
      'patient_condition', w.patient_condition,
      'estimated_discharge_date', w.estimated_discharge_date,
      'attending_physician', COALESCE(s.first_name || ' ' || s.last_name, 'Unknown'),
      'created_by', COALESCE(s2.first_name || ' ' || s2.last_name, 'Unknown'),
      'participants', w.participants
    ) AS wrn
    FROM ward_round_notes w
    LEFT JOIN staff s ON w.attending_physician_id = s.id
    LEFT JOIN staff s2 ON w.created_by = s2.id
    WHERE w.encounter_id IN (SELECT id FROM visits WHERE patient_id = v_patient_uuid)
    ORDER BY w.round_date DESC
    LIMIT p_max_per_section
  ) sub;

  -- ── 11. Daily Progress Notes ──
  SELECT COALESCE(jsonb_agg(dpn ORDER BY dpn->>'note_date' DESC), '[]'::jsonb) INTO v_progress_notes
  FROM (
    SELECT jsonb_build_object(
      'note_date', d.note_date,
      'subjective', d.subjective,
      'objective', d.objective,
      'assessment', d.assessment,
      'plan', d.plan,
      'nursing_summary', d.nursing_summary,
      'vital_signs_summary', d.vital_signs_summary,
      'patient_condition', d.patient_condition,
      'alert_level', d.alert_level,
      'intake_oral_ml', d.oral_intake_ml,
      'intake_iv_ml', d.iv_intake_ml,
      'urine_output_ml', d.urine_output_ml,
      'recorded_by', COALESCE(s.first_name || ' ' || s.last_name, 'Unknown')
    ) AS dpn
    FROM daily_progress_notes d
    LEFT JOIN staff s ON d.recorded_by = s.id
    WHERE d.patient_id = v_patient_uuid
    ORDER BY d.note_date DESC
    LIMIT p_max_per_section
  ) sub;

  -- ── 12. Procedures ──
  SELECT COALESCE(jsonb_agg(pr ORDER BY pr->>'scheduled_date' DESC), '[]'::jsonb) INTO v_procedures
  FROM (
    SELECT jsonb_build_object(
      'procedure_number', p.procedure_number,
      'procedure_name', p.procedure_name,
      'procedure_code', p.procedure_code,
      'scheduled_date', p.scheduled_date,
      'actual_start_time', p.actual_start_time,
      'actual_end_time', p.actual_end_time,
      'status', p.status,
      'priority', p.priority,
      'indication', p.indication,
      'pre_procedure_diagnosis', p.pre_procedure_diagnosis,
      'post_procedure_diagnosis', p.post_procedure_diagnosis,
      'anesthesia_type', p.anesthesia_type,
      'procedure_notes', p.procedure_notes,
      'findings', p.findings,
      'technique_description', p.technique_description,
      'complications', p.complications,
      'estimated_blood_loss_ml', p.estimated_blood_loss_ml,
      'post_op_instructions', p.post_op_instructions,
      'primary_surgeon', COALESCE(s1.first_name || ' ' || s1.last_name, 'Unknown'),
      'anesthesiologist', COALESCE(s2.first_name || ' ' || s2.last_name, NULL),
      'scrub_nurse', COALESCE(s3.first_name || ' ' || s3.last_name, NULL)
    ) AS pr
    FROM procedures p
    LEFT JOIN staff s1 ON p.primary_surgeon_id = s1.id
    LEFT JOIN staff s2 ON p.anesthesiologist_id = s2.id
    LEFT JOIN staff s3 ON p.scrub_nurse_id = s3.id
    WHERE p.patient_id = v_patient_uuid
    ORDER BY p.scheduled_date DESC NULLS LAST
    LIMIT p_max_per_section
  ) sub;

  -- ── 13. Referrals ──
  SELECT COALESCE(jsonb_agg(ref ORDER BY ref->>'created_at' DESC), '[]'::jsonb) INTO v_referrals
  FROM (
    SELECT jsonb_build_object(
      'referral_number', r.referral_number,
      'referral_type', r.referral_type::text,
      'priority', r.priority::text,
      'status', r.status::text,
      'reason_for_referral', r.reason_for_referral,
      'clinical_summary', r.clinical_summary,
      'created_at', r.created_at,
      'referring_physician', COALESCE(s1.first_name || ' ' || s1.last_name, 'Unknown'),
      'receiving_physician', COALESCE(s2.first_name || ' ' || s2.last_name, NULL),
      'source_department', sd.name,
      'target_department', td.name
    ) AS ref
    FROM referrals r
    LEFT JOIN staff s1 ON r.referring_physician_id = s1.id
    LEFT JOIN staff s2 ON r.receiving_physician_id = s2.id
    LEFT JOIN departments sd ON r.source_department_id = sd.id
    LEFT JOIN departments td ON r.target_department_id = td.id
    WHERE r.patient_id = v_patient_uuid
    ORDER BY r.created_at DESC
    LIMIT p_max_per_section
  ) sub;

  -- ── 14. Triage Assessments ──
  SELECT COALESCE(jsonb_agg(tr ORDER BY tr->>'created_at' DESC), '[]'::jsonb) INTO v_triage
  FROM (
    SELECT jsonb_build_object(
      'created_at', t.created_at,
      'chief_complaint', t.chief_complaint_text,
      'triage_level', t.triage_level,
      'triage_color', t.triage_color,
      'temperature', t.temperature,
      'bp_systolic', t.blood_pressure_systolic,
      'bp_diastolic', t.blood_pressure_diastolic,
      'pulse_rate', t.pulse_rate,
      'respiratory_rate', t.respiratory_rate,
      'oxygen_saturation', t.oxygen_saturation,
      'weight', t.weight,
      'pain_score', t.pain_score,
      'consciousness', t.consciousness::text,
      'triaged_by', COALESCE(s.first_name || ' ' || s.last_name, 'Unknown')
    ) AS tr
    FROM triage_assessments t
    LEFT JOIN staff s ON t.triaged_by = s.id
    WHERE t.patient_id = v_patient_uuid
    ORDER BY t.created_at DESC
    LIMIT p_max_per_section
  ) sub;

  -- ── Assemble result ──
  v_result := jsonb_build_object(
    'demographics', v_demographics,
    'encounters', v_encounters,
    'consultations', v_consultations,
    'nursing_notes', v_nursing_notes,
    'vitals', v_vitals,
    'lab_results', v_lab_results,
    'radiology', v_radiology,
    'prescriptions', v_prescriptions,
    'admissions', v_admissions,
    'ward_round_notes', v_ward_rounds,
    'daily_progress_notes', v_progress_notes,
    'procedures', v_procedures,
    'referrals', v_referrals,
    'triage', v_triage,
    'generated_at', NOW()
  );

  RETURN v_result;
END;
$$;


--
-- Name: get_patient_encounter_details(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_patient_encounter_details(p_patient_id uuid, p_encounter_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_patient_uuid uuid;
  v_result jsonb;
BEGIN
  -- Resolve patient ID
  SELECT p.id INTO v_patient_uuid FROM patients p WHERE p.id = p_patient_id;
  IF v_patient_uuid IS NULL THEN
    SELECT p.id INTO v_patient_uuid FROM patients p WHERE p.patient_id = p_patient_id::text;
  END IF;
  IF v_patient_uuid IS NULL THEN
    RAISE EXCEPTION 'Patient not found';
  END IF;

  -- Verify the encounter belongs to this patient
  IF NOT EXISTS (
    SELECT 1 FROM visits WHERE id = p_encounter_id AND patient_id = v_patient_uuid
  ) THEN
    RAISE EXCEPTION 'Encounter not found for this patient';
  END IF;

  SELECT jsonb_build_object(
    'encounter', (
      SELECT jsonb_build_object(
        'id', v.id, 'visit_id', v.visit_id, 'encounter_date', v.encounter_date,
        'visit_type', v.visit_type, 'chief_complaint', v.chief_complaint,
        'status', v.status::text, 'category', v.encounter_category,
        'attending_doctor', COALESCE(s.first_name || ' ' || s.last_name, 'Not assigned'),
        'discharge_date', v.discharge_date, 'discharge_notes', v.discharge_notes
      )
      FROM visits v LEFT JOIN staff s ON v.attending_doctor_id = s.id
      WHERE v.id = p_encounter_id
    ),
    'consultations', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'consultation_date', c.consultation_date,
        'complaints', c.complaints, 'history_of_present_illness', c.history_of_present_illness,
        'examination_findings', c.examination_findings, 'assessment', c.assessment,
        'plan', c.plan, 'diagnosis', c.diagnosis, 'diagnosis_text', c.diagnosis_text,
        'icd10_codes', c.icd10_codes, 'clinical_notes', c.clinical_notes,
        'treatment_plan', c.treatment_plan,
        'doctor_name', COALESCE(s.first_name || ' ' || s.last_name, 'Unknown')
      ))
      FROM consultations c LEFT JOIN staff s ON c.doctor_id = s.staff_id
      WHERE c.encounter_id = p_encounter_id
    ), '[]'::jsonb),
    'vitals', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'date_recorded', vt.date_recorded,
        'temperature', vt.temperature, 'blood_pressure', vt.blood_pressure,
        'pulse', vt.pulse, 'respiratory_rate', vt.respiratory_rate,
        'oxygen_saturation', vt.oxygen_saturation, 'weight', vt.weight,
        'pain_level', vt.pain_level,
        'recorded_by', COALESCE(s.first_name || ' ' || s.last_name, 'Unknown')
      ) ORDER BY vt.date_recorded DESC)
      FROM vitals vt LEFT JOIN staff s ON vt.nurse_id = s.id
      WHERE vt.encounter_id = p_encounter_id
    ), '[]'::jsonb),
    'nursing_notes', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'title', n.title, 'content', n.content, 'note_type', n.note_type,
        'patient_condition', n.patient_condition, 'is_critical', n.is_critical,
        'created_at', n.created_at,
        'nurse_name', COALESCE(s.first_name || ' ' || s.last_name, 'Unknown')
      ) ORDER BY n.created_at DESC)
      FROM nursing_notes n LEFT JOIN staff s ON n.recorded_by = s.id
      WHERE n.encounter_id = p_encounter_id
    ), '[]'::jsonb),
    'lab_requests', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'created_at', lr.created_at, 'status', lr.status::text,
        'test_name', COALESCE(cat.name, 'Unknown'), 'clinical_notes', lr.clinical_notes,
        'result_value', COALESCE(res.result_value, lr.result_value::text),
        'reference_range', COALESCE(res.reference_range, lr.reference_range),
        'is_abnormal', res.is_abnormal, 'interpretation', COALESCE(res.interpretation, lr.interpretation),
        'ordered_by', COALESCE(s.first_name || ' ' || s.last_name, 'Unknown')
      ) ORDER BY lr.created_at DESC)
      FROM lab_requests lr
      LEFT JOIN lab_test_catalogue cat ON lr.test_id = cat.id
      LEFT JOIN lab_results res ON res.request_id = lr.request_id
      LEFT JOIN staff s ON lr.ordered_by = s.staff_id
      WHERE lr.encounter_id = p_encounter_id
    ), '[]'::jsonb),
    'radiology', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'imaging_type', r.imaging_type, 'body_part', r.body_part,
        'clinical_indication', r.clinical_indication, 'status', r.status::text,
        'findings', COALESCE(sr.findings, r.findings),
        'impression', COALESCE(sr.impression, r.impression),
        'ordered_by', COALESCE(s.first_name || ' ' || s.last_name, 'Unknown')
      ) ORDER BY r.created_at DESC)
      FROM radiology_requests r
      LEFT JOIN scan_results sr ON sr.request_id = r.request_id
      LEFT JOIN staff s ON r.ordered_by = s.staff_id
      WHERE r.encounter_id = p_encounter_id
    ), '[]'::jsonb),
    'prescriptions', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'drug_name', COALESCE(p.drug_name, dc.name, 'Unknown'),
        'dosage', p.dosage, 'frequency', p.frequency, 'duration', p.duration,
        'route', p.route, 'instructions', p.instructions, 'status', p.status::text,
        'prescribed_by', COALESCE(s.first_name || ' ' || s.last_name, 'Unknown')
      ) ORDER BY p.created_at DESC)
      FROM prescriptions p
      LEFT JOIN drug_catalogue dc ON p.drug_id = dc.id
      LEFT JOIN staff s ON p.doctor_id = s.staff_id
      WHERE p.encounter_id = p_encounter_id
    ), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- Name: get_pharmacy_inventory_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_pharmacy_inventory_stats() RETURNS json
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_result JSON;
BEGIN
    SELECT json_build_object(
        'total_drugs', (SELECT COUNT(*) FROM drug_catalogue WHERE is_active = true),
        'total_batches', (
            SELECT COUNT(*) FROM drug_batches 
            WHERE status = 'active' AND quantity_remaining > 0 AND expiry_date > CURRENT_DATE
        ),
        'low_stock_count', (
            SELECT COUNT(DISTINCT drug_id) 
            FROM v_drug_inventory_summary 
            WHERE stock_status = 'low_stock'
        ),
        'out_of_stock_count', (
            -- Only count drugs that should be tracked (not 'not_stocked')
            SELECT COUNT(DISTINCT drug_id) 
            FROM v_drug_inventory_summary 
            WHERE stock_status = 'out_of_stock'
        ),
        'expiring_30_days', (
            SELECT COUNT(*) FROM drug_batches 
            WHERE status = 'active' 
              AND quantity_remaining > 0 
              AND expiry_date > CURRENT_DATE 
              AND expiry_date <= CURRENT_DATE + INTERVAL '30 days'
        ),
        'expiring_60_days', (
            SELECT COUNT(*) FROM drug_batches 
            WHERE status = 'active' 
              AND quantity_remaining > 0 
              AND expiry_date > CURRENT_DATE + INTERVAL '30 days'
              AND expiry_date <= CURRENT_DATE + INTERVAL '60 days'
        ),
        'expiring_90_days', (
            SELECT COUNT(*) FROM drug_batches 
            WHERE status = 'active' 
              AND quantity_remaining > 0 
              AND expiry_date > CURRENT_DATE + INTERVAL '60 days'
              AND expiry_date <= CURRENT_DATE + INTERVAL '90 days'
        ),
        'expired_batches', (
            SELECT COUNT(*) FROM drug_batches 
            WHERE quantity_remaining > 0 
              AND expiry_date <= CURRENT_DATE
        ),
        'total_stock_value_cost', (
            SELECT COALESCE(SUM(quantity_remaining * cost_price), 0) 
            FROM drug_batches 
            WHERE status = 'active' AND expiry_date > CURRENT_DATE
        ),
        'total_stock_value_selling', (
            SELECT COALESCE(SUM(db.quantity_remaining * dc.price), 0) 
            FROM drug_batches db
            JOIN drug_catalogue dc ON dc.id = db.drug_id
            WHERE db.status = 'active' AND db.expiry_date > CURRENT_DATE
        ),
        'dispensed_today_count', (
            SELECT COUNT(*) FROM dispense_records 
            WHERE DATE(dispensed_at) = CURRENT_DATE
        ),
        'received_today_count', (
            SELECT COUNT(*) FROM drug_batches 
            WHERE DATE(received_date) = CURRENT_DATE
        )
    ) INTO v_result;
    
    RETURN v_result;
END;
$$;


--
-- Name: get_queue_statistics(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_queue_statistics(p_clinic_id uuid) RETURNS TABLE(total_waiting integer, emergency_count integer, urgent_count integer, normal_count integer, avg_wait_time interval, longest_wait interval)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        COUNT(*)::INTEGER as total_waiting,
        COUNT(*) FILTER (WHERE priority = 'Emergency')::INTEGER as emergency_count,
        COUNT(*) FILTER (WHERE priority = 'Urgent')::INTEGER as urgent_count,
        COUNT(*) FILTER (WHERE priority = 'Normal')::INTEGER as normal_count,
        AVG(NOW() - wait_start_time) as avg_wait_time,
        MAX(NOW() - wait_start_time) as longest_wait
    FROM queue
    WHERE clinic_id = p_clinic_id
    AND status = 'Waiting';
END;
$$;


--
-- Name: get_record_version(character varying, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_record_version(p_table_name character varying, p_record_id uuid) RETURNS TABLE(current_version integer, last_modified_by uuid, last_modified_at timestamp with time zone)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $_$
BEGIN
  CASE lower(p_table_name)
    WHEN 'patients' THEN
      RETURN QUERY
      SELECT p.version, p.last_modified_by, p.updated_at
      FROM public.patients p
      WHERE p.id = p_record_id;

    WHEN 'encounters' THEN
      RETURN QUERY
      SELECT v.version, v.last_modified_by, v.updated_at
      FROM public.visits v
      WHERE v.id = p_record_id;

    WHEN 'visits' THEN
      RETURN QUERY
      SELECT v.version, v.last_modified_by, v.updated_at
      FROM public.visits v
      WHERE v.id = p_record_id;

    WHEN 'consultations' THEN
      RETURN QUERY
      SELECT c.version, c.last_modified_by, c.updated_at
      FROM public.consultations c
      WHERE c.consultation_id = p_record_id;

    WHEN 'billing_orders' THEN
      RETURN QUERY
      SELECT b.version, b.last_modified_by, b.updated_at
      FROM public.billing_orders b
      WHERE b.id = p_record_id;

    WHEN 'prescriptions' THEN
      RETURN QUERY
      SELECT pr.version, pr.last_modified_by, pr.updated_at
      FROM public.prescriptions pr
      WHERE pr.prescription_id = p_record_id;

    WHEN 'lab_requests' THEN
      RETURN QUERY
      SELECT lr.version, lr.last_modified_by, lr.updated_at
      FROM public.lab_requests lr
      WHERE lr.request_id = p_record_id;

    WHEN 'radiology_requests' THEN
      RETURN QUERY
      SELECT rr.version, rr.last_modified_by, rr.updated_at
      FROM public.radiology_requests rr
      WHERE rr.request_id = p_record_id;

    WHEN 'admissions' THEN
      RETURN QUERY
      SELECT a.version, a.last_modified_by, a.updated_at
      FROM public.admissions a
      WHERE a.id = p_record_id;

    WHEN 'procedures' THEN
      RETURN QUERY
      SELECT proc.version, proc.last_modified_by, proc.updated_at
      FROM public.procedures proc
      WHERE proc.id = p_record_id;

    WHEN 'vitals' THEN
      RETURN QUERY
      SELECT v.version, v.last_modified_by, v.updated_at
      FROM public.vitals v
      WHERE v.id = p_record_id;

    WHEN 'nursing_notes' THEN
      RETURN QUERY
      SELECT nn.version, nn.last_modified_by, nn.updated_at
      FROM public.nursing_notes nn
      WHERE nn.id = p_record_id;

    WHEN 'diagnoses' THEN
      IF to_regclass('public.diagnoses') IS NOT NULL THEN
        RETURN QUERY EXECUTE
          'SELECT d.version, d.last_modified_by, d.updated_at
           FROM public.diagnoses d
           WHERE d.id = $1'
        USING p_record_id;
      END IF;

    WHEN 'ward_rounds' THEN
      IF to_regclass('public.ward_rounds') IS NOT NULL THEN
        RETURN QUERY EXECUTE
          'SELECT wr.version, wr.last_modified_by, wr.updated_at
           FROM public.ward_rounds wr
           WHERE wr.id = $1'
        USING p_record_id;
      END IF;

    ELSE
      RAISE EXCEPTION 'Unsupported table: %', p_table_name
        USING ERRCODE = 'P0001';
  END CASE;
END;
$_$;


--
-- Name: get_shift_date(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_shift_date(p_timestamp timestamp with time zone DEFAULT now()) RETURNS date
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_time TIME;
    v_date DATE;
BEGIN
    v_time := p_timestamp::TIME;
    v_date := p_timestamp::DATE;
    
    -- For night shift after midnight (00:00-07:00), 
    -- the shift date is the previous day
    IF v_time >= '00:00'::TIME AND v_time < '07:00'::TIME THEN
        RETURN v_date - INTERVAL '1 day';
    ELSE
        RETURN v_date;
    END IF;
END;
$$;


--
-- Name: get_specialty_comprehensive_stats(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_specialty_comprehensive_stats(p_specialty_code character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
  v_config RECORD;
  v_exam_stats jsonb;
  v_table_exists boolean;
BEGIN
  -- Access control
  IF NOT can_access_specialty(p_specialty_code) THEN
    RAISE EXCEPTION 'Access denied to specialty: %', p_specialty_code;
  END IF;

  -- Get config
  SELECT * INTO v_config 
  FROM specialty_departments 
  WHERE specialty_code = p_specialty_code AND is_active = true;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Specialty not found: %', p_specialty_code;
  END IF;

  -- Check which specialty tables exist
  -- For specialties with dedicated tables, fall back to consultations if table doesn't exist
  
  IF p_specialty_code = 'DENTAL' THEN
    SELECT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'dental_exams' AND table_schema = 'public') INTO v_table_exists;
    IF v_table_exists THEN
      SELECT jsonb_build_object(
        'exams_today', (
          SELECT COUNT(*) FROM dental_exams de 
          LEFT JOIN visits v ON v.id = de.encounter_id 
          WHERE de.created_at::date = CURRENT_DATE AND (v.status IS NULL OR v.status IN ('Active', 'Closed'))
        ),
        'exams_pending', (
          SELECT COUNT(*) FROM dental_exams de 
          LEFT JOIN visits v ON v.id = de.encounter_id 
          WHERE de.status = 'Pending' AND (v.status IS NULL OR v.status IN ('Active', 'Closed'))
        ),
        'procedures_pending', COALESCE((
          SELECT COUNT(*) FROM dental_procedures dp 
          LEFT JOIN visits v ON v.id = dp.encounter_id 
          WHERE dp.status = 'Pending' AND (v.status IS NULL OR v.status IN ('Active', 'Closed'))
        ), 0),
        'procedures_today', COALESCE((
          SELECT COUNT(*) FROM dental_procedures dp 
          LEFT JOIN visits v ON v.id = dp.encounter_id 
          WHERE dp.procedure_date::date = CURRENT_DATE AND (v.status IS NULL OR v.status IN ('Active', 'Closed'))
        ), 0),
        'teeth_charted_today', COALESCE((
          SELECT COUNT(*) FROM dental_chart dc 
          LEFT JOIN visits v ON v.id = dc.encounter_id 
          WHERE dc.recorded_at::date = CURRENT_DATE AND (v.status IS NULL OR v.status IN ('Active', 'Closed'))
        ), 0)
      ) INTO v_exam_stats;
    ELSE
      v_exam_stats := jsonb_build_object('message', 'Dental tables not yet created');
    END IF;
      
  ELSIF p_specialty_code = 'OPHTHALMOLOGY' THEN
    SELECT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'eye_exams' AND table_schema = 'public') INTO v_table_exists;
    IF v_table_exists THEN
      SELECT jsonb_build_object(
        'exams_today', (
          SELECT COUNT(*) FROM eye_exams ee 
          LEFT JOIN visits v ON v.id = ee.encounter_id 
          WHERE ee.created_at::date = CURRENT_DATE AND (v.status IS NULL OR v.status IN ('Active', 'Closed'))
        ),
        'exams_pending', (
          SELECT COUNT(*) FROM eye_exams ee 
          LEFT JOIN visits v ON v.id = ee.encounter_id 
          WHERE ee.status = 'Pending' AND (v.status IS NULL OR v.status IN ('Active', 'Closed'))
        ),
        'glasses_prescribed_today', (
          SELECT COUNT(*) FROM eye_exams ee 
          LEFT JOIN visits v ON v.id = ee.encounter_id 
          WHERE ee.created_at::date = CURRENT_DATE AND ee.glasses_prescribed = true AND (v.status IS NULL OR v.status IN ('Active', 'Closed'))
        ),
        'surgeries_recommended_month', (
          SELECT COUNT(*) FROM eye_exams ee 
          LEFT JOIN visits v ON v.id = ee.encounter_id 
          WHERE ee.created_at >= CURRENT_DATE - INTERVAL '30 days' AND ee.surgery_recommended = true AND (v.status IS NULL OR v.status IN ('Active', 'Closed'))
        )
      ) INTO v_exam_stats;
    ELSE
      v_exam_stats := jsonb_build_object('message', 'Eye exams table not yet created');
    END IF;
      
  ELSIF p_specialty_code = 'PHYSIOTHERAPY' THEN
    SELECT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'physio_assessments' AND table_schema = 'public') INTO v_table_exists;
    IF v_table_exists THEN
      SELECT jsonb_build_object(
        'assessments_today', (
          SELECT COUNT(*) FROM physio_assessments pa 
          LEFT JOIN visits v ON v.id = pa.encounter_id 
          WHERE pa.created_at::date = CURRENT_DATE AND (v.status IS NULL OR v.status IN ('Active', 'Closed'))
        ),
        'assessments_pending', (
          SELECT COUNT(*) FROM physio_assessments pa 
          LEFT JOIN visits v ON v.id = pa.encounter_id 
          WHERE pa.status = 'Pending' AND (v.status IS NULL OR v.status IN ('Active', 'Closed'))
        ),
        'sessions_today', COALESCE((
          SELECT COUNT(*) FROM physio_sessions ps
          JOIN physio_plans pp ON pp.plan_id = ps.plan_id
          JOIN physio_assessments pa ON pa.assessment_id = pp.assessment_id
          LEFT JOIN visits v ON v.id = pa.encounter_id
          WHERE ps.session_date::date = CURRENT_DATE AND (v.status IS NULL OR v.status IN ('Active', 'Closed'))
        ), 0),
        'active_plans', COALESCE((
          SELECT COUNT(*) FROM physio_plans pp
          JOIN physio_assessments pa ON pa.assessment_id = pp.assessment_id
          LEFT JOIN visits v ON v.id = pa.encounter_id
          WHERE pp.status = 'Active' AND (v.status IS NULL OR v.status IN ('Active', 'Closed'))
        ), 0),
        'discharges_this_week', COALESCE((
          SELECT COUNT(*) FROM physio_discharge pd
          JOIN physio_assessments pa ON pa.assessment_id = pd.assessment_id
          LEFT JOIN visits v ON v.id = pa.encounter_id
          WHERE pd.discharge_date >= CURRENT_DATE - INTERVAL '7 days' AND (v.status IS NULL OR v.status IN ('Active', 'Closed'))
        ), 0)
      ) INTO v_exam_stats;
    ELSE
      v_exam_stats := jsonb_build_object('message', 'Physio tables not yet created');
    END IF;
      
  ELSE
    -- Generic specialty (uses consultations table)
    SELECT jsonb_build_object(
      'consultations_today', (
        SELECT COUNT(*) FROM consultations c 
        LEFT JOIN visits v ON v.id = c.encounter_id 
        WHERE c.specialty_code = p_specialty_code AND c.consultation_date::date = CURRENT_DATE AND (v.status IS NULL OR v.status IN ('Active', 'Closed'))
      ),
      'consultations_pending', (
        SELECT COUNT(*) FROM consultations c 
        LEFT JOIN visits v ON v.id = c.encounter_id 
        WHERE c.specialty_code = p_specialty_code AND c.status = 'Pending' AND (v.status IS NULL OR v.status IN ('Active', 'Closed'))
      ),
      'consultations_month', (
        SELECT COUNT(*) FROM consultations c 
        LEFT JOIN visits v ON v.id = c.encounter_id 
        WHERE c.specialty_code = p_specialty_code AND c.consultation_date >= CURRENT_DATE - INTERVAL '30 days' AND (v.status IS NULL OR v.status IN ('Active', 'Closed'))
      )
    ) INTO v_exam_stats;
  END IF;

  -- Build result
  v_result := jsonb_build_object(
    'specialty_code', v_config.specialty_code,
    'specialty_name', v_config.specialty_name,
    'icon_name', v_config.icon_name,
    'color_class', v_config.color_class,
    'exam_table_name', v_config.exam_table_name,
    'feature_flags', v_config.feature_flags,
    'exam_stats', v_exam_stats
  );

  RETURN v_result;
END;
$$;


--
-- Name: get_specialty_dashboard(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_specialty_dashboard(p_specialty_code character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_config RECORD;
  v_stats jsonb;
  v_queue jsonb;
  v_referrals jsonb;
  v_procedures jsonb;
  v_exams jsonb;
  v_history jsonb;
  v_user_id uuid;
  v_today date := CURRENT_DATE;
BEGIN
  -- Get current user for access control
  v_user_id := auth.uid();

  -- Verify access to specialty
  IF NOT can_access_specialty(p_specialty_code) THEN
    RAISE EXCEPTION 'Access denied to specialty: %', p_specialty_code;
  END IF;

  -- Get specialty config from specialty_departments table
  SELECT * INTO v_config
  FROM specialty_departments
  WHERE specialty_code = p_specialty_code AND is_active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Specialty not found: %', p_specialty_code;
  END IF;

  -- Calculate stats for today
  SELECT jsonb_build_object(
    'waiting', COALESCE((
      SELECT COUNT(*) FROM queue q
      WHERE (q.specialty_code = p_specialty_code
             OR (q.location::TEXT = v_config.queue_department AND v_config.requires_dedicated_queue = true))
        AND q.status IN ('Waiting', 'Called')
        AND q.created_at::date = v_today
    ), 0),
    'in_progress', COALESCE((
      SELECT COUNT(*) FROM queue q
      WHERE (q.specialty_code = p_specialty_code
             OR (q.location::TEXT = v_config.queue_department AND v_config.requires_dedicated_queue = true))
        AND q.status = 'In Progress'
        AND q.created_at::date = v_today
    ), 0),
    'completed', COALESCE((
      SELECT COUNT(*) FROM queue q
      WHERE (q.specialty_code = p_specialty_code
             OR (q.location::TEXT = v_config.queue_department AND v_config.requires_dedicated_queue = true))
        AND q.status = 'Completed'
        AND q.created_at::date = v_today
    ), 0),
    'pending_referrals', COALESCE((
      SELECT COUNT(*) FROM clinical_requests cr
      WHERE cr.target_specialty_code = p_specialty_code
        AND cr.request_type = 'Referral'
        AND cr.status IN ('Pending', 'Approved')
    ), 0),
    'pending_procedures', COALESCE((
      SELECT COUNT(*) FROM clinical_requests cr
      WHERE cr.target_specialty_code = p_specialty_code
        AND cr.request_type = 'Procedure'
        AND cr.status IN ('Pending', 'Approved', 'Scheduled')
    ), 0),
    'today_total', COALESCE((
      SELECT COUNT(*) FROM queue q
      WHERE (q.specialty_code = p_specialty_code
             OR (q.location::TEXT = v_config.queue_department AND v_config.requires_dedicated_queue = true))
        AND q.created_at::date = v_today
    ), 0)
  ) INTO v_stats;

  -- Get queue (limited to 50 for performance)
  SELECT COALESCE(jsonb_agg(row_to_json(qr.*) ORDER BY qr.created_at ASC), '[]'::jsonb) INTO v_queue
  FROM (
    SELECT q.queue_id, q.queue_number, q.status, q.priority, q.notes,
           q.created_at, q.updated_at, q.called_at, q.seen_at,
           q.visit_id, q.encounter_id,
           p.patient_id, p.first_name, p.surname AS last_name, p.emr_number,
           p.date_of_birth, p.phone_number, p.gender,
           v.visit_date, v.visit_type, v.insurance_type
    FROM queue q
    JOIN patients p ON p.patient_id = q.patient_id
    LEFT JOIN visits v ON v.visit_id = q.visit_id
    WHERE (q.specialty_code = p_specialty_code
           OR (q.location::TEXT = v_config.queue_department AND v_config.requires_dedicated_queue = true))
      AND q.status IN ('Waiting', 'Called', 'In Progress')
      AND q.created_at::date = v_today
    ORDER BY q.priority DESC, q.created_at ASC
    LIMIT 50
  ) qr;

  -- Get referrals (limited to 20)
  SELECT COALESCE(jsonb_agg(row_to_json(rr.*) ORDER BY rr.created_at DESC), '[]'::jsonb) INTO v_referrals
  FROM (
    SELECT cr.request_id, cr.request_type, cr.status, cr.priority, cr.reason,
           cr.clinical_findings, cr.provisional_diagnosis, cr.urgency,
           cr.created_at, cr.updated_at, cr.scheduled_date,
           cr.visit_id, cr.encounter_id,
           p.patient_id, p.first_name, p.surname AS last_name, p.emr_number,
           p.date_of_birth, p.gender,
           s.first_name AS requester_first, s.last_name AS requester_last,
           s.specialty_code AS requester_specialty
    FROM clinical_requests cr
    JOIN patients p ON p.patient_id = cr.patient_id
    LEFT JOIN staff s ON s.staff_id = cr.requested_by
    WHERE cr.target_specialty_code = p_specialty_code
      AND cr.request_type = 'Referral'
      AND cr.status IN ('Pending', 'Approved')
    ORDER BY cr.created_at DESC
    LIMIT 20
  ) rr;

  -- Get scheduled procedures (limited to 20)
  SELECT COALESCE(jsonb_agg(row_to_json(pr.*) ORDER BY pr.created_at DESC), '[]'::jsonb) INTO v_procedures
  FROM (
    SELECT cr.request_id, cr.request_type, cr.status, cr.priority, cr.reason,
           cr.clinical_findings, cr.provisional_diagnosis,
           cr.created_at, cr.updated_at, cr.scheduled_date,
           cr.visit_id, cr.encounter_id,
           p.patient_id, p.first_name, p.surname AS last_name, p.emr_number
    FROM clinical_requests cr
    JOIN patients p ON p.patient_id = cr.patient_id
    WHERE cr.target_specialty_code = p_specialty_code
      AND cr.request_type = 'Procedure'
      AND cr.status IN ('Pending', 'Approved', 'Scheduled')
    ORDER BY cr.created_at DESC
    LIMIT 20
  ) pr;

  -- Get recent exams/consultations (limited to 20)
  SELECT COALESCE(jsonb_agg(row_to_json(se.*) ORDER BY se.created_at DESC), '[]'::jsonb) INTO v_exams
  FROM (
    SELECT c.consultation_id AS id,
           'Consultation' AS exam_type,
           c.status,
           c.examination_findings AS findings,
           c.consultation_date AS created_at,
           c.consultation_date AS completed_at,
           p.first_name, p.surname AS last_name, p.emr_number,
           s.first_name AS examiner_first, s.last_name AS examiner_last
    FROM consultations c
    JOIN patients p ON p.patient_id = c.patient_id
    LEFT JOIN staff s ON s.staff_id = c.doctor_id
    WHERE c.specialty_code = p_specialty_code
      AND c.consultation_date >= (CURRENT_DATE - INTERVAL '7 days')
    ORDER BY c.consultation_date DESC
    LIMIT 20
  ) se;

  -- Get consultation history (limited to 50) with FULL details for viewing
  -- Includes granular history fields so the timeline can display them when
  -- clinical_notes is null (common for consultations saved before migration 210)
  SELECT COALESCE(jsonb_agg(row_to_json(sh.*) ORDER BY sh.consultation_date DESC), '[]'::jsonb) INTO v_history
  FROM (
    SELECT c.consultation_id AS id,
           c.complaints,
           c.complaints AS chief_complaint,
           c.diagnosis,
           c.clinical_notes,
           -- Granular history fields (fallbacks for clinical_notes display)
           c.history_of_present_illness,
           c.past_medical_history,
           c.family_history,
           c.social_history,
           c.review_of_systems,
           -- Examination
           c.examination_findings,
           c.physical_examination,
           c.treatment_plan,
           c.specialty_data,
           c.specialty_code,
           COALESCE(c.icd10_codes, '[]'::jsonb) AS icd_codes,
           c.status,
           p.first_name, p.surname AS last_name, p.emr_number, p.patient_id,
           s.first_name AS doctor_first, s.last_name AS doctor_last,
           c.visit_id, c.encounter_id,
           c.consultation_date,
           c.created_at,
           c.updated_at
    FROM consultations c
    JOIN patients p ON p.patient_id = c.patient_id
    LEFT JOIN staff s ON s.staff_id = c.doctor_id
    WHERE c.specialty_code = p_specialty_code
    ORDER BY c.consultation_date DESC
    LIMIT 50
  ) sh;

  -- Return aggregated dashboard data
  RETURN jsonb_build_object(
    'config', row_to_json(v_config),
    'stats', v_stats,
    'queue', v_queue,
    'referrals', v_referrals,
    'procedures', v_procedures,
    'exams', v_exams,
    'history', v_history
  );
END;
$$;


--
-- Name: get_specialty_template(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_specialty_template(p_specialty_code character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_result JSONB;
BEGIN
    SELECT jsonb_build_object(
        'template', jsonb_build_object(
            'id', t.id,
            'specialty_code', t.specialty_code,
            'specialty_name', t.specialty_name,
            'description', t.description,
            'opd_type', t.opd_type,
            'icon_name', t.icon_name,
            'color_class', t.color_class
        ),
        'sections', COALESCE((
            SELECT jsonb_agg(
                jsonb_build_object(
                    'id', s.id,
                    'section_code', s.section_code,
                    'section_name', s.section_name,
                    'description', s.description,
                    'display_order', s.display_order,
                    'is_required', s.is_required,
                    'is_collapsible', s.is_collapsible,
                    'default_expanded', s.default_expanded,
                    'fields', COALESCE((
                        SELECT jsonb_agg(
                            jsonb_build_object(
                                'id', f.id,
                                'field_code', f.field_code,
                                'field_label', f.field_label,
                                'field_type', f.field_type,
                                'placeholder', f.placeholder,
                                'help_text', f.help_text,
                                'config', f.config,
                                'is_required', f.is_required,
                                'validation_rules', f.validation_rules,
                                'display_order', f.display_order,
                                'width', f.width,
                                'conditional_display', f.conditional_display
                            )
                            ORDER BY f.display_order
                        )
                        FROM public.specialty_template_fields f
                        WHERE f.section_id = s.id
                    ), '[]'::jsonb)
                )
                ORDER BY s.display_order
            )
            FROM public.specialty_template_sections s
            WHERE s.template_id = t.id
        ), '[]'::jsonb)
    ) INTO v_result
    FROM public.specialty_templates t
    WHERE t.specialty_code = p_specialty_code
    AND t.is_active = true;
    
    RETURN COALESCE(v_result, '{}'::jsonb);
END;
$$;


--
-- Name: get_specialty_with_department(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_specialty_with_department(p_specialty_code character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_result JSONB;
BEGIN
  SELECT jsonb_build_object(
    'specialty', jsonb_build_object(
      'id', st.id,
      'specialty_code', st.specialty_code,
      'specialty_name', st.specialty_name,
      'description', st.description,
      'icon_name', st.icon_name,
      'color_class', st.color_class,
      'opd_type', st.opd_type
    ),
    'department', CASE 
      WHEN d.id IS NOT NULL THEN jsonb_build_object(
        'id', d.id,
        'name', d.name,
        'code', d.code,
        'opd_type', d.opd_type
      )
      ELSE NULL
    END
  ) INTO v_result
  FROM public.specialty_templates st
  LEFT JOIN public.departments d ON UPPER(d.name) LIKE '%' || st.specialty_code || '%'
    OR st.specialty_code LIKE '%' || UPPER(d.code) || '%'
  WHERE st.specialty_code = p_specialty_code
  AND st.is_active = true
  LIMIT 1;
  
  RETURN COALESCE(v_result, '{}'::jsonb);
END;
$$;


--
-- Name: get_stale_sessions(character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_stale_sessions(p_location character varying DEFAULT NULL::character varying, p_minutes_threshold integer DEFAULT 60) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result JSONB;
BEGIN
  SELECT jsonb_agg(
    jsonb_build_object(
      'queue_id', queue_id,
      'patient_id', patient_id,
      'emr_number', emr_number,
      'patient_name', patient_first_name || ' ' || patient_last_name,
      'staff_name', staff_first_name || ' ' || staff_last_name,
      'minutes_in_session', ROUND(minutes_in_session::numeric, 0),
      'session_start', session_start,
      'session_health', session_health
    )
  )
  INTO v_result
  FROM v_stale_sessions
  WHERE minutes_in_session >= p_minutes_threshold
    AND (p_location IS NULL OR location = p_location);
  
  RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: notifications; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.notifications (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    user_id uuid,
    department_id uuid,
    type public.notification_type NOT NULL,
    priority public.notification_priority DEFAULT 'Normal'::public.notification_priority,
    title character varying(255) NOT NULL,
    message text NOT NULL,
    entity_type character varying(50),
    entity_id uuid,
    is_read boolean DEFAULT false,
    read_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now(),
    notification_subtype character varying(50),
    target_user_id uuid,
    target_role character varying(50),
    target_department character varying(100),
    encounter_id uuid,
    patient_id character varying(50),
    reference_type character varying(50),
    reference_id uuid,
    action_url character varying(500),
    action_label character varying(100),
    is_dismissed boolean DEFAULT false,
    dismissed_at timestamp with time zone,
    created_by uuid,
    expires_at timestamp with time zone,
    metadata jsonb DEFAULT '{}'::jsonb,
    is_persistent boolean DEFAULT false,
    requires_acknowledgement boolean DEFAULT false,
    acknowledged_at timestamp with time zone,
    repeat_interval_seconds integer,
    max_repeats integer DEFAULT 10,
    repeat_count integer DEFAULT 0,
    last_repeated_at timestamp with time zone,
    escalation_level integer DEFAULT 0,
    snoozed_until timestamp with time zone,
    source_module character varying(50)
);


--
-- Name: get_unacknowledged_notifications(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_unacknowledged_notifications(p_user_id uuid) RETURNS SETOF public.notifications
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
    RETURN QUERY
    SELECT n.*
    FROM notifications n
    WHERE n.user_id = p_user_id
      AND n.requires_acknowledgement = TRUE
      AND n.acknowledged_at IS NULL
      AND n.is_dismissed IS NOT TRUE
      AND (n.snoozed_until IS NULL OR n.snoozed_until < NOW())
      AND (n.expires_at IS NULL OR n.expires_at > NOW())
    ORDER BY 
        CASE n.priority 
            WHEN 'Critical' THEN 0 
            WHEN 'High' THEN 1 
            WHEN 'Normal' THEN 2 
            ELSE 3 
        END,
        n.created_at DESC;
END;
$$;


--
-- Name: get_unread_message_count(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_unread_message_count(p_staff_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    IF p_staff_id IS NULL THEN
        RETURN 0;
    END IF;

    SELECT COUNT(*)::INTEGER INTO v_count
    FROM message_recipients mr
    WHERE mr.recipient_id = p_staff_id
      AND NOT mr.is_read
      AND NOT mr.is_deleted;

    RETURN COALESCE(v_count, 0);
END;
$$;


--
-- Name: get_unread_notification_count(uuid, character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_unread_notification_count(p_user_id uuid, p_user_role character varying DEFAULT NULL::character varying, p_user_department character varying DEFAULT NULL::character varying) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO v_count
    FROM notifications
    WHERE is_dismissed = FALSE
    AND is_read = FALSE
    AND (expires_at IS NULL OR expires_at > NOW())
    AND (
        target_user_id = p_user_id
        OR (target_user_id IS NULL AND target_role = p_user_role)
        OR (target_user_id IS NULL AND target_role IS NULL AND target_department = p_user_department)
        OR (target_user_id IS NULL AND target_role IS NULL AND target_department IS NULL)
    );
    
    RETURN v_count;
END;
$$;


--
-- Name: get_user_activity_summary(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_activity_summary(p_user_id uuid DEFAULT NULL::uuid, p_start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_date timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(user_name text, total_actions integer, critical_actions integer, tables_accessed text[], last_activity timestamp with time zone, login_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
  RETURN QUERY
  WITH activity_stats AS (
    SELECT 
      cal.user_id,
      cal.staff_id,
      COUNT(*) as total_actions,
      COUNT(*) FILTER (WHERE cal.is_critical = true) as critical_actions,
      array_agg(DISTINCT cal.table_name) as tables_accessed,
      MAX(cal.performed_at) as last_activity
    FROM comprehensive_audit_log cal
    WHERE (p_user_id IS NULL OR cal.user_id = p_user_id)
      AND (p_start_date IS NULL OR cal.performed_at >= p_start_date)
      AND (p_end_date IS NULL OR cal.performed_at <= p_end_date)
    GROUP BY cal.user_id, cal.staff_id
  ),
  login_stats AS (
    SELECT 
      usa.user_id,
      COUNT(*) FILTER (WHERE usa.event_type = 'login' AND usa.is_successful = true) as login_count
    FROM user_session_audit usa
    WHERE (p_user_id IS NULL OR usa.user_id = p_user_id)
      AND (p_start_date IS NULL OR usa.created_at >= p_start_date)
      AND (p_end_date IS NULL OR usa.created_at <= p_end_date)
    GROUP BY usa.user_id
  )
  SELECT 
    COALESCE(s.first_name || ' ' || s.last_name, au.email, 'Unknown User') as user_name,
    ast.total_actions::INTEGER,
    ast.critical_actions::INTEGER,
    ast.tables_accessed,
    ast.last_activity,
    COALESCE(ls.login_count, 0)::INTEGER
  FROM activity_stats ast
  LEFT JOIN staff s ON s.id = ast.staff_id
  LEFT JOIN auth.users au ON au.id = ast.user_id
  LEFT JOIN login_stats ls ON ls.user_id = ast.user_id
  ORDER BY ast.last_activity DESC;
END;
$$;


--
-- Name: get_user_facility_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_facility_id() RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
  v_facility_id uuid;
BEGIN
  -- Session variable path (fast path)
  BEGIN
    v_facility_id := current_setting('app.facility_id', true)::uuid;
  EXCEPTION WHEN others THEN
    v_facility_id := NULL;
  END;

  IF v_facility_id IS NOT NULL THEN
    RETURN v_facility_id;
  END IF;

  -- Canonical staff mapping
  SELECT s.facility_id INTO v_facility_id
  FROM public.staff s
  WHERE s.user_id = auth.uid()
  LIMIT 1;

  RETURN v_facility_id;
END;
$$;


--
-- Name: get_user_role(); Type: FUNCTION; Schema: public; Owner: -
