--
-- Name: has_permission(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_permission(p_permission text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
  v_role TEXT;
BEGIN
  -- Try session variable first (fast path)
  v_role := current_setting('app.user_role', true);

  -- Fall back to DB lookup
  IF v_role IS NULL OR v_role = '' THEN
    SELECT s.role INTO v_role
    FROM staff s
    WHERE s.auth_user_id = auth.uid()
    LIMIT 1;
  END IF;

  IF v_role IS NULL THEN RETURN FALSE; END IF;

  -- Admins bypass permission checks
  IF v_role IN ('super_admin', 'admin') THEN RETURN TRUE; END IF;

  RETURN EXISTS (
    SELECT 1
    FROM role_permissions rp
    JOIN permissions p ON p.permission_id = rp.permission_id
    WHERE rp.role = v_role
      AND p.name = p_permission
  );
END;
$$;


