--
-- Name: increment_drug_stock(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_drug_stock(p_drug_id uuid, p_quantity numeric) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_new_qty NUMERIC;
BEGIN
    UPDATE drug_catalogue
    SET stock_quantity = stock_quantity + p_quantity,
        updated_at = now()
    WHERE id = p_drug_id
    RETURNING stock_quantity INTO v_new_qty;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Drug not found: %', p_drug_id;
    END IF;

    RETURN v_new_qty;
END;
$$;


--
-- Name: increment_record_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_record_version() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
  -- Increment version if not explicitly set
  IF NEW.version IS NULL OR NEW.version = OLD.version THEN
    NEW.version := COALESCE(OLD.version, 0) + 1;
  END IF;
  
  -- Always update timestamp
  NEW.updated_at := NOW();
  
  RETURN NEW;
END;
$$;


