-- Name: is_encounter_nhis(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_encounter_nhis(p_encounter_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
  v_insurance_type text;
BEGIN
  SELECT COALESCE(insurance_type, payment_category::text) INTO v_insurance_type
  FROM public.visits
  WHERE id = p_encounter_id;

  RETURN v_insurance_type IS NOT NULL AND UPPER(v_insurance_type) LIKE '%NHIS%';
END;
$$;


