-- Name: is_encounter_writable(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_encounter_writable(encounter_uuid uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
  enc_status TEXT;
BEGIN
  IF encounter_uuid IS NULL THEN
    RETURN FALSE;
  END IF;
  
  SELECT status INTO enc_status
  FROM visits
  WHERE id = encounter_uuid;
  
  RETURN enc_status = 'Active';
END;
$$;


--
-- Name: is_in_quiet_hours(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_in_quiet_hours(p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_master user_notification_master_settings%ROWTYPE;
    v_current_time TIME;
BEGIN
    SELECT * INTO v_master FROM user_notification_master_settings WHERE user_id = p_user_id;
    
    IF v_master IS NULL OR NOT v_master.quiet_hours_enabled THEN
        RETURN FALSE;
    END IF;
    
    v_current_time := CURRENT_TIME;
    
    -- Handle overnight quiet hours (e.g., 22:00 to 06:00)
    IF v_master.quiet_hours_start > v_master.quiet_hours_end THEN
        RETURN v_current_time >= v_master.quiet_hours_start OR v_current_time <= v_master.quiet_hours_end;
    ELSE
        RETURN v_current_time >= v_master.quiet_hours_start AND v_current_time <= v_master.quiet_hours_end;
    END IF;
END;
$$;


