--
-- Name: log_audit_event(public.audit_category, public.audit_action, character varying, character varying, text, public.audit_severity, uuid, character varying, uuid, character varying, jsonb, jsonb, text[], text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_audit_event(p_category public.audit_category, p_action public.audit_action, p_resource_type character varying, p_resource_id character varying, p_description text, p_severity public.audit_severity DEFAULT 'info'::public.audit_severity, p_user_id uuid DEFAULT NULL::uuid, p_patient_id character varying DEFAULT NULL::character varying, p_encounter_id uuid DEFAULT NULL::uuid, p_resource_name character varying DEFAULT NULL::character varying, p_old_values jsonb DEFAULT NULL::jsonb, p_new_values jsonb DEFAULT NULL::jsonb, p_changed_fields text[] DEFAULT NULL::text[], p_reason text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_audit_id UUID;
    v_user_name VARCHAR(200);
    v_user_role VARCHAR(50);
    v_patient_name VARCHAR(200);
BEGIN
    -- Get user details
    IF p_user_id IS NOT NULL THEN
        SELECT CONCAT(first_name, ' ', last_name), role 
        INTO v_user_name, v_user_role
        FROM staff WHERE id = p_user_id;
    END IF;
    
    -- Get patient name
    IF p_patient_id IS NOT NULL THEN
        SELECT CONCAT(first_name, ' ', surname)
        INTO v_patient_name
        FROM patients WHERE patient_id = p_patient_id;
    END IF;
    
    INSERT INTO audit_logs (
        category, action, severity,
        user_id, user_role, user_name,
        resource_type, resource_id, resource_name,
        patient_id, patient_name, encounter_id,
        description,
        old_values, new_values, changed_fields,
        reason, metadata
    ) VALUES (
        p_category, p_action, p_severity,
        p_user_id, v_user_role, v_user_name,
        p_resource_type, p_resource_id, p_resource_name,
        p_patient_id, v_patient_name, p_encounter_id,
        p_description,
        p_old_values, p_new_values, p_changed_fields,
        p_reason, p_metadata
    ) RETURNING id INTO v_audit_id;
    
    RETURN v_audit_id;
END;
$$;


--
-- Name: log_care_team_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_care_team_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        INSERT INTO encounter_access_logs (
            encounter_id, 
            user_id, 
            user_role, 
            action, 
            action_details, 
            was_authorized
        )
        VALUES (
            NEW.encounter_id, 
            COALESCE(NEW.assigned_by, NEW.staff_id), 
            'doctor', 
            'add_to_care_team', 
            'Added ' || NEW.staff_name || ' as ' || NEW.role, 
            true
        );
    ELSIF TG_OP = 'UPDATE' AND OLD.is_active = true AND NEW.is_active = false THEN
        INSERT INTO encounter_access_logs (
            encounter_id, 
            user_id, 
            user_role, 
            action, 
            action_details, 
            was_authorized
        )
        VALUES (
            NEW.encounter_id, 
            NEW.staff_id, 
            'doctor', 
            'remove_from_care_team', 
            'Removed ' || NEW.staff_name || ' from care team', 
            true
        );
    END IF;
    
    -- Update timestamp
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$;


--
-- Name: log_comprehensive_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_comprehensive_audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_old_values JSONB;
    v_new_values JSONB;
    v_changed_fields TEXT[];
    v_description TEXT;
    v_action_type TEXT;
    v_patient_id UUID;
    v_patient_name TEXT;
BEGIN
    -- Determine action type
    IF TG_OP = 'INSERT' THEN
        v_action_type := 'create';
        v_new_values := to_jsonb(NEW);
        v_old_values := NULL;
        v_changed_fields := ARRAY(SELECT jsonb_object_keys(v_new_values));
        v_description := 'Created ' || TG_TABLE_NAME || ' record';
        
        -- Extract patient info if available
        IF TG_TABLE_NAME = 'patients' THEN
            v_patient_id := NEW.id;
            v_patient_name := COALESCE(NEW.first_name || ' ' || NEW.surname, 'Unknown');
            v_description := 'Patient registered: ' || v_patient_name;
        END IF;
        
    ELSIF TG_OP = 'UPDATE' THEN
        v_action_type := 'update';
        v_old_values := to_jsonb(OLD);
        v_new_values := to_jsonb(NEW);
        
        -- Calculate changed fields
        SELECT ARRAY_AGG(key) INTO v_changed_fields
        FROM (
            SELECT key
            FROM jsonb_each(v_new_values)
            WHERE (v_old_values -> key) IS DISTINCT FROM (v_new_values -> key)
            AND key NOT IN ('updated_at', 'version')
        ) changed;
        
        v_description := 'Updated ' || TG_TABLE_NAME || ' - Changed: ' || COALESCE(array_to_string(v_changed_fields, ', '), 'none');
        
        -- Extract patient info if available
        IF TG_TABLE_NAME = 'patients' THEN
            v_patient_id := NEW.id;
            v_patient_name := COALESCE(NEW.first_name || ' ' || NEW.surname, 'Unknown');
        END IF;
        
    ELSIF TG_OP = 'DELETE' THEN
        v_action_type := 'delete';
        v_old_values := to_jsonb(OLD);
        v_new_values := NULL;
        v_changed_fields := ARRAY[]::TEXT[];
        v_description := 'Deleted ' || TG_TABLE_NAME || ' record';
        
        IF TG_TABLE_NAME = 'patients' THEN
            v_patient_id := OLD.id;
            v_patient_name := COALESCE(OLD.first_name || ' ' || OLD.surname, 'Unknown');
        END IF;
    END IF;

    -- Insert audit log entry
    INSERT INTO comprehensive_audit_log (
        event_type,
        table_name,
        record_id,
        action_type,
        description,
        old_values,
        new_values,
        changed_fields,
        patient_id,
        patient_name,
        performed_at
    ) VALUES (
        TG_TABLE_NAME || '_' || v_action_type,
        TG_TABLE_NAME,
        COALESCE(
            v_new_values->>'id', v_old_values->>'id',
            v_new_values->>'consultation_id', v_old_values->>'consultation_id',
            v_new_values->>'request_id', v_old_values->>'request_id',
            v_new_values->>'prescription_id', v_old_values->>'prescription_id',
            v_new_values->>'admission_id', v_old_values->>'admission_id',
            'unknown'
        ),
        v_action_type,
        v_description,
        v_old_values,
        v_new_values,
        COALESCE(v_changed_fields, ARRAY[]::TEXT[]),
        v_patient_id,
        v_patient_name,
        NOW()
    );

    RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: log_nhis_activity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_nhis_activity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
  v_user_id UUID;
  v_staff_id UUID;
  v_user_role VARCHAR(50);
  v_patient_id UUID;
  v_event_type VARCHAR(100);
  v_action_type VARCHAR(50);
  v_ip_address INET;
  v_session_id TEXT;
BEGIN
  -- Get current user context
  v_user_id := auth.uid();
  
  -- Get user details from staff table
  IF v_user_id IS NOT NULL THEN
    SELECT s.id, s.role
    INTO v_staff_id, v_user_role
    FROM staff s 
    WHERE s.user_id = v_user_id
    LIMIT 1;
  END IF;

  -- Determine action and event type
  IF TG_OP = 'INSERT' THEN
    v_action_type := 'create';
    v_event_type := TG_TABLE_NAME || '_created';
    v_patient_id := NEW.patient_id;
  ELSIF TG_OP = 'UPDATE' THEN
    v_action_type := 'update';
    v_event_type := TG_TABLE_NAME || '_modified';
    v_patient_id := NEW.patient_id;
  ELSIF TG_OP = 'DELETE' THEN
    v_action_type := 'delete';
    v_event_type := TG_TABLE_NAME || '_deleted';
    v_patient_id := OLD.patient_id;
  END IF;

  -- Get session context
  BEGIN
    v_ip_address := current_setting('app.client_ip')::INET;
  EXCEPTION WHEN OTHERS THEN
    v_ip_address := NULL;
  END;

  BEGIN
    v_session_id := current_setting('app.session_id');
  EXCEPTION WHEN OTHERS THEN
    v_session_id := NULL;
  END;

  -- Insert NHIS-specific audit record
  INSERT INTO nhis_activity_audit (
    event_type,
    patient_id,
    profile_id,
    encounter_id,
    enrollee_id,
    auth_code,
    user_id,
    staff_id,
    user_role,
    action_type,
    before_state,
    after_state,
    ip_address,
    session_id,
    performed_at
  ) VALUES (
    v_event_type,
    v_patient_id,
    CASE 
      WHEN TG_TABLE_NAME = 'nhis_profiles' THEN COALESCE(NEW.id, OLD.id)
      ELSE COALESCE(NEW.profile_id, OLD.profile_id)
    END,
    COALESCE(NEW.encounter_id, OLD.encounter_id),
    COALESCE(NEW.enrollee_id, OLD.enrollee_id),
    COALESCE(NEW.auth_code, OLD.auth_code, NEW.authorization_code, OLD.authorization_code),
    v_user_id,
    v_staff_id,
    v_user_role,
    v_action_type,
    CASE WHEN TG_OP <> 'INSERT' THEN to_jsonb(OLD) ELSE NULL END,
    CASE WHEN TG_OP <> 'DELETE' THEN to_jsonb(NEW) ELSE NULL END,
    v_ip_address,
    v_session_id,
    NOW()
  );

  -- Return appropriate record
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  ELSE
    RETURN NEW;
  END IF;

EXCEPTION
  WHEN OTHERS THEN
    -- Log error but don't fail the main operation
    RAISE WARNING 'NHIS audit trigger failed: %', SQLERRM;
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    ELSE
      RETURN NEW;
    END IF;
END;
$$;


--
-- Name: log_nursing_action(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_nursing_action() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
  current_user_id UUID;
  current_user_role TEXT;
BEGIN
  -- Get current user info
  SELECT id, role::TEXT INTO current_user_id, current_user_role
  FROM staff
  WHERE user_id = auth.uid()
  LIMIT 1;

  INSERT INTO nursing_audit_log (
    encounter_id,
    patient_id,
    user_id,
    user_role,
    action,
    table_name,
    record_id,
    old_values,
    new_values
  ) VALUES (
    COALESCE(NEW.encounter_id, OLD.encounter_id),
    COALESCE(NEW.patient_id, OLD.patient_id),
    current_user_id,
    current_user_role,
    TG_OP,
    TG_TABLE_NAME,
    COALESCE(NEW.id, OLD.id),
    CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN row_to_json(OLD) ELSE NULL END,
    CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN row_to_json(NEW) ELSE NULL END
  );

  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: log_ownership_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_ownership_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
    IF TG_OP = 'UPDATE' AND OLD.attending_doctor_id IS DISTINCT FROM NEW.attending_doctor_id THEN
        INSERT INTO encounter_access_logs (
            encounter_id, 
            user_id, 
            user_role, 
            action, 
            action_details, 
            was_authorized
        )
        VALUES (
            NEW.id, 
            COALESCE(NEW.attending_doctor_id, OLD.attending_doctor_id), 
            'doctor', 
            'transfer_ownership',
            'Ownership changed from ' || COALESCE(OLD.attending_doctor_id::text, 'none') || 
            ' to ' || COALESCE(NEW.attending_doctor_id::text, 'none'), 
            true
        );
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: log_unauthorized_access(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_unauthorized_access() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_user_id UUID;
    v_user_role VARCHAR(50);
BEGIN
    -- Get current user
    SELECT id, role INTO v_user_id, v_user_role
    FROM staff
    WHERE user_id = auth.uid();
    
    -- Log failed access attempt
    IF v_user_id IS NOT NULL THEN
        INSERT INTO encounter_access_logs (
            encounter_id,
            user_id,
            user_role,
            action,
            action_details,
            was_authorized
        ) VALUES (
            NEW.id,
            v_user_id,
            v_user_role,
            'unauthorized_access_attempt',
            'Attempted to access encounter without authorization',
            false
        );
    END IF;
    
    RETURN NEW;
EXCEPTION
    WHEN OTHERS THEN
        -- Silently fail to not block legitimate operations
        RETURN NEW;
END;
$$;


--
-- Name: log_user_session(uuid, character varying, inet, text, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_user_session(p_user_id uuid, p_event_type character varying, p_ip_address inet DEFAULT NULL::inet, p_user_agent text DEFAULT NULL::text, p_session_id text DEFAULT NULL::text, p_is_successful boolean DEFAULT true, p_failure_reason text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
  v_staff_id UUID;
  v_session_log_id UUID;
BEGIN
  -- Get staff ID
  SELECT id INTO v_staff_id FROM staff WHERE user_id = p_user_id LIMIT 1;

  -- Insert session log
  INSERT INTO user_session_audit (
    user_id,
    staff_id,
    event_type,
    ip_address,
    user_agent,
    session_id,
    login_time,
    logout_time,
    is_successful,
    failure_reason
  ) VALUES (
    p_user_id,
    v_staff_id,
    p_event_type,
    p_ip_address,
    p_user_agent,
    p_session_id,
    CASE WHEN p_event_type = 'login' THEN NOW() ELSE NULL END,
    CASE WHEN p_event_type IN ('logout', 'timeout', 'forced_logout') THEN NOW() ELSE NULL END,
    p_is_successful,
    p_failure_reason
  ) RETURNING id INTO v_session_log_id;

  -- Update session duration for logout events
  IF p_event_type IN ('logout', 'timeout', 'forced_logout') AND p_session_id IS NOT NULL THEN
    UPDATE user_session_audit 
    SET 
      logout_time = NOW(),
      session_duration = NOW() - login_time
    WHERE session_id = p_session_id 
      AND event_type = 'login' 
      AND logout_time IS NULL;
  END IF;

  RETURN v_session_log_id;
END;
$$;


--
-- Name: log_version_conflict(character varying, uuid, integer, integer, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_version_conflict(p_table_name character varying, p_record_id uuid, p_expected_version integer, p_actual_version integer, p_attempted_by uuid, p_last_modified_by uuid, p_client_info jsonb DEFAULT NULL::jsonb) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
  v_log_id UUID;
BEGIN
  INSERT INTO version_conflict_log (
    table_name, record_id, expected_version, actual_version,
    attempted_by, last_modified_by, client_info
  ) VALUES (
    p_table_name, p_record_id, p_expected_version, p_actual_version,
    p_attempted_by, p_last_modified_by, p_client_info
  )
  RETURNING id INTO v_log_id;
  
  RETURN v_log_id;
END;
$$;


--
-- Name: mark_all_messages_read(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_all_messages_read(p_staff_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    updated_count INTEGER;
BEGIN
    UPDATE message_recipients
    SET is_read = true, read_at = now()
    WHERE recipient_id = p_staff_id
      AND NOT is_read
      AND NOT is_deleted;

    GET DIAGNOSTICS updated_count = ROW_COUNT;
    RETURN updated_count;
END;
$$;


--
-- Name: mark_message_read(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_message_read(p_message_id uuid, p_staff_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
    IF p_staff_id IS NULL THEN
        RETURN;
    END IF;

    UPDATE message_recipients
    SET is_read = true, read_at = now()
    WHERE message_id = p_message_id
      AND recipient_id = p_staff_id;
END;
$$;


--
-- Name: mark_notification_read(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_notification_read(p_notification_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
    UPDATE notifications
    SET is_read = TRUE, read_at = NOW()
    WHERE id = p_notification_id
    AND (target_user_id = p_user_id OR target_user_id IS NULL);
    
    RETURN FOUND;
END;
$$;


--
-- Name: nhis_check_service_authorization(uuid, character varying, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nhis_check_service_authorization(p_patient_id uuid, p_service_type character varying, p_encounter_id uuid DEFAULT NULL::uuid) RETURNS TABLE(is_authorized boolean, authorization_id uuid, authorization_status character varying, is_provisional boolean, expires_at timestamp with time zone, reason text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
    -- Check for valid authorization for this service type
    RETURN QUERY
    SELECT 
        TRUE AS is_authorized,
        a.id AS authorization_id,
        a.status::VARCHAR(50) AS authorization_status,
        a.is_provisional,
        a.expiry_date AS expires_at,
        CASE 
            WHEN a.is_provisional THEN 'Provisionally approved: ' || COALESCE(a.provisional_reason, 'Pending official code')
            ELSE 'NHIS authorized'
        END AS reason
    FROM nhis_authorizations a
    WHERE a.patient_id = p_patient_id
        AND a.status = 'active'
        AND a.expiry_date > NOW()
        AND (
            a.specific_service_type IS NULL  -- General authorization covers all
            OR a.specific_service_type = p_service_type
        )
    ORDER BY a.is_provisional ASC, a.created_at DESC  -- Prefer non-provisional
    LIMIT 1;
    
    -- If no result, return not authorized
    IF NOT FOUND THEN
        RETURN QUERY
        SELECT 
            FALSE AS is_authorized,
            NULL::UUID AS authorization_id,
            'none'::VARCHAR(50) AS authorization_status,
            FALSE AS is_provisional,
            NULL::TIMESTAMPTZ AS expires_at,
            'No valid NHIS authorization for ' || p_service_type AS reason;
    END IF;
END;
$$;


--
-- Name: nhis_emergency_override(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nhis_emergency_override(p_encounter_id uuid, p_override_by uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_encounter RECORD;
BEGIN
    -- Get encounter
    SELECT * INTO v_encounter FROM visits WHERE id = p_encounter_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', FALSE, 'error', 'Encounter not found');
    END IF;
    
    -- Update encounter
    UPDATE visits SET
        nhis_verification_status = 'emergency_override',
        nhis_override_by = p_override_by,
        nhis_override_at = NOW(),
        nhis_override_reason = p_reason,
        requires_post_authorization = TRUE,
        updated_at = NOW()
    WHERE id = p_encounter_id;
    
    -- Log audit with emergency flag
    INSERT INTO nhis_audit_log (
        action_type, action_description, entity_type, entity_id,
        patient_id, encounter_id, new_state, performed_by,
        is_emergency_action, emergency_reason
    ) VALUES (
        'EMERGENCY_OVERRIDE', 'Emergency override activated - requires post-authorization',
        'encounter', p_encounter_id, v_encounter.patient_id, p_encounter_id,
        jsonb_build_object('reason', p_reason, 'override_at', NOW()),
        p_override_by, TRUE, p_reason
    );
    
    RETURN jsonb_build_object(
        'success', TRUE,
        'encounter_id', p_encounter_id,
        'status', 'emergency_override',
        'requires_post_authorization', TRUE
    );
END;
$$;


--
-- Name: nhis_enter_official_code(uuid, character varying, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nhis_enter_official_code(p_authorization_id uuid, p_official_code character varying, p_entered_by uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_patient_id UUID;
    v_old_code VARCHAR(100);
BEGIN
    -- Get current authorization details
    SELECT patient_id, auth_code INTO v_patient_id, v_old_code
    FROM nhis_authorizations
    WHERE id = p_authorization_id AND is_provisional = TRUE;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Provisional authorization not found: %', p_authorization_id;
    END IF;
    
    -- Update with official code
    UPDATE nhis_authorizations
    SET 
        auth_code = p_official_code,
        actual_code_received_at = NOW(),
        updated_at = NOW()
    WHERE id = p_authorization_id;
    
    -- Log to audit
    INSERT INTO nhis_audit_log (
        action_type,
        entity_type,
        entity_id,
        patient_id,
        performed_by,
        details
    ) VALUES (
        'official_code_entry',
        'authorization',
        p_authorization_id,
        v_patient_id,
        p_entered_by,
        jsonb_build_object(
            'old_provisional_code', v_old_code,
            'official_code', p_official_code
        )
    );
    
    RETURN TRUE;
END;
$$;


--
-- Name: nhis_provisional_approve(uuid, character varying, text, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nhis_provisional_approve(p_patient_id uuid, p_service_type character varying, p_reason text, p_approved_by uuid, p_encounter_id uuid DEFAULT NULL::uuid, p_expiry_days integer DEFAULT 30) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_auth_id UUID;
    v_profile_id UUID;
    v_expiry_date TIMESTAMPTZ;
BEGIN
    -- Get patient's NHIS profile
    SELECT id INTO v_profile_id
    FROM nhis_profiles
    WHERE patient_id = p_patient_id AND status = 'active'
    LIMIT 1;
    
    IF v_profile_id IS NULL THEN
        RAISE EXCEPTION 'No active NHIS profile found for patient %', p_patient_id;
    END IF;
    
    -- Calculate expiry date
    v_expiry_date := NOW() + (p_expiry_days || ' days')::INTERVAL;
    
    -- Create provisional authorization
    INSERT INTO nhis_authorizations (
        patient_id,
        nhis_profile_id,
        auth_code,
        auth_type,
        start_date,
        expiry_date,
        status,
        specific_service_type,
        is_provisional,
        provisional_reason,
        provisional_approved_by,
        provisional_approved_at,
        created_by
    ) VALUES (
        p_patient_id,
        v_profile_id,
        'PROV-' || TO_CHAR(NOW(), 'YYYYMMDD-HH24MISS'),  -- Temporary provisional code
        'provisional',
        NOW(),
        v_expiry_date,
        'active',
        p_service_type,
        TRUE,
        p_reason,
        p_approved_by,
        NOW(),
        p_approved_by
    )
    RETURNING id INTO v_auth_id;
    
    -- Log to audit
    INSERT INTO nhis_audit_log (
        action_type,
        entity_type,
        entity_id,
        patient_id,
        performed_by,
        details
    ) VALUES (
        'provisional_approval',
        'authorization',
        v_auth_id,
        p_patient_id,
        p_approved_by,
        jsonb_build_object(
            'service_type', p_service_type,
            'reason', p_reason,
            'encounter_id', p_encounter_id,
            'expiry_date', v_expiry_date
        )
    );
    
    RETURN v_auth_id;
END;
$$;


--
-- Name: normalize_text_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_text_token(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT NULLIF(lower(btrim(regexp_replace(COALESCE(p_value, ''), '\s+', ' ', 'g'))), '');
$$;


--
-- Name: notify_critical_result(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_critical_result() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_patient_name TEXT;
    v_test_name TEXT;
BEGIN
    -- Only notify if result is marked as critical
    IF NEW.is_critical = TRUE AND (OLD IS NULL OR OLD.is_critical = FALSE) THEN
        -- Get patient name
        SELECT CONCAT(first_name, ' ', surname) INTO v_patient_name
        FROM patients WHERE patient_id = NEW.patient_id;
        
        -- Get test name
        SELECT name INTO v_test_name
        FROM lab_test_catalogue WHERE id = NEW.test_id;
        
        -- Create urgent notification for ordering doctor
        PERFORM create_notification(
            'CriticalValue'::notification_type,
            '🚨 CRITICAL Lab Result',
            'CRITICAL: ' || COALESCE(v_test_name, 'Lab test') || ' result for ' || COALESCE(v_patient_name, 'Patient') || ' requires immediate attention',
            'critical'::notification_priority,
            NULL,  -- Will need to resolve ordered_by to UUID
            'doctor',  -- Fallback to all doctors
            NULL,
            NEW.encounter_id,
            NEW.patient_id,
            'lab_request',
            NEW.request_id,
            '/lab?request=' || NEW.request_id,
            'View Result',
            NEW.result_entered_by,
            NULL,
            jsonb_build_object('test_name', v_test_name, 'is_critical', true)
        );
    END IF;
    
    RETURN NEW;
END;
$$;


--
-- Name: notify_overdue_vitals(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_overdue_vitals(p_schedule_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_schedule patient_vital_schedules%ROWTYPE;
    v_config vital_schedule_configs%ROWTYPE;
    v_patient_name TEXT;
    v_minutes_overdue INTEGER;
BEGIN
    -- Get schedule details
    SELECT * INTO v_schedule
    FROM patient_vital_schedules
    WHERE id = p_schedule_id AND is_active = TRUE AND is_overdue = TRUE;
    
    IF NOT FOUND THEN
        RETURN FALSE;
    END IF;
    
    -- Check if alert already sent
    IF v_schedule.alert_sent = TRUE THEN
        RETURN FALSE;
    END IF;
    
    -- Get config
    SELECT * INTO v_config
    FROM vital_schedule_configs
    WHERE acuity_level = v_schedule.acuity_level;
    
    -- Get patient name
    SELECT CONCAT(first_name, ' ', surname) INTO v_patient_name
    FROM patients WHERE patient_id = v_schedule.patient_id;
    
    -- Calculate minutes overdue
    v_minutes_overdue := EXTRACT(EPOCH FROM (NOW() - v_schedule.next_vitals_due))::INTEGER / 60;
    
    -- Create notification
    PERFORM create_notification(
        'vitals_overdue'::notification_type,
        '⚠️ Vitals Overdue - ' || v_config.display_name,
        'Vital signs for ' || COALESCE(v_patient_name, 'Patient') || ' are ' || v_minutes_overdue || ' minutes overdue (' || v_config.display_name || ' patient)',
        v_config.alert_priority,
        v_schedule.assigned_nurse_id,  -- Target assigned nurse
        'nurse',  -- Also target all nurses
        NULL,
        v_schedule.encounter_id,
        v_schedule.patient_id,
        'vital_schedule',
        v_schedule.id,
        '/nursing?patient=' || v_schedule.patient_id || '&tab=vitals',
        'Record Vitals',
        NULL,
        NOW() + INTERVAL '1 hour',  -- Expires after 1 hour
        jsonb_build_object(
            'acuity_level', v_schedule.acuity_level,
            'minutes_overdue', v_minutes_overdue,
            'patient_name', v_patient_name
        )
    );
    
    -- Mark alert as sent
    UPDATE patient_vital_schedules
    SET alert_sent = TRUE, alert_sent_at = NOW()
    WHERE id = p_schedule_id;
    
    RETURN TRUE;
END;
$$;


--
-- Name: notify_shift_handover(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_shift_handover() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_patient_name TEXT;
    v_nurse_name TEXT;
BEGIN
    -- Get patient name
    SELECT CONCAT(first_name, ' ', surname) INTO v_patient_name
    FROM patients WHERE patient_id = NEW.patient_id;
    
    -- Get outgoing nurse name
    SELECT CONCAT(first_name, ' ', last_name) INTO v_nurse_name
    FROM staff WHERE id = NEW.outgoing_nurse_id;
    
    -- Create notification for incoming shift nurses
    -- Note: create_notification may not exist yet, wrap in exception handler
    BEGIN
        PERFORM create_notification(
            'shift_handover',  -- type (VARCHAR, will be cast)
            'Shift Handover Available',
            'Nurse ' || COALESCE(v_nurse_name, 'Unknown') || ' has prepared handover notes for ' || COALESCE(v_patient_name, 'Patient'),
            'high',  -- priority (VARCHAR, will be cast)
            NULL,  -- No specific user
            'nurse',  -- Target all nurses
            NULL,
            NEW.encounter_id,
            NEW.patient_id,
            'shift_handover',
            NEW.id,
            '/nursing?encounter=' || NEW.encounter_id || '&tab=handover',
            'View Handover',
            NEW.outgoing_nurse_id,
            NEW.shift_date + INTERVAL '8 hours',  -- Expires after next shift
            jsonb_build_object(
                'from_shift', NEW.from_shift,
                'to_shift', NEW.to_shift,
                'patient_name', v_patient_name
            )
        );
    EXCEPTION
        WHEN undefined_function THEN
            -- create_notification doesn't exist yet, skip
            NULL;
    END;
    
    RETURN NEW;
END;
$$;


--
-- Name: notify_treatment_plan_created(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_treatment_plan_created() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_patient_name TEXT;
    v_patient_external_id VARCHAR(50);
    v_creator_name TEXT;
BEGIN
    -- Get patient name and external patient_id (VARCHAR) - notifications table references patients(patient_id)
    SELECT CONCAT(first_name, ' ', surname), patient_id 
    INTO v_patient_name, v_patient_external_id
    FROM patients WHERE id = NEW.patient_id;
    
    -- Get creator name
    SELECT CONCAT(first_name, ' ', last_name) INTO v_creator_name
    FROM staff WHERE id = NEW.created_by;
    
    -- Create notification for nurses
    -- Note: p_patient_id expects VARCHAR(50) patient_id (like "PT-00001"), not UUID
    PERFORM create_notification(
        'treatment_plan_created',           -- p_type VARCHAR
        'New Treatment Plan',               -- p_title VARCHAR
        'Dr. ' || COALESCE(v_creator_name, 'Unknown') || ' created a treatment plan for ' || COALESCE(v_patient_name, 'Patient'),  -- p_message TEXT
        'high',                             -- p_priority VARCHAR
        NULL,                               -- p_target_user_id UUID
        'nurse',                            -- p_target_role VARCHAR
        NULL,                               -- p_target_department VARCHAR
        NEW.encounter_id,                   -- p_encounter_id UUID
        v_patient_external_id,              -- p_patient_id VARCHAR(50) - use external patient_id
        'treatment_plan',                   -- p_reference_type VARCHAR
        NEW.id,                             -- p_reference_id UUID
        '/medical-records?patient=' || COALESCE(v_patient_external_id, NEW.patient_id::TEXT) || '&tab=treatment-plan',  -- p_action_url VARCHAR
        'View Plan',                        -- p_action_label VARCHAR
        NEW.created_by,                     -- p_created_by UUID
        NULL,                               -- p_expires_at TIMESTAMPTZ
        jsonb_build_object('plan_title', NEW.title, 'plan_id', NEW.id)  -- p_metadata JSONB
    );
    
    RETURN NEW;
END;
$$;


--
-- Name: nurse_has_encounter_access(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nurse_has_encounter_access(encounter_uuid uuid, user_uuid uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
  enc_exists BOOLEAN;
  in_care_team BOOLEAN;
  same_facility BOOLEAN;
BEGIN
  -- Check encounter exists
  SELECT EXISTS(SELECT 1 FROM visits WHERE id = encounter_uuid) INTO enc_exists;
  IF NOT enc_exists THEN
    RETURN FALSE;
  END IF;
  
  -- Check if nurse is in care team for this encounter
  SELECT EXISTS(
    SELECT 1 FROM encounter_care_team
    WHERE encounter_id = encounter_uuid
    AND staff_id = user_uuid
    AND is_active = true
    AND (expires_at IS NULL OR expires_at > NOW())
  ) INTO in_care_team;
  
  IF in_care_team THEN
    RETURN TRUE;
  END IF;
  
  -- Check if nurse is in same facility as the encounter
  SELECT EXISTS(
    SELECT 1 FROM visits v
    JOIN patients p ON v.patient_id = p.id
    JOIN staff s ON s.facility_id = p.facility_id
    WHERE v.id = encounter_uuid
    AND s.id = user_uuid
  ) INTO same_facility;
  
  -- For now, allow same-facility access (can be tightened later)
  RETURN same_facility;
END;
$$;


--
-- Name: populate_message_recipients(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.populate_message_recipients() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    recipient_count INTEGER := 0;
    dept_name TEXT;
BEGIN
    -- For direct messages, create single recipient entry
    IF NEW.recipient_id IS NOT NULL THEN
        INSERT INTO message_recipients (message_id, recipient_id)
        VALUES (NEW.id, NEW.recipient_id)
        ON CONFLICT (message_id, recipient_id) DO NOTHING;
        recipient_count := recipient_count + 1;
    END IF;

    -- For department messages (by ID), create entries for all staff in department
    IF NEW.recipient_department_id IS NOT NULL THEN
        -- Get the department name from departments table
        SELECT name INTO dept_name FROM departments WHERE id = NEW.recipient_department_id;

        -- Match staff by department_id OR department name
        INSERT INTO message_recipients (message_id, recipient_id)
        SELECT NEW.id, s.id
        FROM staff s
        WHERE (
            s.department_id = NEW.recipient_department_id
            OR s.department = dept_name
        )
          AND s.is_active = true
          AND s.id != NEW.sender_id
        ON CONFLICT (message_id, recipient_id) DO NOTHING;

        GET DIAGNOSTICS recipient_count = ROW_COUNT;
    END IF;

    -- For department messages (by name - fallback when departments table is empty)
    IF NEW.recipient_department_name IS NOT NULL THEN
        INSERT INTO message_recipients (message_id, recipient_id)
        SELECT NEW.id, s.id
        FROM staff s
        WHERE s.department = NEW.recipient_department_name
          AND s.is_active = true
          AND s.id != NEW.sender_id
        ON CONFLICT (message_id, recipient_id) DO NOTHING;

        GET DIAGNOSTICS recipient_count = ROW_COUNT;

        IF recipient_count = 0 THEN
            RAISE NOTICE 'No active staff found in department %', NEW.recipient_department_name;
        END IF;
    END IF;

    -- For role-based messages, create entries for all staff with that role
    IF NEW.recipient_role IS NOT NULL THEN
        INSERT INTO message_recipients (message_id, recipient_id)
        SELECT NEW.id, s.id
        FROM staff s
        WHERE s.role::text = NEW.recipient_role
          AND s.is_active = true
          AND s.id != NEW.sender_id
        ON CONFLICT (message_id, recipient_id) DO NOTHING;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: populate_nhis_claim_payer_info(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.populate_nhis_claim_payer_info() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_patient RECORD;
    v_profile RECORD;
    v_hmo_name TEXT;
    v_hmo_id UUID;
BEGIN
    -- Only on INSERT, populate payer fields if not already set
    IF TG_OP = 'INSERT' THEN
        -- Get patient info
        SELECT payer_info, nhis_number INTO v_patient
        FROM patients WHERE id = NEW.patient_id;
        
        -- Get NHIS profile
        SELECT provider_name, scheme_type, enrollee_id INTO v_profile
        FROM nhis_profiles WHERE patient_id = NEW.patient_id
        ORDER BY created_at DESC LIMIT 1;
        
        -- Resolve HMO name: payer_info.scheme is the actual HMO name field
        v_hmo_name := COALESCE(
            NEW.hmo_name,
            v_patient.payer_info->>'scheme',
            v_profile.provider_name
        );
        
        -- Try to resolve hmo_id from nhis_hmos table by name
        IF v_hmo_name IS NOT NULL AND v_hmo_name <> '' THEN
            SELECT id INTO v_hmo_id FROM nhis_hmos WHERE name = v_hmo_name LIMIT 1;
        END IF;
        
        -- Set fields
        NEW.hmo_name := COALESCE(NEW.hmo_name, v_hmo_name);
        NEW.hmo_id := COALESCE(NEW.hmo_id, v_hmo_id);
        NEW.payer_name := COALESCE(NEW.payer_name, v_hmo_name);
        NEW.scheme_type := COALESCE(NEW.scheme_type, v_profile.scheme_type::text);
    END IF;
    
    RETURN NEW;
END;
$$;


