--
-- Name: prevent_billing_on_closed_encounter(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_billing_on_closed_encounter() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_status TEXT;
BEGIN
    -- Only check if encounter_id is set
    IF NEW.encounter_id IS NOT NULL THEN
        SELECT status INTO v_status
        FROM visits
        WHERE id = NEW.encounter_id;

        IF v_status IN ('Closed', 'Cancelled') THEN
            RAISE EXCEPTION 'Cannot create billing for a % encounter (encounter_id: %)',
                v_status, NEW.encounter_id;
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: prevent_closed_encounter_modification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_closed_encounter_modification() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_encounter_status TEXT;
    v_encounter_id UUID;
BEGIN
    -- Get encounter_id from the record (try both column names)
    v_encounter_id := NEW.encounter_id;
    
    IF v_encounter_id IS NULL THEN
        RAISE EXCEPTION 'encounter_id/visit_id is required for clinical data';
    END IF;
    
    -- Check encounter status
    SELECT status::TEXT INTO v_encounter_status
    FROM visits
    WHERE id = v_encounter_id;
    
    IF v_encounter_status IN ('Completed', 'Closed', 'Cancelled') THEN
        -- External study reports arrive after the outpatient encounter has
        -- closed. Result capture is the one legitimate post-encounter write.
        IF TG_TABLE_NAME = 'radiology_requests'
           AND NEW.status IN (
             'Awaiting Report',
             'Preliminary Report',
             'Final Report',
             'Completed',
             'Reported'
           ) THEN
            RETURN NEW;
        END IF;

        RAISE EXCEPTION 'Cannot modify data on closed encounter (status: %)', v_encounter_status;
    END IF;
    
    RETURN NEW;
END;
$$;


--
-- Name: prevent_encounter_deletion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_encounter_deletion() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
  record_count INTEGER;
BEGIN
  -- Check daily_progress_notes
  SELECT COUNT(*) INTO record_count FROM daily_progress_notes WHERE encounter_id = OLD.id;
  IF record_count > 0 THEN
    RAISE EXCEPTION 'Cannot delete encounter with % progress note(s).', record_count;
  END IF;
  
  -- Check consultations
  SELECT COUNT(*) INTO record_count FROM consultations WHERE encounter_id = OLD.id;
  IF record_count > 0 THEN
    RAISE EXCEPTION 'Cannot delete encounter with % consultation(s).', record_count;
  END IF;
  
  -- Check vitals
  SELECT COUNT(*) INTO record_count FROM vitals WHERE encounter_id = OLD.id;
  IF record_count > 0 THEN
    RAISE EXCEPTION 'Cannot delete encounter with % vital record(s).', record_count;
  END IF;
  
  -- Check lab_requests
  SELECT COUNT(*) INTO record_count FROM lab_requests WHERE encounter_id = OLD.id;
  IF record_count > 0 THEN
    RAISE EXCEPTION 'Cannot delete encounter with % lab request(s).', record_count;
  END IF;
  
  -- Check prescriptions
  SELECT COUNT(*) INTO record_count FROM prescriptions WHERE encounter_id = OLD.id;
  IF record_count > 0 THEN
    RAISE EXCEPTION 'Cannot delete encounter with % prescription(s).', record_count;
  END IF;
  
  RETURN OLD;
END;
$$;


--
-- Name: prevent_on_call_overlap(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_on_call_overlap() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_overlap_count INTEGER;
BEGIN
    -- Check for overlapping active schedules for same staff
    SELECT COUNT(*) INTO v_overlap_count
    FROM on_call_schedule
    WHERE staff_id = NEW.staff_id
      AND is_active = true
      AND id != COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)
      AND tstzrange(start_time, end_time) && tstzrange(NEW.start_time, NEW.end_time);
    
    IF v_overlap_count > 0 THEN
        RAISE EXCEPTION 'Staff member already has an overlapping on-call schedule';
    END IF;
    
    -- Update timestamp
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$;


--
-- Name: prevent_patient_deletion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_patient_deletion() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
  record_count INTEGER;
BEGIN
  -- Check visits/encounters
  SELECT COUNT(*) INTO record_count FROM visits WHERE patient_id = OLD.id;
  IF record_count > 0 THEN
    RAISE EXCEPTION 'Cannot delete patient with % encounter(s). Mark as Inactive instead.', record_count;
  END IF;
  
  -- Check consultations
  SELECT COUNT(*) INTO record_count FROM consultations WHERE patient_id::uuid = OLD.id;
  IF record_count > 0 THEN
    RAISE EXCEPTION 'Cannot delete patient with % consultation(s). Mark as Inactive instead.', record_count;
  END IF;
  
  -- Check billing orders
  SELECT COUNT(*) INTO record_count FROM billing_orders WHERE patient_id = OLD.id;
  IF record_count > 0 THEN
    RAISE EXCEPTION 'Cannot delete patient with % billing record(s). Mark as Inactive instead.', record_count;
  END IF;
  
  RETURN OLD;
END;
$$;


--
-- Name: process_nhis_referral_queue(uuid, character varying, uuid, text, text, character varying, public.nhis_tariff_group, text, text, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_nhis_referral_queue(p_queue_id uuid, p_action character varying, p_processed_by uuid, p_notes text DEFAULT NULL::text, p_rejection_reason text DEFAULT NULL::text, p_auth_code character varying DEFAULT NULL::character varying, p_tariff_group public.nhis_tariff_group DEFAULT 'Civilian_HMO'::public.nhis_tariff_group, p_referral_source text DEFAULT NULL::text, p_referral_code text DEFAULT NULL::text, p_referral_date date DEFAULT NULL::date, p_referral_reason text DEFAULT NULL::text, p_referring_clinician text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_queue RECORD;
    v_patient RECORD;
    v_clinic RECORD;
    v_encounter_id uuid;
    v_encounter_number text;
    v_visit_id text;
    v_today_prefix text;
    v_next_seq int;
    v_nhis_profile_id uuid;
    v_authorization_id uuid;
    v_result jsonb;
    v_derived_tariff_group nhis_tariff_group;
    v_staff_id uuid;
    v_is_internal_referral boolean := false;
    v_billing_order_id uuid;
    v_order_number text;
    v_consultation_fee numeric(12,2);
    v_service_description text;
BEGIN
    -- Get staff ID from user ID
    SELECT id INTO v_staff_id FROM staff WHERE user_id = p_processed_by;

    -- Get queue item
    SELECT * INTO v_queue FROM nhis_referral_queue WHERE id = p_queue_id;

    IF v_queue IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Queue item not found');
    END IF;

    IF v_queue.status NOT IN ('pending', 'in_review') THEN
        RETURN jsonb_build_object('success', false, 'error', 'Queue item already processed');
    END IF;

    -- Determine if this is an internal referral
    v_is_internal_referral := (v_queue.request_type = 'internal_nhis_approval');

    -- Get patient info
    SELECT * INTO v_patient FROM patients WHERE id = v_queue.patient_id;

    IF v_patient IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Patient not found');
    END IF;

    -- Derive tariff group
    v_derived_tariff_group := CASE
        WHEN v_patient.insurance_type::text IN ('DHML', 'Military_NHIS') THEN 'Personnel'::nhis_tariff_group
        WHEN v_patient.insurance_type::text = 'Civilian_NHIS' THEN 'Civilian_HMO'::nhis_tariff_group
        WHEN v_patient.insurance_type::text = 'GIFSHIP' THEN 'Civilian_HMO'::nhis_tariff_group
        WHEN v_patient.insurance_type::text = 'Retainership' THEN 'Special'::nhis_tariff_group
        WHEN v_patient.insurance_type::text = 'Private' THEN 'Private'::nhis_tariff_group
        ELSE COALESCE(p_tariff_group, 'Civilian_HMO'::nhis_tariff_group)
    END;

    IF p_action = 'approve' THEN
        -- Get clinic info
        IF v_queue.target_clinic_id IS NOT NULL THEN
            SELECT * INTO v_clinic FROM clinics WHERE id = v_queue.target_clinic_id;
        END IF;

        -- ─── FIX: Lookup real consultation fee from clinic ───
        v_consultation_fee := COALESCE(
            CASE
                WHEN v_queue.visit_type IN ('A&E', 'Emergency') THEN
                    COALESCE(v_clinic.emergency_fee, v_clinic.consultation_fee)
                WHEN v_queue.visit_type IN ('Follow-up', 'Follow Up') THEN
                    COALESCE(v_clinic.follow_up_fee, v_clinic.consultation_fee)
                ELSE v_clinic.consultation_fee
            END,
            0
        );
        v_service_description := COALESCE(v_clinic.clinic_name, 'General') || ' - Consultation';

        -- INTERNAL REFERRAL
        IF v_is_internal_referral THEN
            -- CASE A: Doctor referral (has clinical_request_id)
            IF v_queue.clinical_request_id IS NOT NULL THEN
                UPDATE clinical_requests
                SET
                    nhis_approval_status = 'approved',
                    status = 'Approved',
                    referral_workflow_status = 'Pending_Encounter_Office',
                    updated_at = NOW()
                WHERE id = v_queue.clinical_request_id;

                UPDATE nhis_referral_queue SET
                    status = 'approved',
                    processed_by = v_staff_id,
                    processed_at = NOW(),
                    processing_notes = p_notes
                WHERE id = p_queue_id;

                RETURN jsonb_build_object(
                    'success', true,
                    'action', 'approved',
                    'request_type', 'internal_specialty_referral',
                    'message', 'Internal specialty referral approved. Patient visible in Encounter Office for appointment booking.'
                );
            END IF;

            -- CASE B: Direct encounter request (no clinical_request_id)

            -- Generate encounter number
            SELECT 'ENC-' || TO_CHAR(CURRENT_DATE, 'YYYYMMDD') || '-' ||
                   LPAD((COALESCE(MAX(CAST(SUBSTRING(encounter_number FROM 14) AS INTEGER)), 0) + 1)::text, 4, '0')
            INTO v_encounter_number
            FROM visits
            WHERE encounter_number LIKE 'ENC-' || TO_CHAR(CURRENT_DATE, 'YYYYMMDD') || '-%';

            -- Generate visit_id
            v_today_prefix := 'S-' || TO_CHAR(CURRENT_DATE, 'YYYYMMDD') || '-';
            SELECT COALESCE(MAX(CAST(SUBSTRING(visit_id FROM LENGTH(v_today_prefix) + 1) AS INTEGER)), 0) + 1
            INTO v_next_seq
            FROM visits
            WHERE visit_id LIKE v_today_prefix || '%';
            v_visit_id := v_today_prefix || LPAD(v_next_seq::text, 5, '0');

            -- Create the encounter
            INSERT INTO visits (
                patient_id, visit_id, clinic_id, attending_doctor_id,
                encounter_number, encounter_date, visit_type, status,
                payment_category, insurance_type, nhis_verification_status, chief_complaint
            ) VALUES (
                v_queue.patient_id, v_visit_id, v_queue.target_clinic_id, v_queue.target_doctor_id,
                v_encounter_number, CURRENT_DATE,
                COALESCE(v_queue.visit_type, 'Follow Up'),
                'Active'::visit_status, 'NHIS'::payment_method,
                v_patient.insurance_type, 'verified',
                COALESCE(v_queue.chief_complaint, 'NHIS Approved Encounter')
            )
            RETURNING id INTO v_encounter_id;

            -- Route to NURSING queue
            INSERT INTO queue (
                patient_id, visit_id, encounter_id, clinic_id,
                ticket_number, location, priority, status, notes, created_at, updated_at
            ) VALUES (
                v_queue.patient_id, v_encounter_id, v_encounter_id, v_queue.target_clinic_id,
                'Q-' || LPAD((floor(random() * 9000) + 1000)::text, 4, '0'),
                'Nursing', 'Normal', 'Waiting',
                'Internal NHIS Patient - 100% auto-verified. Proceed to nursing assessment.',
                NOW(), NOW()
            );

            -- Generate billing order number
            SELECT 'BO-' || TO_CHAR(CURRENT_DATE, 'YYYYMMDD') || '-' ||
                   LPAD((COALESCE(MAX(CAST(SUBSTRING(order_number FROM 13) AS INTEGER)), 0) + 1)::text, 4, '0')
            INTO v_order_number
            FROM billing_orders
            WHERE order_number LIKE 'BO-' || TO_CHAR(CURRENT_DATE, 'YYYYMMDD') || '-%';

            -- Create billing order with REAL consultation fee (was hardcoded 0)
            INSERT INTO billing_orders (
                order_number, encounter_id, visit_id, patient_id,
                total_amount, net_amount, nhis_covered, nhis_percentage,
                nhis_payable, patient_payable, status, source_module,
                payment_method, paid_amount, balance_amount, created_at, updated_at
            ) VALUES (
                v_order_number, v_encounter_id, v_encounter_id, v_queue.patient_id,
                v_consultation_fee,     -- was: 0
                v_consultation_fee,     -- was: 0
                TRUE, 100,
                v_consultation_fee,     -- was: 0
                0,                      -- patient pays 0 (NHIS 100%)
                'Paid_NHIS', 'consultation', 'NHIS'::payment_method,
                0, 0, NOW(), NOW()
            )
            RETURNING id INTO v_billing_order_id;

            -- Add billing item with REAL consultation fee (was hardcoded 0)
            INSERT INTO billing_items (
                billing_order_id, item_type, item_name, service_name,
                quantity, unit_price, unit_cost, total_price, gross_amount,
                nhis_covered, nhis_percentage, nhis_payable, patient_payable, status
            ) VALUES (
                v_billing_order_id, 'Consultation',
                v_service_description, v_service_description,
                1,
                v_consultation_fee,     -- was: 0
                v_consultation_fee,     -- was: 0
                v_consultation_fee,     -- was: 0
                v_consultation_fee,     -- was: 0
                TRUE, 100,
                v_consultation_fee,     -- was: 0
                0, 'Paid'
            );

            -- Update queue item
            UPDATE nhis_referral_queue SET
                status = 'approved',
                processed_by = v_staff_id,
                processed_at = NOW(),
                processing_notes = p_notes,
                encounter_id = v_encounter_id
            WHERE id = p_queue_id;

            RETURN jsonb_build_object(
                'success', true,
                'action', 'approved',
                'request_type', 'direct_internal_encounter',
                'encounter_id', v_encounter_id,
                'encounter_number', v_encounter_number,
                'billing_order_id', v_billing_order_id,
                'consultation_fee', v_consultation_fee,
                'next_queue', 'Nursing',
                'message', 'NHIS approved. Encounter created and 100% auto-verified. Consultation fee: ' || v_consultation_fee || '. Routed to Nursing Queue.'
            );
        END IF;

        -- EXTERNAL REFERRAL: Create encounter and route to Nursing

        -- Generate encounter number
        SELECT 'ENC-' || TO_CHAR(CURRENT_DATE, 'YYYYMMDD') || '-' ||
               LPAD((COALESCE(MAX(CAST(SUBSTRING(encounter_number FROM 14) AS INTEGER)), 0) + 1)::text, 4, '0')
        INTO v_encounter_number
        FROM visits
        WHERE encounter_number LIKE 'ENC-' || TO_CHAR(CURRENT_DATE, 'YYYYMMDD') || '-%';

        -- Generate visit_id
        v_today_prefix := 'S-' || TO_CHAR(CURRENT_DATE, 'YYYYMMDD') || '-';
        SELECT COALESCE(MAX(CAST(SUBSTRING(visit_id FROM LENGTH(v_today_prefix) + 1) AS INTEGER)), 0) + 1
        INTO v_next_seq
        FROM visits
        WHERE visit_id LIKE v_today_prefix || '%';
        v_visit_id := v_today_prefix || LPAD(v_next_seq::text, 5, '0');

        -- Create the encounter
        INSERT INTO visits (
            patient_id, visit_id, clinic_id, attending_doctor_id,
            encounter_number, encounter_date, visit_type, status,
            payment_category, insurance_type, nhis_verification_status, chief_complaint
        ) VALUES (
            v_queue.patient_id, v_visit_id, v_queue.target_clinic_id, v_queue.target_doctor_id,
            v_encounter_number, CURRENT_DATE,
            COALESCE(v_queue.visit_type, 'Referred NHIS Patient (External)'),
            'Active'::visit_status, 'NHIS'::payment_method,
            v_patient.insurance_type, 'verified',
            COALESCE(v_queue.chief_complaint, v_queue.clinical_basis, p_referral_reason, 'NHIS Referral')
        )
        RETURNING id INTO v_encounter_id;

        -- Route to NURSING queue
        INSERT INTO queue (
            patient_id, visit_id, encounter_id, clinic_id,
            ticket_number, location, priority, status, notes, created_at, updated_at
        ) VALUES (
            v_queue.patient_id, v_encounter_id, v_encounter_id, v_queue.target_clinic_id,
            'Q-' || LPAD((floor(random() * 9000) + 1000)::text, 4, '0'),
            'Nursing', 'Normal', 'Waiting',
            'External NHIS Referral - 100% auto-verified. Proceed to nursing assessment.',
            NOW(), NOW()
        );

        -- Generate billing order number
        SELECT 'BO-' || TO_CHAR(CURRENT_DATE, 'YYYYMMDD') || '-' ||
               LPAD((COALESCE(MAX(CAST(SUBSTRING(order_number FROM 13) AS INTEGER)), 0) + 1)::text, 4, '0')
        INTO v_order_number
        FROM billing_orders
        WHERE order_number LIKE 'BO-' || TO_CHAR(CURRENT_DATE, 'YYYYMMDD') || '-%';

        -- Create billing order with REAL consultation fee (was hardcoded 0)
        INSERT INTO billing_orders (
            order_number, encounter_id, visit_id, patient_id,
            total_amount, net_amount, nhis_covered, nhis_percentage,
            nhis_payable, patient_payable, status, source_module,
            payment_method, paid_amount, balance_amount, created_at, updated_at
        ) VALUES (
            v_order_number, v_encounter_id, v_encounter_id, v_queue.patient_id,
            v_consultation_fee,     -- was: 0
            v_consultation_fee,     -- was: 0
            TRUE, 100,
            v_consultation_fee,     -- was: 0
            0,                      -- patient pays 0 (NHIS 100%)
            'Paid_NHIS', 'consultation', 'NHIS'::payment_method,
            0, 0, NOW(), NOW()
        )
        RETURNING id INTO v_billing_order_id;

        -- Add billing item with REAL consultation fee (was hardcoded 0)
        INSERT INTO billing_items (
            billing_order_id, item_type, item_name, service_name,
            quantity, unit_price, unit_cost, total_price, gross_amount,
            nhis_covered, nhis_percentage, nhis_payable, patient_payable, status
        ) VALUES (
            v_billing_order_id, 'Consultation',
            v_service_description || ' (NHIS Referral)',
            v_service_description || ' (NHIS Referral)',
            1,
            v_consultation_fee,     -- was: 0
            v_consultation_fee,     -- was: 0
            v_consultation_fee,     -- was: 0
            v_consultation_fee,     -- was: 0
            TRUE, 100,
            v_consultation_fee,     -- was: 0
            0, 'Paid'
        );

        -- Update NHIS Profile
        UPDATE nhis_profiles
        SET status = 'active', verified_by = v_staff_id, verified_at = NOW(), updated_at = NOW()
        WHERE patient_id = v_queue.patient_id
        RETURNING id INTO v_nhis_profile_id;

        IF v_nhis_profile_id IS NULL THEN
            INSERT INTO nhis_profiles (
                patient_id, enrollee_id, scheme_type, provider_name, patient_origin, tariff_group, status, verified_by, verified_at
            ) VALUES (
                v_queue.patient_id,
                COALESCE(v_patient.nhis_number, 'PEND-' || v_patient.patient_id),
                CASE
                    WHEN v_patient.insurance_type::text IN ('Military_NHIS', 'DHML') THEN 'Personnel'::nhis_scheme_type
                    WHEN v_patient.insurance_type::text IN ('Civilian_NHIS', 'GIFSHIP') THEN 'Civilian_NHIS'::nhis_scheme_type
                    ELSE 'Civilian_NHIS'::nhis_scheme_type
                END,
                v_patient.payer_info->>'scheme',
                'referred'::nhis_patient_origin,
                v_derived_tariff_group,
                'active'::nhis_profile_status,
                v_staff_id,
                NOW()
            )
            RETURNING id INTO v_nhis_profile_id;
        ELSE
            -- Update provider_name on existing profiles if NULL
            UPDATE nhis_profiles
            SET provider_name = COALESCE(provider_name, v_patient.payer_info->>'scheme'),
                updated_at = NOW()
            WHERE id = v_nhis_profile_id AND (provider_name IS NULL OR provider_name = '');
        END IF;

        -- Create authorization record
        INSERT INTO nhis_authorizations (
            patient_id, nhis_profile_id, auth_code, auth_type, source, start_date, expiry_date, status,
            referral_source, referral_clinical_basis, referring_clinician, referral_date, referral_code,
            verified_by, verified_at, verification_notes
        ) VALUES (
            v_queue.patient_id, v_nhis_profile_id,
            COALESCE(p_auth_code, 'REF-' || TO_CHAR(NOW(), 'YYYYMMDDHH24MISS')),
            'referral', 'referred_patient', NOW(), NOW() + INTERVAL '30 days', 'active',
            COALESCE(p_referral_source, v_queue.referral_source),
            v_queue.clinical_basis,
            COALESCE(p_referring_clinician, v_queue.referring_clinician),
            COALESCE(p_referral_date, v_queue.referral_date),
            COALESCE(p_referral_code, v_queue.referral_code),
            v_staff_id, NOW(), p_notes
        )
        RETURNING id INTO v_authorization_id;

        -- Update queue item
        UPDATE nhis_referral_queue SET
            status = 'approved',
            processed_by = v_staff_id,
            processed_at = NOW(),
            processing_notes = p_notes,
            authorization_id = v_authorization_id,
            encounter_id = v_encounter_id,
            referral_source = COALESCE(p_referral_source, referral_source),
            referral_code = COALESCE(p_referral_code, referral_code),
            referral_date = COALESCE(p_referral_date, referral_date),
            referring_clinician = COALESCE(p_referring_clinician, referring_clinician)
        WHERE id = p_queue_id;

        -- Update patient referral info
        UPDATE patients SET
            nhis_patient_source = 'Referral',
            referral_code = COALESCE(p_referral_code, referral_code),
            referring_facility_name = COALESCE(p_referral_source, referring_facility_name),
            referral_status = 'Active'::referral_status_enum
        WHERE id = v_queue.patient_id;

        v_result := jsonb_build_object(
            'success', true,
            'action', 'approved',
            'request_type', 'external_referral',
            'encounter_id', v_encounter_id,
            'encounter_number', v_encounter_number,
            'authorization_id', v_authorization_id,
            'billing_order_id', v_billing_order_id,
            'consultation_fee', v_consultation_fee,
            'next_queue', 'Nursing',
            'message', 'External NHIS referral approved. 100% auto-verified. Consultation fee: ' || v_consultation_fee || '. Patient routed to Nursing Queue.'
        );

    ELSIF p_action = 'reject' THEN
        UPDATE nhis_referral_queue SET
            status = 'rejected',
            processed_by = v_staff_id,
            processed_at = NOW(),
            processing_notes = p_notes,
            rejection_reason = p_rejection_reason
        WHERE id = p_queue_id;

        IF v_is_internal_referral AND v_queue.clinical_request_id IS NOT NULL THEN
            UPDATE clinical_requests
            SET nhis_approval_status = 'rejected', status = 'Rejected', referral_workflow_status = 'Cancelled', updated_at = NOW()
            WHERE id = v_queue.clinical_request_id;
        END IF;

        UPDATE patients SET referral_status = 'Cancelled'::referral_status_enum, updated_at = NOW()
        WHERE id = v_queue.patient_id;

        v_result := jsonb_build_object('success', true, 'action', 'rejected', 'message', 'NHIS referral rejected');

    ELSE
        v_result := jsonb_build_object('success', false, 'error', 'Invalid action');
    END IF;

    RETURN v_result;
END;
$$;


--
-- Name: record_clinical_template_usage(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_clinical_template_usage(p_template_id uuid, p_staff_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Global counter
    UPDATE public.clinical_text_templates
    SET usage_count  = usage_count + 1,
        last_used_at = NOW(),
        updated_at   = NOW()
    WHERE id = p_template_id;

    -- Per-user upsert
    INSERT INTO public.clinical_text_template_usage (template_id, staff_id, used_at)
    VALUES (p_template_id, p_staff_id, NOW())
    ON CONFLICT (template_id, staff_id) DO UPDATE
        SET used_at = NOW();
END;
$$;


--
-- Name: record_referral_print(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_referral_print(p_queue_id uuid, p_printed_by uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
    UPDATE nhis_referral_queue
    SET 
        printed_at = NOW(),
        printed_by = p_printed_by,
        print_count = COALESCE(print_count, 0) + 1,
        status = CASE 
            WHEN status = 'approved' THEN 'completed'
            ELSE status 
        END,
        updated_at = NOW()
    WHERE id = p_queue_id;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Referral not found'
        );
    END IF;
    
    RETURN jsonb_build_object(
        'success', true,
        'message', 'Print recorded successfully',
        'queue_id', p_queue_id
    );
END;
$$;


--
-- Name: recover_orphaned_encounters(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recover_orphaned_encounters(p_facility_id uuid DEFAULT NULL::uuid, p_dry_run boolean DEFAULT true) RETURNS TABLE(visit_id uuid, visit_number character varying, patient_name text, current_stage character varying, last_queue_location character varying, action_taken text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_record RECORD;
  v_default_location VARCHAR;
  v_ticket_number VARCHAR;
BEGIN
  -- Find orphaned encounters:
  -- - Visit status is 'Active'
  -- - No queue entry with status in ('Waiting', 'Called', 'In Progress')
  -- - current_stage suggests they should be in a queue
  
  FOR v_record IN
    SELECT 
      v.id,
      v.visit_id AS visit_number,
      COALESCE(p.first_name || ' ' || p.surname, 'Unknown') AS patient_name,
      v.current_stage,
      v.patient_id,
      v.clinic_id,
      v.priority,
      (
        SELECT q.location 
        FROM queue q 
        WHERE q.visit_id = v.id 
        ORDER BY q.completed_at DESC NULLS LAST, q.created_at DESC 
        LIMIT 1
      ) AS last_queue_location
    FROM visits v
    LEFT JOIN patients p ON v.patient_id = p.id
    WHERE v.status = 'Active'
      AND (p_facility_id IS NULL OR v.facility_id = p_facility_id)
      AND NOT EXISTS (
        SELECT 1 FROM queue q 
        WHERE q.visit_id = v.id 
        AND q.status IN ('Waiting', 'Called', 'In Progress')
      )
      -- Only recover encounters in stages that expect a queue entry
      AND v.current_stage IN (
        'registered', 'payment', 'queue_waiting', 'nursing_vitals',
        'consultation', 'billing_final'
      )
      -- Exclude completed or discharged encounters
      AND v.current_stage != 'completed'
      AND v.current_stage != 'encounter_closed'
      -- Only encounters from today (configurable, currently within last 24 hours)
      AND v.created_at > NOW() - INTERVAL '24 hours'
  LOOP
    -- Determine target location based on current_stage and last queue location
    CASE v_record.current_stage
      WHEN 'registered' THEN v_default_location := 'Billing';
      WHEN 'payment' THEN v_default_location := 'Billing';
      WHEN 'queue_waiting' THEN v_default_location := COALESCE(v_record.last_queue_location, 'Nursing');
      WHEN 'nursing_vitals' THEN v_default_location := 'Nursing';
      WHEN 'consultation' THEN v_default_location := 'Consultation';
      WHEN 'billing_final' THEN v_default_location := 'Billing';
      ELSE v_default_location := 'Nursing';
    END CASE;
    
    -- If last queue was already Nursing, next should be Consultation
    IF v_record.last_queue_location = 'Nursing' AND v_record.current_stage = 'queue_waiting' THEN
      v_default_location := 'Consultation';
    END IF;
    
    -- If last queue was Billing, next should be Nursing (for initial payment flow)
    IF v_record.last_queue_location = 'Billing' AND v_record.current_stage IN ('registered', 'payment', 'queue_waiting') THEN
      v_default_location := 'Nursing';
    END IF;
    
    IF NOT p_dry_run THEN
      -- Generate ticket number
      SELECT COALESCE(MAX(CAST(ticket_number AS INTEGER)), 0) + 1 
      INTO v_ticket_number
      FROM queue 
      WHERE location = v_default_location
        AND created_at::date = CURRENT_DATE;
      
      v_ticket_number := COALESCE(v_ticket_number, '1');
      
      -- Create the missing queue entry
      INSERT INTO queue (
        patient_id,
        visit_id,
        encounter_id,
        clinic_id,
        ticket_number,
        location,
        priority,
        status,
        notes,
        created_at
      ) VALUES (
        v_record.patient_id,
        v_record.id,
        v_record.id,
        v_record.clinic_id,
        v_ticket_number,
        v_default_location,
        COALESCE(v_record.priority, 'Normal'),
        'Waiting',
        'Auto-recovered from orphaned state by system',
        NOW()
      );
      
      -- Update current_stage to match the queue location
      UPDATE visits 
      SET 
        current_stage = CASE v_default_location
          WHEN 'Billing' THEN 'payment'
          WHEN 'Nursing' THEN 'queue_waiting'
          WHEN 'Consultation' THEN 'consultation'
          ELSE 'queue_waiting'
        END,
        updated_at = NOW()
      WHERE id = v_record.id;
    END IF;
    
    -- Return results
    visit_id := v_record.id;
    visit_number := v_record.visit_number;
    patient_name := v_record.patient_name;
    current_stage := v_record.current_stage;
    last_queue_location := v_record.last_queue_location;
    action_taken := CASE 
      WHEN p_dry_run THEN 'Would create queue entry for: ' || v_default_location
      ELSE 'Created queue entry for: ' || v_default_location
    END;
    
    RETURN NEXT;
  END LOOP;
  
  RETURN;
END;
$$;


--
-- Name: reject_specialty_referral(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_specialty_referral(p_request_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
  v_staff_id uuid;
  v_specialty_code varchar(50);
BEGIN
  IF p_reason IS NULL OR trim(p_reason) = '' THEN
    RAISE EXCEPTION 'Rejection reason is required';
  END IF;
  
  SELECT id, specialty_code INTO v_staff_id, v_specialty_code
  FROM staff WHERE user_id = auth.uid();
  
  UPDATE clinical_requests SET
    status = 'Rejected',
    referral_rejected_at = now(),
    referral_rejected_by = v_staff_id,
    referral_rejection_reason = p_reason,
    updated_at = now()
  WHERE id = p_request_id
    AND request_type = 'Referral'
    AND target_specialty_code = v_specialty_code
    AND status IN ('Pending', 'Approved')
  RETURNING jsonb_build_object(
    'id', id, 
    'status', status, 
    'rejected_at', referral_rejected_at,
    'rejected_by', v_staff_id,
    'reason', referral_rejection_reason
  ) INTO v_result;
  
  IF v_result IS NULL THEN
    RAISE EXCEPTION 'Referral not found or access denied';
  END IF;
  
  RETURN v_result;
END;
$$;


--
-- Name: release_service_to_billing(character varying, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_service_to_billing(p_service_type character varying, p_service_id uuid, p_released_by uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_encounter_id UUID;
    v_encounter RECORD;
BEGIN
    -- Get encounter based on service type
    CASE p_service_type
        WHEN 'lab_request' THEN
            SELECT encounter_id INTO v_encounter_id FROM lab_requests WHERE request_id = p_service_id;
            UPDATE lab_requests SET 
                billing_release_status = 'released',
                released_by = p_released_by,
                released_at = NOW()
            WHERE request_id = p_service_id;
        WHEN 'radiology_request' THEN
            SELECT encounter_id INTO v_encounter_id FROM radiology_requests WHERE request_id = p_service_id;
            UPDATE radiology_requests SET 
                billing_release_status = 'released',
                released_by = p_released_by,
                released_at = NOW()
            WHERE request_id = p_service_id;
        WHEN 'prescription' THEN
            SELECT encounter_id INTO v_encounter_id FROM prescriptions WHERE prescription_id = p_service_id;
            UPDATE prescriptions SET 
                billing_release_status = 'released',
                released_by = p_released_by,
                released_at = NOW()
            WHERE prescription_id = p_service_id;
        ELSE
            RETURN jsonb_build_object('success', FALSE, 'error', 'Unknown service type');
    END CASE;
    
    -- Get encounter for verification check
    SELECT * INTO v_encounter FROM visits WHERE id = v_encounter_id;
    
    -- Check encounter is verified or emergency_override
    IF v_encounter.nhis_verification_status NOT IN ('verified', 'emergency_override') THEN
        RETURN jsonb_build_object('success', FALSE, 'error', 'Encounter not verified - cannot release to billing');
    END IF;
    
    -- Log audit
    INSERT INTO nhis_audit_log (
        action_type, action_description, entity_type, entity_id,
        encounter_id, performed_by
    ) VALUES (
        'SERVICE_RELEASED', 'Service released to billing',
        p_service_type, p_service_id, v_encounter_id, p_released_by
    );
    
    RETURN jsonb_build_object(
        'success', TRUE,
        'service_type', p_service_type,
        'service_id', p_service_id,
        'released_at', NOW()
    );
END;
$$;


--
-- Name: reopen_encounter(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_encounter(p_encounter_id uuid, p_reopened_by uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_user_role TEXT;
BEGIN
    -- Get user role
    SELECT role::TEXT INTO v_user_role
    FROM staff
    WHERE staff_id = p_reopened_by;
    
    -- Only admins can reopen
    IF v_user_role NOT IN ('admin', 'super_admin', 'medical_director') THEN
        RETURN jsonb_build_object('success', false, 'error', 'Only administrators can reopen encounters');
    END IF;
    
    IF p_reason IS NULL OR LENGTH(TRIM(p_reason)) < 10 THEN
        RETURN jsonb_build_object('success', false, 'error', 'Reopen reason must be at least 10 characters');
    END IF;
    
    -- Reopen the encounter
    UPDATE visits
    SET 
        status = 'Active',
        current_stage = 'in_consultation',
        end_time = NULL,
        closed_by = NULL,
        closed_reason = NULL,
        stage_updated_at = NOW(),
        stage_history = COALESCE(stage_history, '[]'::JSONB) || jsonb_build_object(
            'stage', 'reopened',
            'timestamp', NOW(),
            'performed_by', p_reopened_by,
            'notes', 'Encounter reopened: ' || p_reason
        )
    WHERE visit_id = p_encounter_id;
    
    -- Log the reopen
    INSERT INTO clinical_audit_log (
        encounter_id, patient_id, action, entity_type, entity_id,
        performed_by, notes
    )
    SELECT 
        visit_id, patient_id, 'REOPEN', 'encounter', visit_id,
        p_reopened_by,
        p_reason
    FROM visits
    WHERE visit_id = p_encounter_id;
    
    RETURN jsonb_build_object(
        'success', true,
        'encounter_id', p_encounter_id,
        'status', 'Active',
        'reopened_at', NOW()
    );
END;
$$;


--
-- Name: clinical_note_templates; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.clinical_note_templates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    template_key character varying(100) NOT NULL,
    display_name character varying(200) NOT NULL,
    description text,
    note_type character varying(50) NOT NULL,
    specialty_clinic_id uuid,
    specialty_code character varying(50),
    department_id uuid,
    role character varying(50),
    encounter_type character varying(50),
    patient_context character varying(50),
    schema_json jsonb DEFAULT '{"sections": []}'::jsonb NOT NULL,
    base_fields jsonb DEFAULT '["subjective", "objective", "assessment", "plan"]'::jsonb NOT NULL,
    ui_config jsonb DEFAULT '{}'::jsonb,
    priority integer DEFAULT 0 NOT NULL,
    is_default boolean DEFAULT false NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    created_by uuid
);


--
-- Name: resolve_note_template(character varying, character varying, uuid, character varying, character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_note_template(p_note_type character varying, p_specialty_code character varying DEFAULT NULL::character varying, p_clinic_id uuid DEFAULT NULL::uuid, p_role character varying DEFAULT NULL::character varying, p_encounter_type character varying DEFAULT NULL::character varying, p_patient_context character varying DEFAULT NULL::character varying) RETURNS public.clinical_note_templates
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_template public.clinical_note_templates;
BEGIN
    -- Find the most specific matching active template
    -- Priority order: specialty+role+encounter+context > specialty+role > specialty > role > generic default
    SELECT * INTO v_template
    FROM public.clinical_note_templates
    WHERE is_active = true
      AND note_type = p_note_type
      AND (specialty_code IS NULL OR specialty_code = p_specialty_code)
      AND (specialty_clinic_id IS NULL OR specialty_clinic_id = p_clinic_id)
      AND (role IS NULL OR role = p_role)
      AND (encounter_type IS NULL OR encounter_type = p_encounter_type)
      AND (patient_context IS NULL OR patient_context = p_patient_context)
    ORDER BY priority DESC,
             -- Tiebreaker: most non-null matching columns = more specific
             (CASE WHEN specialty_code IS NOT NULL AND specialty_code = p_specialty_code THEN 1 ELSE 0 END
              + CASE WHEN role IS NOT NULL AND role = p_role THEN 1 ELSE 0 END
              + CASE WHEN encounter_type IS NOT NULL AND encounter_type = p_encounter_type THEN 1 ELSE 0 END
              + CASE WHEN patient_context IS NOT NULL AND patient_context = p_patient_context THEN 1 ELSE 0 END
             ) DESC
    LIMIT 1;

    RETURN v_template;
END;
$$;


--
-- Name: resume_specialty_session(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resume_specialty_session(p_queue_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result JSONB;
  v_staff_id UUID;
  v_is_admin BOOLEAN;
  v_queue RECORD;
  v_patient RECORD;
  v_visit RECORD;
BEGIN
  -- Get current staff
  SELECT id, role::text IN ('super_admin', 'admin', 'medical_director', 'Admin', 'System_Admin', 'Medical_Director')
  INTO v_staff_id, v_is_admin
  FROM staff 
  WHERE user_id = auth.uid();
  
  IF v_staff_id IS NULL THEN
    RAISE EXCEPTION 'Staff not found for current user';
  END IF;
  
  -- Get queue entry with lock
  SELECT q.*, 
         p.patient_id AS emr_number,
         p.first_name,
         p.surname AS last_name,
         p.date_of_birth,
         p.gender
  INTO v_queue
  FROM queue q
  LEFT JOIN patients p ON p.id = q.patient_id
  WHERE q.id = p_queue_id
  FOR UPDATE OF q;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Queue entry not found'
    );
  END IF;
  
  -- Check if session is in progress
  IF v_queue.status != 'In Progress' THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Session is not in progress',
      'current_status', v_queue.status
    );
  END IF;
  
  -- Check permission: only session owner or admin can resume
  IF NOT v_is_admin AND v_queue.assigned_to IS NOT NULL AND v_queue.assigned_to != v_staff_id THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Session assigned to another staff member'
    );
  END IF;
  
  -- Update session tracking
  UPDATE queue
  SET session_staff_id = v_staff_id,
      updated_at = NOW()
  WHERE id = p_queue_id;
  
  RETURN jsonb_build_object(
    'success', true,
    'message', 'Session resumed successfully',
    'queue_id', p_queue_id,
    'patient', jsonb_build_object(
      'id', v_queue.patient_id,
      'patient_id', v_queue.emr_number,
      'first_name', v_queue.first_name,
      'last_name', v_queue.last_name,
      'gender', v_queue.gender,
      'date_of_birth', v_queue.date_of_birth
    ),
    'visit_id', v_queue.visit_id,
    'encounter_id', v_queue.encounter_id,
    'session_started_at', v_queue.called_at,
    'session_notes', v_queue.session_notes
  );
END;
$$;


--
-- Name: route_referral_to_encounter_office(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.route_referral_to_encounter_office() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
    -- Only process new Referral requests
    IF NEW.request_type = 'Referral' AND TG_OP = 'INSERT' THEN
        -- Set initial workflow status
        NEW.referral_workflow_status := 'Pending_Encounter_Office';
        
        -- Set status to Under_Review (awaiting Encounter Office action)
        NEW.status := 'Under_Review';
        
        -- Create notification for Encounter Office (optional, can be implemented)
        -- INSERT INTO notifications ...
    END IF;
    
    RETURN NEW;
END;
$$;


--
-- Name: route_to_specialty_queue(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.route_to_specialty_queue() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_dept_code VARCHAR(50);
    v_queue_location VARCHAR(50);
BEGIN
    -- Only process when status changes to Approved and it's a Referral
    IF NEW.status = 'Approved' AND NEW.request_type = 'Referral' AND OLD.status != 'Approved' THEN
        -- Get target department code
        SELECT code INTO v_dept_code 
        FROM departments 
        WHERE id = NEW.target_department_id;
        
        -- Map department to queue location
        CASE v_dept_code
            WHEN 'DEPT013' THEN v_queue_location := 'Dental';
            WHEN 'DEPT014' THEN v_queue_location := 'Ophthalmology';
            WHEN 'DEPT015' THEN v_queue_location := 'Physiotherapy';
            ELSE v_queue_location := NULL;
        END CASE;
        
        -- If it's a specialty referral, update the queue
        IF v_queue_location IS NOT NULL THEN
            -- Update the queue entry for this encounter
            UPDATE queue SET 
                location = v_queue_location::queue_location,
                status = 'Waiting',
                updated_at = NOW()
            WHERE visit_id = NEW.encounter_id
            AND status NOT IN ('Completed', 'Cancelled', 'No_Show');
            
            -- Also update specialty_module column
            NEW.specialty_module := LOWER(v_queue_location);
        END IF;
    END IF;
    
    RETURN NEW;
END;
$$;


--
-- Name: route_visit_to_specialty(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.route_visit_to_specialty() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_doctor_dept_code VARCHAR(50);
    v_queue_location VARCHAR(50);
BEGIN
    -- Get the attending doctor's department
    IF NEW.attending_doctor_id IS NOT NULL THEN
        SELECT d.code INTO v_doctor_dept_code
        FROM staff s
        LEFT JOIN departments d ON s.department_id = d.id
        WHERE s.id = NEW.attending_doctor_id;
        
        -- Map department to queue location
        CASE v_doctor_dept_code
            WHEN 'DEPT013' THEN v_queue_location := 'Dental';
            WHEN 'DEPT014' THEN v_queue_location := 'Ophthalmology';
            WHEN 'DEPT015' THEN v_queue_location := 'Physiotherapy';
            ELSE v_queue_location := NULL;
        END CASE;
        
        -- If specialty doctor, update the queue immediately
        IF v_queue_location IS NOT NULL THEN
            -- Update queue for this visit
            UPDATE queue SET 
                location = v_queue_location::queue_location,
                status = 'Waiting',
                updated_at = NOW()
            WHERE visit_id = NEW.id
            AND status NOT IN ('Completed', 'Cancelled', 'No_Show');
        END IF;
    END IF;
    
    RETURN NEW;
END;
$$;


--
-- Name: search_clinical_text_templates(text, uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_clinical_text_templates(p_module text, p_staff_id uuid, p_query text DEFAULT ''::text, p_category text DEFAULT NULL::text, p_limit integer DEFAULT 30) RETURNS TABLE(id uuid, template_key character varying, display_name character varying, description text, module character varying, category character varying, template_data jsonb, search_keywords text[], is_shared boolean, is_mine boolean, usage_count integer, my_usage_count integer, priority integer)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        t.id,
        t.template_key,
        t.display_name,
        t.description,
        t.module,
        t.category,
        t.template_data,
        t.search_keywords,
        t.is_shared,
        (t.created_by = p_staff_id)                 AS is_mine,
        t.usage_count,
        COALESCE(u.used_count, 0)                   AS my_usage_count,
        t.priority
    FROM public.clinical_text_templates t
    LEFT JOIN (
        SELECT template_id, COUNT(*)::INTEGER AS used_count
        FROM public.clinical_text_template_usage
        WHERE staff_id = p_staff_id
        GROUP BY template_id
    ) u ON u.template_id = t.id
    WHERE
        t.is_active = true
        AND t.module = p_module
        AND (
            t.is_shared = true                          -- shared → visible to all
            OR t.created_by = p_staff_id                -- personal → own only
        )
        AND (p_category IS NULL OR t.category = p_category OR t.category IS NULL)
        AND (
            p_query = ''
            OR t.tsv @@ plainto_tsquery('english', p_query)
            OR t.display_name ILIKE '%' || p_query || '%'
        )
    ORDER BY
        COALESCE(u.used_count, 0) DESC,   -- user's personal usage first
        t.usage_count DESC,               -- then global usage
        t.priority DESC,
        t.display_name
    LIMIT p_limit;
END;
$$;


--
-- Name: search_drug_catalogue(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_drug_catalogue(p_query text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, name text, generic_name text, drug_code text, form text, strength text, unit text, stock_quantity numeric, unit_price numeric, is_active boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pattern TEXT := '%' || trim(p_query) || '%';
BEGIN
  RETURN QUERY
  SELECT
    dc.id,
    dc.name,
    dc.generic_name,
    dc.drug_code,
    dc.form::TEXT,
    dc.strength,
    dc.unit,
    dc.stock_quantity,
    dc.unit_price,
    dc.is_active
  FROM drug_catalogue dc
  WHERE
    dc.name         ILIKE v_pattern OR
    dc.generic_name ILIKE v_pattern OR
    dc.drug_code    ILIKE v_pattern
  ORDER BY
    CASE WHEN dc.name ILIKE (trim(p_query) || '%') THEN 0 ELSE 1 END,
    dc.name
  LIMIT  p_limit
  OFFSET p_offset;
END;
$$;


--
-- Name: search_icd10_codes(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_icd10_codes(p_keyword text, p_max_results integer DEFAULT 25) RETURNS TABLE(code text, description text, match_score double precision)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_search_term TEXT;
    v_tsquery tsquery;
BEGIN
    -- Normalize search term
    v_search_term := TRIM(UPPER(p_keyword));
    
    IF v_search_term IS NULL OR LENGTH(v_search_term) < 2 THEN
        RETURN;
    END IF;
    
    -- Create tsquery for full-text search
    v_tsquery := plainto_tsquery('english', p_keyword);
    
    RETURN QUERY
    SELECT 
        i.code,
        i.description,
        CASE 
            -- Exact code match gets highest score
            WHEN UPPER(i.code) = v_search_term THEN 100.0
            -- Code prefix match gets high score
            WHEN UPPER(i.code) LIKE v_search_term || '%' THEN 80.0
            -- Code contains search term
            WHEN UPPER(i.code) LIKE '%' || v_search_term || '%' THEN 60.0
            -- Full-text match score
            WHEN v_tsquery @@ to_tsvector('english', i.description) THEN 
                ts_rank(to_tsvector('english', i.description), v_tsquery) * 50.0
            -- ILIKE match gets base score
            ELSE 10.0
        END AS match_score
    FROM public.icd10_codes i
    WHERE 
        -- Match by code (case-insensitive)
        UPPER(i.code) LIKE '%' || v_search_term || '%'
        OR
        -- Match by description (full-text or ILIKE)
        v_tsquery @@ to_tsvector('english', i.description)
        OR
        UPPER(i.description) LIKE '%' || v_search_term || '%'
    ORDER BY match_score DESC, i.code ASC
    LIMIT p_max_results;
END;
$$;


--
-- Name: search_nhis_profiles(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_nhis_profiles(p_query text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, patient_id uuid, nhis_number text, hmo_name text, enrollment_date date, expiry_date date, status text, first_name text, surname text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pattern TEXT := '%' || trim(p_query) || '%';
BEGIN
  RETURN QUERY
  SELECT
    np.id,
    np.patient_id,
    np.nhis_number,
    np.hmo_name,
    np.enrollment_date,
    np.expiry_date,
    np.status::TEXT,
    pt.first_name,
    pt.surname
  FROM nhis_profiles np
  JOIN patients pt ON pt.id = np.patient_id
  WHERE
    np.nhis_number ILIKE v_pattern OR
    np.hmo_name    ILIKE v_pattern OR
    pt.first_name  ILIKE v_pattern OR
    pt.surname     ILIKE v_pattern OR
    (pt.first_name || ' ' || pt.surname) ILIKE v_pattern
  ORDER BY pt.surname, pt.first_name
  LIMIT  p_limit
  OFFSET p_offset;
END;
$$;


--
-- Name: search_patient_records_fulltext(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_patient_records_fulltext(p_patient_id uuid, p_query text, p_limit integer DEFAULT 20) RETURNS TABLE(source_table text, source_id uuid, encounter_id uuid, record_date timestamp with time zone, snippet text, rank real)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
	v_tsq tsquery;
BEGIN
	PERFORM verify_patient_access(p_patient_id);

	v_tsq := websearch_to_tsquery('english', p_query);

	RETURN QUERY
	WITH ranked_chunks AS (
		SELECT
			pre.source_table::text AS source_table,
			pre.source_id,
			pre.encounter_id,
			pre.record_date,
			ts_headline(
				'english',
				coalesce(pre.chunk_text, ''),
				v_tsq,
				'MaxWords=60, MinWords=20'
			) AS snippet,
			ts_rank_cd(
				to_tsvector('english', coalesce(pre.chunk_text, '')),
				v_tsq
			)::real AS rank
		FROM public.patient_record_embeddings pre
		WHERE pre.patient_id = p_patient_id
			AND to_tsvector('english', coalesce(pre.chunk_text, '')) @@ v_tsq
	),
	grouped AS (
		SELECT
			r.source_table,
			r.source_id,
			(array_agg(r.encounter_id ORDER BY r.rank DESC NULLS LAST, r.record_date DESC NULLS LAST))[1] AS encounter_id,
			max(r.record_date) AS record_date,
			max(r.rank) AS rank,
			string_agg(r.snippet, ' ... ' ORDER BY r.rank DESC) AS snippet
		FROM ranked_chunks r
		GROUP BY r.source_table, r.source_id
	)
	SELECT
		g.source_table,
		g.source_id,
		g.encounter_id,
		g.record_date,
		g.snippet,
		g.rank
	FROM grouped g
	ORDER BY g.rank DESC, g.record_date DESC NULLS LAST
	LIMIT p_limit;
END;
$$;


--
-- Name: search_patient_records_hybrid(uuid, text, public.vector, integer, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_patient_records_hybrid(p_patient_id uuid, p_query text, p_query_embedding public.vector, p_limit integer DEFAULT 15, p_fulltext_weight double precision DEFAULT 0.4, p_vector_weight double precision DEFAULT 0.6) RETURNS TABLE(source_table text, source_id uuid, encounter_id uuid, record_date timestamp with time zone, content_snippet text, combined_score double precision)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
  PERFORM verify_patient_access(p_patient_id);

  RETURN QUERY
  WITH fulltext_hits AS (
    SELECT ft.source_table, ft.source_id, ft.encounter_id, ft.record_date,
           ft.snippet, ft."rank"::float AS ft_score
    FROM search_patient_records_fulltext(p_patient_id, p_query, 50) ft
  ),
  vector_hits AS (
    SELECT vs.source_table, vs.source_id, vs.encounter_id, vs.record_date,
           vs.chunk_text, vs.similarity AS vec_score
    FROM search_patient_records_vector(p_patient_id, p_query_embedding, 50, 0.5) vs
  ),
  combined AS (
    SELECT
      COALESCE(f.source_table, v.source_table) AS source_table,
      COALESCE(f.source_id, v.source_id) AS source_id,
      COALESCE(f.encounter_id, v.encounter_id) AS encounter_id,
      COALESCE(f.record_date, v.record_date) AS record_date,
      COALESCE(f.snippet, v.chunk_text) AS content_snippet,
      (COALESCE(f.ft_score, 0) * p_fulltext_weight + COALESCE(v.vec_score, 0) * p_vector_weight) AS combined_score
    FROM fulltext_hits f
    FULL OUTER JOIN vector_hits v
      ON f.source_table = v.source_table AND f.source_id = v.source_id
  )
  SELECT c.source_table, c.source_id, c.encounter_id, c.record_date,
         c.content_snippet, c.combined_score
  FROM combined c
  ORDER BY c.combined_score DESC
  LIMIT p_limit;
END;
$$;


--
-- Name: search_patient_records_vector(uuid, public.vector, integer, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_patient_records_vector(p_patient_id uuid, p_query_embedding public.vector, p_limit integer DEFAULT 20, p_similarity_threshold double precision DEFAULT 0.7) RETURNS TABLE(source_table text, source_id uuid, encounter_id uuid, record_date timestamp with time zone, chunk_text text, chunk_type text, similarity double precision)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
  PERFORM verify_patient_access(p_patient_id);

  RETURN QUERY
  SELECT
    pre.source_table::text,
    pre.source_id,
    pre.encounter_id,
    pre.record_date,
    pre.chunk_text,
    pre.chunk_type::text,
    (1 - (pre.embedding <=> p_query_embedding))::float AS similarity
  FROM patient_record_embeddings pre
  WHERE pre.patient_id = p_patient_id
    AND 1 - (pre.embedding <=> p_query_embedding) >= p_similarity_threshold
  ORDER BY pre.embedding <=> p_query_embedding
  LIMIT p_limit;
END;
$$;


--
-- Name: search_patients(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_patients(p_query text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, patient_id text, first_name text, surname text, date_of_birth date, gender text, contact_phone text, emr_number text, nhis_number text, patient_type text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pattern TEXT := '%' || trim(p_query) || '%';
BEGIN
  RETURN QUERY
  SELECT
    pt.id,
    pt.patient_id,
    pt.first_name,
    pt.surname,
    pt.date_of_birth,
    pt.gender::TEXT,
    pt.contact_phone,
    pt.emr_number,
    pt.nhis_number,
    pt.patient_type::TEXT
  FROM patients pt
  WHERE
    pt.first_name    ILIKE v_pattern OR
    pt.surname       ILIKE v_pattern OR
    (pt.first_name || ' ' || pt.surname) ILIKE v_pattern OR
    pt.emr_number    ILIKE v_pattern OR
    pt.contact_phone ILIKE v_pattern OR
    pt.nhis_number   ILIKE v_pattern
  ORDER BY
    -- Exact prefix matches first
    CASE WHEN pt.emr_number ILIKE (trim(p_query) || '%') THEN 0 ELSE 1 END,
    pt.surname, pt.first_name
  LIMIT  p_limit
  OFFSET p_offset;
END;
$$;


