-- Name: search_service_catalogue(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_service_catalogue(p_query text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, name text, code text, category text, unit_price numeric, nhis_tariff numeric, is_active boolean)
