--
-- Name: seed_staff_for_user(uuid, text, text, text, public.user_role, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seed_staff_for_user(p_user_id uuid, p_staff_id text, p_first_name text, p_last_name text, p_role public.user_role, p_department_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_email TEXT;
    v_new_staff_id UUID;
BEGIN
    -- Get email from auth.users
    SELECT email INTO v_email FROM auth.users WHERE id = p_user_id;
    
    IF v_email IS NULL THEN
        RAISE EXCEPTION 'User % not found in auth.users', p_user_id;
    END IF;
    
    -- Check if staff record already exists
    SELECT id INTO v_new_staff_id FROM staff WHERE user_id = p_user_id;
    IF v_new_staff_id IS NOT NULL THEN
        RAISE NOTICE 'Staff record already exists for user %', p_user_id;
        RETURN v_new_staff_id;
    END IF;
    
    -- Insert staff record
    INSERT INTO staff (
        staff_id,
        user_id,
        email,
        first_name,
        last_name,
        role,
        department_id,
        is_active
    ) VALUES (
        p_staff_id,
        p_user_id,
        v_email,
        p_first_name,
        p_last_name,
        p_role,
        p_department_id,
        true
    )
    RETURNING id INTO v_new_staff_id;
    
    RETURN v_new_staff_id;
END;
$$;


--
-- Name: set_clinical_request_sla(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_clinical_request_sla() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    sla_hours_val INTEGER;
BEGIN
    -- Set SLA based on urgency
    CASE NEW.urgency
        WHEN 'Emergency' THEN sla_hours_val := 1;
        WHEN 'Urgent' THEN sla_hours_val := 4;
        ELSE sla_hours_val := 24;
    END CASE;
    
    NEW.sla_hours := sla_hours_val;
    NEW.sla_deadline := NEW.created_at + (sla_hours_val || ' hours')::INTERVAL;
    
    RETURN NEW;
END;
$$;


--
-- Name: set_idempotency_timestamp(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_idempotency_timestamp() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
  -- Only set timestamp if idempotency_key is provided and timestamp is not already set
  IF NEW.idempotency_key IS NOT NULL AND NEW.idempotency_created_at IS NULL THEN
    NEW.idempotency_created_at := NOW();
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: set_message_thread_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_message_thread_id() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
    -- If this is a reply, inherit the thread_id from parent
    IF NEW.parent_message_id IS NOT NULL THEN
        SELECT COALESCE(thread_id, id) INTO NEW.thread_id
        FROM staff_messages WHERE id = NEW.parent_message_id;
    ELSE
        -- New thread, use the message's own ID
        NEW.thread_id = NEW.id;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: set_nhis_approval_status_on_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_nhis_approval_status_on_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $_$
DECLARE
  requires_auth boolean := false;
  patient_is_nhis boolean := false;
  catalogue_table text;
  catalogue_id_field text;
  service_id uuid;
BEGIN
  -- Determine the catalogue table and ID field based on request table
  IF TG_TABLE_NAME = 'lab_requests' THEN
    catalogue_table := 'lab_test_catalogue';
    catalogue_id_field := 'id';
    service_id := NEW.test_id;
  ELSIF TG_TABLE_NAME = 'radiology_requests' THEN
    catalogue_table := 'imaging_catalogue';
    catalogue_id_field := 'id';
    service_id := NEW.imaging_id;
  ELSIF TG_TABLE_NAME = 'prescriptions' THEN
    catalogue_table := 'drug_catalogue';
    catalogue_id_field := 'id';
    service_id := NEW.drug_id;
  ELSIF TG_TABLE_NAME = 'procedure_requests' THEN
    catalogue_table := 'procedure_catalogue';
    catalogue_id_field := 'id';
    service_id := NEW.procedure_id;
  ELSE
    RETURN NEW;
  END IF;
  
  -- Check if service requires NHIS authorization
  EXECUTE format(
    'SELECT COALESCE(requires_nhis_authorization, false) FROM %I WHERE %I = $1',
    catalogue_table, catalogue_id_field
  ) INTO requires_auth USING service_id;
  
  -- Check if patient is NHIS (has insurance_type containing 'nhis' or 'NHIS')
  -- Note: insurance_type is an ENUM, must cast to text for LIKE comparison
  IF NEW.patient_id IS NOT NULL THEN
    SELECT LOWER(COALESCE(insurance_type::text, '')) LIKE '%nhis%'
    INTO patient_is_nhis
    FROM patients
    WHERE patient_id = NEW.patient_id;
  END IF;
  
  -- Set nhis_approval_status based on requirements (cast to enum type)
  IF requires_auth AND COALESCE(patient_is_nhis, false) THEN
    NEW.nhis_approval_status := 'pending'::nhis_approval_status;
  ELSE
    NEW.nhis_approval_status := 'not_required'::nhis_approval_status;
  END IF;
  
  RETURN NEW;
END;
$_$;


--
-- Name: set_patient_allergy_metadata(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_patient_allergy_metadata() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_facility_id uuid;
BEGIN
  IF NEW.facility_id IS NULL THEN
    SELECT registered_facility_id INTO v_facility_id
    FROM public.patients
    WHERE id = NEW.patient_id;

    IF v_facility_id IS NULL THEN
      v_facility_id := public.get_user_facility_id();
    END IF;

    IF v_facility_id IS NULL THEN
      SELECT id INTO v_facility_id
      FROM public.facilities
      WHERE is_active = true
      ORDER BY created_at NULLS LAST, id
      LIMIT 1;
    END IF;

    NEW.facility_id := v_facility_id;
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


--
-- Name: set_queue_specialty_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_queue_specialty_code() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
  -- If specialty_code not provided, derive from assigned_to staff
  IF NEW.specialty_code IS NULL AND NEW.assigned_to IS NOT NULL THEN
    SELECT specialty_code INTO NEW.specialty_code
    FROM staff 
    WHERE id = NEW.assigned_to AND specialty_code IS NOT NULL;
  END IF;
  
  -- Fallback: derive from encounter's attending_doctor_id
  IF NEW.specialty_code IS NULL AND NEW.encounter_id IS NOT NULL THEN
    SELECT s.specialty_code INTO NEW.specialty_code
    FROM visits v
    JOIN staff s ON s.id = v.attending_doctor_id
    WHERE v.id = NEW.encounter_id 
      AND s.specialty_code IS NOT NULL;
  END IF;
  
  -- Fallback: derive from location if it's a dedicated specialty queue
  IF NEW.specialty_code IS NULL AND NEW.location IS NOT NULL THEN
    SELECT sd.specialty_code INTO NEW.specialty_code
    FROM specialty_departments sd
    WHERE sd.queue_department = NEW.location::TEXT
      AND sd.requires_dedicated_queue = true
      AND sd.is_active = true
    LIMIT 1;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: set_session_user_role(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_session_user_role() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT;
BEGIN
  -- Fetch from staff table
  SELECT role::TEXT INTO v_role
  FROM staff
  WHERE user_id = auth.uid()
    AND is_active = TRUE
  LIMIT 1;

  IF v_role IS NULL THEN
    v_role := 'anonymous';
  END IF;

  -- Set for this transaction/connection
  PERFORM set_config('app.user_role', v_role, false);  -- false = not transaction-local

  RETURN v_role;
END;
$$;


--
-- Name: set_specialty_nhis_approval_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_specialty_nhis_approval_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
  v_is_nhis boolean;
BEGIN
  -- Check if encounter is NHIS
  IF NEW.encounter_id IS NOT NULL THEN
    v_is_nhis := public.is_encounter_nhis(NEW.encounter_id);
    
    -- If NHIS patient, set status to pending
    IF v_is_nhis THEN
      NEW.nhis_approval_status := 'pending';
    ELSE
      NEW.nhis_approval_status := 'not_required';
    END IF;
  ELSE
    NEW.nhis_approval_status := 'not_required';
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: start_specialty_session(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_specialty_session(p_queue_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
  v_staff_id uuid;
  v_staff_role text;
  v_specialty_code varchar(50);
  v_is_admin boolean;
BEGIN
  SELECT id, role::text, specialty_code INTO v_staff_id, v_staff_role, v_specialty_code
  FROM staff WHERE user_id = auth.uid();
  
  IF v_staff_id IS NULL THEN
    RAISE EXCEPTION 'Staff not found for current user';
  END IF;
  
  -- Admins can start any session
  v_is_admin := v_staff_role IN ('super_admin', 'admin', 'medical_director', 'Admin', 'System_Admin', 'Medical_Director');
  
  UPDATE queue SET
    status = 'In Progress',
    called_at = COALESCE(called_at, now()),  -- Don't overwrite if resuming
    assigned_to = v_staff_id,
    session_started_at = COALESCE(session_started_at, now()),  -- Track original start
    session_staff_id = v_staff_id,
    updated_at = now()
  WHERE id = p_queue_id
    AND (
      v_is_admin  -- Admins can start any session
      OR specialty_code = v_specialty_code  -- Doctors can start their specialty
      OR specialty_code IS NULL  -- Anyone can start unassigned queue entries
    )
    AND status IN ('Waiting', 'Called', 'In Progress')  -- Allow re-starting In Progress
  RETURNING jsonb_build_object(
    'queue_id', id,
    'status', status,
    'patient_id', patient_id,
    'started_at', called_at,
    'assigned_to', assigned_to,
    'visit_id', visit_id,
    'encounter_id', encounter_id
  ) INTO v_result;
  
  IF v_result IS NULL THEN
    RAISE EXCEPTION 'Queue entry not found or access denied';
  END IF;
  
  RETURN v_result;
END;
$$;


--
-- Name: sync_arm_of_service(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_arm_of_service() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
    -- If arm_of_service is set but military_branch is not, sync it
    IF NEW.arm_of_service IS NOT NULL AND NEW.military_branch IS NULL THEN
        NEW.military_branch := NEW.arm_of_service::military_branch_enum;
    END IF;
    
    -- If military_branch is set but arm_of_service is not, sync it
    IF NEW.military_branch IS NOT NULL AND NEW.arm_of_service IS NULL THEN
        NEW.arm_of_service := NEW.military_branch::TEXT;
    END IF;
    
    RETURN NEW;
EXCEPTION
    WHEN invalid_text_representation THEN
        -- If the value can't be cast to the enum, just keep the text value
        RETURN NEW;
END;
$$;


--
-- Name: sync_clinical_request_nhis_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_clinical_request_nhis_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
    -- Only process specialty referral type services
    IF NEW.service_type LIKE '%_referral' AND NEW.service_request_id IS NOT NULL THEN
        -- Update the clinical_request nhis_approval_status
        UPDATE clinical_requests
        SET 
            nhis_approval_status = NEW.status,
            updated_at = NOW()
        WHERE id::text = NEW.service_request_id;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: sync_drug_stock_quantity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_drug_stock_quantity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
    -- Update the drug_catalogue stock_quantity to match sum of active batches
    UPDATE drug_catalogue
    SET stock_quantity = (
        SELECT COALESCE(SUM(quantity_remaining), 0)
        FROM drug_batches
        WHERE drug_id = COALESCE(NEW.drug_id, OLD.drug_id)
          AND status = 'active'
          AND expiry_date > CURRENT_DATE
    ),
    updated_at = NOW()
    WHERE id = COALESCE(NEW.drug_id, OLD.drug_id);
    
    RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: sync_hygiene_to_nursing_interventions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_hygiene_to_nursing_interventions() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
    IF NEW.status = 'Completed' THEN
        INSERT INTO nursing_interventions (
            encounter_id, patient_id, ward_id, bed_id,
            category_code, intervention_code, notes,
            performed_at, shift, nurse_id
        )
        VALUES (
            NEW.encounter_id, NEW.patient_id, NEW.ward_id, NEW.bed_id,
            NEW.activity_category::text, NEW.activity_code, NEW.notes,
            NEW.performed_time, NEW.shift, NEW.performed_by
        )
        ON CONFLICT DO NOTHING;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: sync_lab_critical_notifications(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_lab_critical_notifications() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_patient_external_id text;
  v_notified_to uuid;
BEGIN
  IF NOT COALESCE(NEW.is_critical, false) OR NEW.critical_notified_at IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT lr.patient_id, lr.ordered_by
  INTO v_patient_external_id, v_notified_to
  FROM public.lab_requests lr
  WHERE lr.request_id = NEW.request_id;

  INSERT INTO public.lab_critical_notifications (
    lab_result_id,
    patient_id,
    critical_value,
    critical_type,
    notified_to,
    notification_method,
    notification_status,
    notified_at,
    notes
  )
  VALUES (
    NEW.id,
    v_patient_external_id,
    NEW.result_value,
    CASE WHEN NEW.is_abnormal THEN 'Critical Result' ELSE 'Critical Value' END,
    v_notified_to,
    'system',
    'Pending',
    NEW.critical_notified_at,
    COALESCE(NEW.comments, NEW.interpretation)
  )
  ON CONFLICT (lab_result_id)
  DO UPDATE SET
    patient_id = EXCLUDED.patient_id,
    critical_value = EXCLUDED.critical_value,
    critical_type = EXCLUDED.critical_type,
    notified_to = EXCLUDED.notified_to,
    notification_method = EXCLUDED.notification_method,
    notified_at = EXCLUDED.notified_at,
    notes = EXCLUDED.notes;

  RETURN NEW;
END;
$$;


--
-- Name: sync_lab_request_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_lab_request_status() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- When a lab result is inserted or updated, sync key info to lab_requests
    UPDATE lab_requests
    SET 
        status = CASE 
            WHEN NEW.workflow_status = 'released' THEN 'Completed'::request_status
            WHEN NEW.workflow_status IN ('verified', 'approved') THEN 'Result_Ready'::request_status
            ELSE status
        END,
        result_entered_at = COALESCE(result_entered_at, NEW.created_at),
        result_entered_by = COALESCE(result_entered_by, NEW.technician_id),
        is_critical = COALESCE(NEW.is_critical, is_critical),
        updated_at = NOW()
    WHERE request_id = NEW.request_id;
    
    RETURN NEW;
END;
$$;


--
-- Name: sync_nhis_claim_billing_refs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_nhis_claim_billing_refs() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
  -- Sync invoice number if invoice_id is set but invoice_number is not
  IF NEW.invoice_id IS NOT NULL AND (NEW.invoice_number IS NULL OR NEW.invoice_number = '') THEN
    SELECT invoice_number INTO NEW.invoice_number
    FROM invoices WHERE invoice_id = NEW.invoice_id;
  END IF;

  -- Sync receipt number if receipt_id is set but receipt_number is not
  IF NEW.receipt_id IS NOT NULL AND (NEW.receipt_number IS NULL OR NEW.receipt_number = '') THEN
    SELECT receipt_number INTO NEW.receipt_number
    FROM receipts WHERE receipt_id = NEW.receipt_id;
  END IF;

  -- CRITICAL: Validate that invoice belongs to the same encounter as the claim
  IF NEW.invoice_id IS NOT NULL AND NEW.encounter_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM invoices 
      WHERE invoice_id = NEW.invoice_id 
        AND encounter_id = NEW.encounter_id
    ) THEN
      RAISE EXCEPTION 'Invoice % does not belong to encounter %. Claims must be linked to invoices from the same encounter.', 
        NEW.invoice_id, NEW.encounter_id;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: sync_patient_allergy_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_patient_allergy_summary() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_patient_id uuid;
BEGIN
  v_patient_id := COALESCE(NEW.patient_id, OLD.patient_id);

  UPDATE public.patients
  SET
    known_allergies = COALESCE((
      SELECT array_agg(allergen ORDER BY allergen)
      FROM public.patient_allergies
      WHERE patient_id = v_patient_id AND is_active = true
    ), ARRAY[]::text[]),
    allergies_reviewed_at = now(),
    updated_at = now()
  WHERE id = v_patient_id;

  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: sync_physio_plan_payment_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_physio_plan_payment_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
    -- Only fire when status changes to a paid state
    IF NEW.status IN ('Paid', 'Paid_NHIS', 'Paid_Retainership') AND
       (OLD.status IS NULL OR OLD.status NOT IN ('Paid', 'Paid_NHIS', 'Paid_Retainership')) AND
       NEW.source_module = 'physiotherapy' THEN

        -- Update physio_plans linked via billing_items.service_reference_id or item_id
        UPDATE physio_plans
        SET payment_status = 'paid',
            updated_at = now()
        WHERE plan_id IN (
            SELECT bi.service_reference_id
            FROM billing_items bi
            WHERE bi.billing_order_id = NEW.id
              AND bi.service_reference_id IS NOT NULL
              AND EXISTS (SELECT 1 FROM physio_plans pp WHERE pp.plan_id = bi.service_reference_id)
            UNION
            SELECT bi.item_id
            FROM billing_items bi
            WHERE bi.billing_order_id = NEW.id
              AND bi.item_id IS NOT NULL
              AND EXISTS (SELECT 1 FROM physio_plans pp WHERE pp.plan_id = bi.item_id)
        )
          AND payment_status != 'paid';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: sync_radiology_staff_identifiers(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_radiology_staff_identifiers() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
  v_staff_id_text varchar(50);
  v_staff_uuid uuid;
BEGIN
  -- ordered_by/text -> ordered_by_uuid
  IF NEW.ordered_by_uuid IS NULL AND NEW.ordered_by IS NOT NULL THEN
    SELECT s.id INTO v_staff_uuid
    FROM public.staff s
    WHERE s.staff_id = NEW.ordered_by
    LIMIT 1;
    NEW.ordered_by_uuid := v_staff_uuid;
  END IF;

  -- ordered_by_uuid -> ordered_by/text
  IF NEW.ordered_by IS NULL AND NEW.ordered_by_uuid IS NOT NULL THEN
    SELECT s.staff_id INTO v_staff_id_text
    FROM public.staff s
    WHERE s.id = NEW.ordered_by_uuid
    LIMIT 1;
    NEW.ordered_by := v_staff_id_text;
  END IF;

  -- performed_by/text -> performed_by_uuid
  IF NEW.performed_by_uuid IS NULL AND NEW.performed_by IS NOT NULL THEN
    SELECT s.id INTO v_staff_uuid
    FROM public.staff s
    WHERE s.staff_id = NEW.performed_by
    LIMIT 1;
    NEW.performed_by_uuid := v_staff_uuid;
  END IF;

  -- performed_by_uuid -> performed_by/text
  IF NEW.performed_by IS NULL AND NEW.performed_by_uuid IS NOT NULL THEN
    SELECT s.staff_id INTO v_staff_id_text
    FROM public.staff s
    WHERE s.id = NEW.performed_by_uuid
    LIMIT 1;
    NEW.performed_by := v_staff_id_text;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: sync_shift_handover_dates(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_shift_handover_dates() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
  -- If shift_date is null but handover_date is set, copy it
  IF NEW.shift_date IS NULL AND NEW.handover_date IS NOT NULL THEN
    NEW.shift_date := NEW.handover_date;
  END IF;
  -- If handover_date is null but shift_date is set, copy it
  IF NEW.handover_date IS NULL AND NEW.shift_date IS NOT NULL THEN
    NEW.handover_date := NEW.shift_date;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: sync_staff_auth_user_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_staff_auth_user_id() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
  -- Keep legacy and canonical auth columns synchronized.
  IF NEW.user_id IS NOT NULL THEN
    NEW.auth_user_id := NEW.user_id;
  ELSIF NEW.auth_user_id IS NOT NULL THEN
    NEW.user_id := NEW.auth_user_id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: track_clinical_request_status_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.track_clinical_request_status_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
    IF OLD.status IS DISTINCT FROM NEW.status THEN
        INSERT INTO clinical_request_status_history (
            request_id,
            from_status,
            to_status,
            changed_by,
            change_reason
        ) VALUES (
            NEW.id,
            OLD.status,
            NEW.status,
            NEW.reviewed_by,
            NEW.review_notes
        );
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: track_lab_result_changes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.track_lab_result_changes() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
BEGIN
    -- Only track if there's an actual change to result data
    IF TG_OP = 'UPDATE' AND (
        OLD.result_value IS DISTINCT FROM NEW.result_value OR
        OLD.structured_result IS DISTINCT FROM NEW.structured_result OR
        OLD.workflow_status IS DISTINCT FROM NEW.workflow_status
    ) THEN
        INSERT INTO lab_result_history (
            lab_result_id,
            version,
            result,
            result_value,
            structured_result,
            result_status,
            modified_by,
            modification_type,
            modification_reason
        ) VALUES (
            NEW.id,
            NEW.version,
            NEW.result_value,
            CASE WHEN NEW.result_value ~ '^[0-9.]+$' THEN NEW.result_value::numeric ELSE NULL END,
            NEW.structured_result,
            NEW.workflow_status,
            NEW.last_modified_by,
            CASE 
                WHEN OLD.workflow_status != NEW.workflow_status THEN 'Status Change'
                WHEN OLD.result_value IS DISTINCT FROM NEW.result_value THEN 'Result Amendment'
                WHEN OLD.structured_result IS DISTINCT FROM NEW.structured_result THEN 'Data Update'
                ELSE 'Modification'
            END,
            'Automatic tracking on update'
        );
    END IF;
    
    RETURN NEW;
END;
$_$;


--
-- Name: transfer_queue_ticket(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transfer_queue_ticket(p_current_queue_id uuid, p_new_dept text, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_current_queue RECORD;
    v_new_ticket integer;
    v_new_queue_id uuid;
    v_today_lagos date;
    v_result jsonb;
    v_location queue_location;
BEGIN
    -- Get today's date in Africa/Lagos timezone
    v_today_lagos := (now() AT TIME ZONE 'Africa/Lagos')::date;
    
    -- Cast text department to queue_location enum
    BEGIN
        v_location := p_new_dept::queue_location;
    EXCEPTION WHEN invalid_text_representation THEN
        -- Default to 'Nursing' if invalid location provided
        v_location := 'Nursing'::queue_location;
    END;
    
    -- Get current queue entry
    SELECT * INTO v_current_queue 
    FROM public.queue 
    WHERE id = p_current_queue_id;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Queue entry not found'
        );
    END IF;
    
    -- Acquire lock for new department
    PERFORM pg_advisory_xact_lock(hashtext('queue_counter_' || p_new_dept || '_' || v_today_lagos::text));
    
    -- Complete current queue entry
    UPDATE public.queue
    SET status = 'Completed',
        completed_at = now()
    WHERE id = p_current_queue_id;
    
    -- Get next ticket number for new department
    INSERT INTO public.queue_daily_counters (department, counter_date, last_ticket_number)
    VALUES (p_new_dept, v_today_lagos, 1)
    ON CONFLICT (department, counter_date)
    DO UPDATE SET 
        last_ticket_number = queue_daily_counters.last_ticket_number + 1,
        updated_at = now()
    RETURNING last_ticket_number INTO v_new_ticket;
    
    -- Generate new queue ID
    v_new_queue_id := extensions.uuid_generate_v4();
    
    -- Create new queue entry
    INSERT INTO public.queue (
        id,
        patient_id,
        visit_id,
        encounter_id,
        clinic_id,
        location,
        ticket_number,
        priority,
        status,
        notes,
        created_at
    ) VALUES (
        v_new_queue_id,
        v_current_queue.patient_id,
        v_current_queue.visit_id,
        v_current_queue.encounter_id,
        v_current_queue.clinic_id,
        v_location,  -- Use the casted enum value
        v_new_ticket::text,
        v_current_queue.priority,
        'Waiting',
        COALESCE(p_notes, 'Transferred from ' || v_current_queue.location),
        now()
    );
    
    -- Build result
    v_result := jsonb_build_object(
        'success', true,
        'previous_queue_id', p_current_queue_id,
        'previous_department', v_current_queue.location,
        'new_queue_id', v_new_queue_id,
        'new_ticket_number', v_new_ticket,
        'new_department', p_new_dept,
        'patient_id', v_current_queue.patient_id,
        'encounter_id', v_current_queue.encounter_id
    );
    
    RETURN v_result;
    
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', SQLERRM,
        'error_detail', SQLSTATE
    );
END;
$$;


