--
-- Name: update_theatre_room_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_theatre_room_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
    -- Surgery starting - mark room as In_Use
    IF NEW.status = 'In_Theatre' AND (OLD.status IS NULL OR OLD.status != 'In_Theatre') THEN
        UPDATE theatre_rooms 
        SET current_status = 'In_Use', 
            current_surgery_id = NEW.id, 
            updated_at = NOW()
        WHERE id = NEW.theatre_room_id;
    END IF;
    
    -- Surgery ending - mark room for cleaning
    IF NEW.status IN ('Completed', 'Recovery', 'Cancelled') 
       AND OLD.status = 'In_Theatre' THEN
        UPDATE theatre_rooms 
        SET current_status = 'Cleaning', 
            current_surgery_id = NULL, 
            updated_at = NOW()
        WHERE id = OLD.theatre_room_id;
    END IF;
    
    RETURN NEW;
END;
$$;


--
-- Name: update_treatment_plan_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_treatment_plan_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    total_tasks INTEGER;
    completed_tasks INTEGER;
    in_progress_tasks INTEGER;
BEGIN
    -- Count task statuses
    SELECT 
        COUNT(*),
        COUNT(*) FILTER (WHERE status = 'Completed'),
        COUNT(*) FILTER (WHERE status = 'In_Progress')
    INTO total_tasks, completed_tasks, in_progress_tasks
    FROM treatment_plan_tasks
    WHERE plan_id = COALESCE(NEW.plan_id, OLD.plan_id);
    
    -- Update plan status
    IF completed_tasks = total_tasks AND total_tasks > 0 THEN
        UPDATE treatment_plans 
        SET status = 'Completed', 
            completed_at = NOW(),
            updated_at = NOW()
        WHERE plan_id = COALESCE(NEW.plan_id, OLD.plan_id)
        AND status != 'Completed';
    ELSIF in_progress_tasks > 0 OR completed_tasks > 0 THEN
        UPDATE treatment_plans 
        SET status = 'In_Progress',
            updated_at = NOW()
        WHERE plan_id = COALESCE(NEW.plan_id, OLD.plan_id)
        AND status NOT IN ('In_Progress', 'Completed', 'Cancelled');
    END IF;
    
    RETURN COALESCE(NEW, OLD);
END;
$$;


