--
-- Name: upsert_followup_booking(uuid, uuid, uuid, uuid, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_followup_booking(p_encounter_id uuid, p_patient_id uuid, p_requesting_doctor_id uuid, p_source_clinic_id uuid DEFAULT NULL::uuid, p_follow_up_date date DEFAULT NULL::date, p_follow_up_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
  v_existing_id uuid;
  v_result_id   uuid;
BEGIN

  -- -----------------------------------------------------------------------
  -- 1. Look for an existing active Follow-Up booking for this encounter
  -- -----------------------------------------------------------------------
  SELECT id INTO v_existing_id
  FROM   public.clinical_requests
  WHERE  encounter_id  = p_encounter_id
    AND  request_type  = 'Follow-Up'::public.clinical_request_type
    AND  status       != 'Cancelled'::public.clinical_request_status
  ORDER  BY created_at DESC
  LIMIT  1;

  -- -----------------------------------------------------------------------
  -- 2a. Doctor cleared the date → cancel any existing booking
  -- -----------------------------------------------------------------------
  IF p_follow_up_date IS NULL THEN
    IF v_existing_id IS NOT NULL THEN
      UPDATE public.clinical_requests
      SET    status                   = 'Cancelled'::public.clinical_request_status,
             referral_workflow_status = 'Cancelled',
             updated_at              = now()
      WHERE  id = v_existing_id;
    END IF;
    RETURN v_existing_id;  -- NULL if no booking existed

  -- -----------------------------------------------------------------------
  -- 2b. Date set and existing booking found → UPDATE in place (no duplicate)
  -- -----------------------------------------------------------------------
  ELSIF v_existing_id IS NOT NULL THEN
    UPDATE public.clinical_requests
    SET    scheduled_date            = p_follow_up_date,
           appointment_date          = p_follow_up_date,
           follow_up_reason          = p_follow_up_notes,
           follow_up_instructions    = p_follow_up_notes,
           notes                     = p_follow_up_notes,
           clinical_reason           = COALESCE(p_follow_up_notes, 'Follow-up visit'),
           source_clinic_id          = COALESCE(p_source_clinic_id, source_clinic_id),
           -- If it was somehow cancelled before, reactivate it
           status                    = CASE
                                         WHEN status = 'Cancelled'::public.clinical_request_status
                                         THEN 'Pending'::public.clinical_request_status
                                         ELSE status
                                       END,
           referral_workflow_status  = CASE
                                         WHEN referral_workflow_status = 'Cancelled'
                                         THEN 'Pending_Encounter_Office'
                                         ELSE referral_workflow_status
                                       END,
           updated_at                = now()
    WHERE  id = v_existing_id
    RETURNING id INTO v_result_id;

    RETURN v_result_id;

  -- -----------------------------------------------------------------------
  -- 2c. Date set, no existing booking → INSERT new Follow-Up record
  -- -----------------------------------------------------------------------
  ELSE
    INSERT INTO public.clinical_requests (
      patient_id,
      encounter_id,
      requesting_doctor_id,
      source_clinic_id,
      request_type,
      clinical_reason,
      follow_up_reason,
      follow_up_instructions,
      notes,
      scheduled_date,
      appointment_date,
      urgency,
      status,
      referral_workflow_status,
      created_by,
      created_at,
      updated_at
    ) VALUES (
      p_patient_id,
      p_encounter_id,
      p_requesting_doctor_id,
      p_source_clinic_id,
      'Follow-Up'::public.clinical_request_type,
      COALESCE(NULLIF(TRIM(p_follow_up_notes), ''), 'Follow-up visit'),
      p_follow_up_notes,
      p_follow_up_notes,
      p_follow_up_notes,
      p_follow_up_date,
      p_follow_up_date,
      'Routine'::public.clinical_urgency,
      'Pending'::public.clinical_request_status,
      'Pending_Encounter_Office',
      p_requesting_doctor_id,
      now(),
      now()
    )
    RETURNING id INTO v_result_id;

    RETURN v_result_id;
  END IF;

END;
$$;


--
-- Name: validate_billing_item(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_billing_item() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_insurance_type VARCHAR;
    v_service_type VARCHAR;
    v_calc RECORD;
BEGIN
    -- ── Existing audit field defaults ──
    IF NEW.service_name IS NULL OR NEW.service_name = '' THEN
        IF NEW.item_name IS NOT NULL AND NEW.item_name != '' THEN
            NEW.service_name := NEW.item_name;
        ELSE
            RAISE EXCEPTION 'service_name or item_name is required for billing items';
        END IF;
    END IF;

    IF NEW.unit_cost IS NULL THEN
        IF NEW.unit_price IS NOT NULL THEN
            NEW.unit_cost := NEW.unit_price;
        ELSE
            RAISE EXCEPTION 'unit_cost or unit_price is required for billing items';
        END IF;
    END IF;

    IF NEW.quantity IS NULL OR NEW.quantity < 1 THEN
        NEW.quantity := 1;
    END IF;

    IF NEW.gross_amount IS NULL THEN
        NEW.gross_amount := NEW.quantity * NEW.unit_cost;
    END IF;

    -- Sync legacy fields
    IF NEW.item_name IS NULL THEN
        NEW.item_name := NEW.service_name;
    END IF;
    IF NEW.unit_price IS NULL THEN
        NEW.unit_price := NEW.unit_cost;
    END IF;
    IF NEW.total_price IS NULL THEN
        NEW.total_price := NEW.gross_amount;
    END IF;

    -- ── NEW: Auto-calculate NHIS fields from the parent billing_order's encounter ──
    IF NEW.billing_order_id IS NOT NULL THEN
        -- Look up insurance type via billing_order → visit
        SELECT v.insurance_type::TEXT INTO v_insurance_type
        FROM billing_orders bo
        JOIN visits v ON v.id = bo.encounter_id
        WHERE bo.id = NEW.billing_order_id;

        IF v_insurance_type IS NOT NULL AND v_insurance_type != '' THEN
            -- Determine service type from item_type
            v_service_type := COALESCE(NEW.item_type::TEXT, 'Other');

            -- Calculate NHIS amounts, passing any service-level override
            -- (nhis_percentage > 0 from the catalogue means use that override)
            SELECT * INTO v_calc
            FROM calculate_nhis_amounts(
                NEW.gross_amount,
                v_insurance_type,
                v_service_type,
                CASE WHEN NEW.nhis_percentage > 0 THEN NEW.nhis_percentage ELSE NULL END
            );

            NEW.nhis_covered := v_calc.nhis_covered;
            NEW.nhis_percentage := v_calc.nhis_percentage;
            NEW.nhis_payable := v_calc.nhis_payable;
            NEW.patient_payable := v_calc.patient_payable;

            RETURN NEW;
        END IF;
    END IF;

    -- Fallback: ensure NHIS fields have defaults (no visit lookup possible)
    IF NEW.nhis_covered IS NULL THEN
        NEW.nhis_covered := FALSE;
    END IF;
    IF NEW.nhis_percentage IS NULL THEN
        NEW.nhis_percentage := 0;
    END IF;
    IF NEW.nhis_payable IS NULL THEN
        NEW.nhis_payable := 0;
    END IF;
    IF NEW.patient_payable IS NULL THEN
        NEW.patient_payable := COALESCE(NEW.gross_amount, NEW.quantity * NEW.unit_cost);
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: validate_encounter_active(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_encounter_active(p_encounter_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_status TEXT;
BEGIN
    SELECT status::TEXT INTO v_status
    FROM visits
    WHERE id = p_encounter_id;
    
    IF v_status IS NULL THEN
        RETURN FALSE;
    END IF;
    
    IF v_status IN ('Completed', 'Closed', 'Cancelled') THEN
        RETURN FALSE;
    END IF;
    
    RETURN TRUE;
END;
$$;


