--
-- Name: validate_specialty_data(character varying, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_specialty_data(p_specialty_code character varying, p_specialty_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_errors JSONB := '[]'::jsonb;
    v_field RECORD;
    v_field_value JSONB;
    v_is_valid BOOLEAN := true;
BEGIN
    -- Check each required field
    FOR v_field IN 
        SELECT f.field_code, f.field_label, f.is_required, f.field_type, f.validation_rules
        FROM public.specialty_template_fields f
        JOIN public.specialty_template_sections s ON s.id = f.section_id
        JOIN public.specialty_templates t ON t.id = s.template_id
        WHERE t.specialty_code = p_specialty_code
        AND t.is_active = true
        AND f.is_required = true
    LOOP
        v_field_value := p_specialty_data -> v_field.field_code;
        
        -- Check if required field is missing or empty
        IF v_field_value IS NULL OR v_field_value = 'null'::jsonb OR 
           (jsonb_typeof(v_field_value) = 'string' AND v_field_value #>> '{}' = '') THEN
            v_errors := v_errors || jsonb_build_object(
                'field', v_field.field_code,
                'message', v_field.field_label || ' is required'
            );
            v_is_valid := false;
        END IF;
    END LOOP;
    
    RETURN jsonb_build_object(
        'is_valid', v_is_valid,
        'errors', v_errors
    );
END;
$$;


--
-- Name: verify_encounter_action(uuid, uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_encounter_action(p_encounter_id uuid, p_user_id uuid, p_action character varying) RETURNS TABLE(can_perform boolean, reason text, encounter_role character varying)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_access_info RECORD;
    v_role_actions TEXT[];
BEGIN
    -- Get user's access role for this encounter
    SELECT * INTO v_access_info
    FROM check_encounter_access(
        p_encounter_id,
        p_user_id,
        (SELECT role FROM staff WHERE id = p_user_id),
        (SELECT department FROM staff WHERE id = p_user_id)
    );
    
    IF NOT v_access_info.has_access THEN
        RETURN QUERY SELECT false, 'No access to this encounter', 'no_access'::VARCHAR;
        RETURN;
    END IF;
    
    -- Define action permissions per role
    v_role_actions := CASE v_access_info.access_role
        WHEN 'primary_doctor' THEN ARRAY['view','edit','prescribe','order_lab','order_radiology','order_procedure','close','transfer','add_team']
        WHEN 'co_managing_doctor' THEN ARRAY['view','edit','prescribe','order_lab','order_radiology','order_procedure','add_team']
        WHEN 'consulting_doctor' THEN ARRAY['view','edit','prescribe','order_lab','order_radiology']
        WHEN 'on_call_doctor' THEN ARRAY['view','edit','prescribe','order_lab','order_radiology','order_procedure']
        WHEN 'department_doctor' THEN ARRAY['view']
        WHEN 'nurse' THEN ARRAY['view','add_vitals','add_nursing_notes']
        WHEN 'lab_technician' THEN ARRAY['view','process_lab']
        WHEN 'radiologist' THEN ARRAY['view','process_radiology']
        WHEN 'pharmacist' THEN ARRAY['view','dispense']
        ELSE ARRAY[]::TEXT[]
    END;
    
    IF p_action = ANY(v_role_actions) THEN
        RETURN QUERY SELECT true, 'Action authorized for role: ' || v_access_info.access_role, v_access_info.access_role;
    ELSE
        RETURN QUERY SELECT false, 'Action not permitted for role: ' || v_access_info.access_role, v_access_info.access_role;
    END IF;
END;
$$;


--
-- Name: verify_nhis_encounter(uuid, uuid, uuid, public.nhis_tariff_group); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_nhis_encounter(p_encounter_id uuid, p_auth_id uuid, p_verified_by uuid, p_tariff_group public.nhis_tariff_group DEFAULT 'Civilian_HMO'::public.nhis_tariff_group) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
    v_auth RECORD;
    v_encounter RECORD;
    v_policy RECORD;
    v_result JSONB;
BEGIN
    -- Get authorization
    SELECT * INTO v_auth FROM nhis_authorizations WHERE id = p_auth_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', FALSE, 'error', 'Authorization not found');
    END IF;
    
    -- Check authorization status
    IF v_auth.status != 'active' THEN
        RETURN jsonb_build_object('success', FALSE, 'error', 'Authorization is not active');
    END IF;
    
    -- Check expiry
    IF v_auth.expiry_date < NOW() THEN
        UPDATE nhis_authorizations SET status = 'expired' WHERE id = p_auth_id;
        RETURN jsonb_build_object('success', FALSE, 'error', 'Authorization has expired');
    END IF;
    
    -- Get encounter
    SELECT * INTO v_encounter FROM visits WHERE id = p_encounter_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', FALSE, 'error', 'Encounter not found');
    END IF;
    
    -- Get policy config
    SELECT * INTO v_policy FROM nhis_policy_config WHERE is_active = TRUE LIMIT 1;
    
    -- Update encounter
    UPDATE visits SET
        payer_type = 'nhis',
        nhis_auth_id = p_auth_id,
        nhis_verification_status = 'verified',
        nhis_verified_by = p_verified_by,
        nhis_verified_at = NOW(),
        nhis_tariff_group = p_tariff_group,
        nhis_policy_snapshot = jsonb_build_object(
            'auth_code', v_auth.auth_code,
            'auth_expiry', v_auth.expiry_date,
            'tariff_group', p_tariff_group,
            'verified_at', NOW()
        ),
        updated_at = NOW()
    WHERE id = p_encounter_id;
    
    -- Log audit
    INSERT INTO nhis_audit_log (
        action_type, action_description, entity_type, entity_id,
        patient_id, encounter_id, new_state, performed_by
    ) VALUES (
        'ENCOUNTER_VERIFIED', 'NHIS encounter verified', 'encounter', p_encounter_id,
        v_encounter.patient_id, p_encounter_id,
        jsonb_build_object('auth_id', p_auth_id, 'tariff_group', p_tariff_group),
        p_verified_by
    );
    
    RETURN jsonb_build_object(
        'success', TRUE,
        'encounter_id', p_encounter_id,
        'auth_id', p_auth_id,
        'tariff_group', p_tariff_group
    );
END;
$$;


--
-- Name: verify_patient_access(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_patient_access(p_patient_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- In this Electron desktop app, API calls use the service_role key
  -- (auth.uid() is NULL), so we only verify the patient exists.
  -- Application-layer auth is enforced by the Electron main process.
  -- Check both patients.id (uuid PK) and patients.patient_id (varchar)
  -- because different parts of the app may pass either value.
  IF NOT EXISTS (
    SELECT 1 FROM patients p
    WHERE p.id = p_patient_id
       OR p.patient_id = p_patient_id::text
  ) THEN
    RAISE EXCEPTION 'Patient not found';
  END IF;
END;
$$;


--
-- Name: verify_payment_and_route(uuid, character varying, character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_payment_and_route(p_billing_id uuid, p_payment_method character varying, p_idempotency_key character varying DEFAULT NULL::character varying, p_verified_by_staff_id character varying DEFAULT NULL::character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_billing RECORD;
  v_visit RECORD;
  v_clinic RECORD;
  v_receipt_number VARCHAR;
  v_ticket_number VARCHAR;
  v_queue_id UUID;
  v_target_location VARCHAR := 'Nursing';
  v_is_specialty_clinic BOOLEAN := FALSE;
  v_is_specialty_referral BOOLEAN := FALSE;
  v_payment_status VARCHAR;
  v_new_paid_amount NUMERIC;
  v_new_balance NUMERIC;
  v_is_insurance_payment BOOLEAN;
  v_existing_receipt RECORD;
  v_patient_display_id VARCHAR;
  v_visit_display_id VARCHAR;
BEGIN
  -- ==========================================================================
  -- STEP 1: Idempotency Check - Return existing result if already processed
  -- ==========================================================================
  IF p_idempotency_key IS NOT NULL THEN
    SELECT r.*, bo.status AS billing_status, v.current_stage
    INTO v_existing_receipt
    FROM receipts r
    JOIN billing_orders bo ON bo.id = r.billing_order_id
    LEFT JOIN visits v ON v.id = bo.encounter_id OR v.id = bo.visit_id
    WHERE r.idempotency_key = p_idempotency_key
    LIMIT 1;
    
    IF FOUND THEN
      -- Already processed - return idempotent response
      RETURN jsonb_build_object(
        'success', true,
        'idempotent', true,
        'message', 'Payment already verified (idempotent response)',
        'receipt_number', v_existing_receipt.receipt_number,
        'billing_status', v_existing_receipt.billing_status,
        'current_stage', v_existing_receipt.current_stage
      );
    END IF;
  END IF;

  -- ==========================================================================
  -- STEP 2: Lock and fetch billing order (FOR UPDATE prevents race conditions)
  -- ==========================================================================
  SELECT bo.*, 
         bo.balance_amount AS balance,
         p.patient_id AS patient_display_id,
         vis.visit_id AS visit_display_id
  INTO v_billing
  FROM billing_orders bo
  LEFT JOIN patients p ON p.id = bo.patient_id
  LEFT JOIN visits vis ON vis.id = COALESCE(bo.encounter_id, bo.visit_id::uuid)
  WHERE bo.id = p_billing_id
  FOR UPDATE OF bo;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Billing order not found'
    );
  END IF;
  
  -- Check if already paid
  IF v_billing.status IN ('Paid', 'Paid_NHIS', 'Paid_Retainership') THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Billing order already paid',
      'current_status', v_billing.status
    );
  END IF;

  -- ==========================================================================
  -- STEP 3: Fetch visit/encounter details
  -- ==========================================================================
  SELECT * INTO v_visit
  FROM visits
  WHERE id = COALESCE(v_billing.encounter_id, v_billing.visit_id::uuid)
  FOR UPDATE;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Visit/encounter not found'
    );
  END IF;

  -- ==========================================================================
  -- STEP 4: Determine payment status and amounts
  -- ==========================================================================
  v_is_insurance_payment := p_payment_method IN ('NHIS', 'Retainership');
  
  CASE p_payment_method
    WHEN 'NHIS' THEN v_payment_status := 'Paid_NHIS';
    WHEN 'Retainership' THEN v_payment_status := 'Paid_Retainership';
    ELSE v_payment_status := 'Paid';
  END CASE;
  
  v_new_paid_amount := v_billing.paid_amount + GREATEST(COALESCE(v_billing.balance, v_billing.balance_amount, 0), 0);
  v_new_balance := CASE WHEN v_is_insurance_payment THEN 0 
                        ELSE GREATEST(v_billing.net_amount - v_new_paid_amount, 0) 
                   END;

  -- ==========================================================================
  -- STEP 5: Generate receipt number
  -- ==========================================================================
  v_receipt_number := 'RCP-' || TO_CHAR(NOW(), 'YYMM') || '-' || LPAD(nextval('public.receipt_number_seq')::TEXT, 6, '0');

  -- ==========================================================================
  -- STEP 6: Update billing order status (atomic)
  -- ==========================================================================
  UPDATE billing_orders
  SET status = v_payment_status::billing_order_status,
      payment_method = p_payment_method::payment_method,
      paid_amount = v_new_paid_amount,
      balance_amount = v_new_balance,
      updated_at = NOW()
  WHERE id = p_billing_id;
  
  -- Update all billing items
  UPDATE billing_items
  SET status = 'Paid'::payment_status
  WHERE billing_order_id = p_billing_id;

  -- ==========================================================================
  -- STEP 7: Create receipt with idempotency key
  -- ==========================================================================
  v_patient_display_id := v_billing.patient_display_id;
  v_visit_display_id := v_billing.visit_display_id;
  
  INSERT INTO receipts (
    receipt_number,
    billing_order_id,
    patient_id,
    visit_id,
    encounter_id,
    amount_paid,
    payment_method,
    issued_by,
    idempotency_key
  ) VALUES (
    v_receipt_number,
    p_billing_id,
    v_patient_display_id,
    v_visit_display_id,
    v_visit.id,
    GREATEST(COALESCE(v_billing.balance, v_billing.balance_amount, 0), 0),
    p_payment_method::payment_method,
    p_verified_by_staff_id,
    COALESCE(p_idempotency_key, 'auto-' || p_billing_id::text || '-' || EXTRACT(EPOCH FROM NOW())::text)
  )
  ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL
  DO NOTHING;

  -- ==========================================================================
  -- STEP 8: Determine routing target based on clinic type
  -- ==========================================================================
  IF v_visit.clinic_id IS NOT NULL THEN
    SELECT * INTO v_clinic
    FROM clinics
    WHERE id = v_visit.clinic_id;
    
    IF FOUND THEN
      IF LOWER(COALESCE(v_clinic.clinic_name, '')) LIKE '%dental%' OR 
         LOWER(COALESCE(v_clinic.clinic_code, '')) = 'dent' THEN
        v_target_location := 'Dental';
        v_is_specialty_clinic := TRUE;
      ELSIF LOWER(COALESCE(v_clinic.clinic_name, '')) LIKE '%eye%' OR 
            LOWER(COALESCE(v_clinic.clinic_name, '')) LIKE '%ophthal%' THEN
        v_target_location := 'Ophthalmology';
        v_is_specialty_clinic := TRUE;
      ELSIF LOWER(COALESCE(v_clinic.clinic_name, '')) LIKE '%physio%' OR 
            LOWER(COALESCE(v_clinic.clinic_name, '')) LIKE '%rehab%' THEN
        v_target_location := 'Physiotherapy';
        v_is_specialty_clinic := TRUE;
      END IF;
    END IF;
  END IF;
  
  v_is_specialty_referral := v_visit.is_referral_encounter AND v_visit.source_referral_id IS NOT NULL;

  -- ==========================================================================
  -- STEP 9: Complete existing billing queue entry
  -- ==========================================================================
  UPDATE queue
  SET status = 'Completed',
      completed_at = NOW()
  WHERE visit_id = v_visit.id
    AND location = 'Billing'
    AND status IN ('Waiting', 'Called', 'In Progress');

  -- ==========================================================================
  -- STEP 10: Handle routing based on workflow type
  -- ==========================================================================
  
  -- For specialty referrals: update clinical_request, skip queue table
  IF v_is_specialty_referral AND v_is_specialty_clinic THEN
    UPDATE clinical_requests
    SET status = 'Approved',
        updated_at = NOW()
    WHERE id = v_visit.source_referral_id;
    
    -- Update stage for referral patients (they show in Referrals Queue)
    UPDATE visits
    SET current_stage = 'queue_waiting',
        stage_updated_at = NOW(),
        updated_at = NOW()
    WHERE id = v_visit.id;
    
    RETURN jsonb_build_object(
      'success', true,
      'idempotent', false,
      'receipt_number', v_receipt_number,
      'billing_status', v_payment_status,
      'current_stage', 'queue_waiting',
      'target_location', v_target_location,
      'is_referral', true,
      'message', 'Patient routed to ' || v_target_location || ' Referrals Queue'
    );
  END IF;
  
  -- For normal patients: create queue entry atomically
  -- Generate ticket number
  SELECT COALESCE(MAX(CAST(ticket_number AS INTEGER)), 0) + 1
  INTO v_ticket_number
  FROM queue
  WHERE location = v_target_location::queue_location
    AND created_at::date = CURRENT_DATE;
  
  v_ticket_number := COALESCE(v_ticket_number, '1');
  
  -- Insert queue entry with conflict handling (idempotent)
  INSERT INTO queue (
    patient_id,
    visit_id,
    encounter_id,
    clinic_id,
    ticket_number,
    location,
    priority,
    status,
    notes
  ) VALUES (
    v_visit.patient_id,
    v_visit.id,
    v_visit.id,
    v_visit.clinic_id,
    v_ticket_number,
    v_target_location::queue_location,
    COALESCE(v_visit.priority, 'Normal'),
    'Waiting',
    'Auto-routed after payment verification (Receipt: ' || v_receipt_number || ')'
  )
  ON CONFLICT (encounter_id, location) 
  WHERE status IN ('Waiting', 'Called', 'In Progress')
  DO UPDATE SET 
    notes = queue.notes || ' [Retry at ' || NOW()::text || ']'
  RETURNING id INTO v_queue_id;

  -- ==========================================================================
  -- STEP 11: Update visit stage (atomic with queue creation)
  -- ==========================================================================
  UPDATE visits
  SET current_stage = 'queue_waiting',
      stage_updated_at = NOW(),
      updated_at = NOW()
  WHERE id = v_visit.id;

  -- ==========================================================================
  -- STEP 12: Return success with all details
  -- ==========================================================================
  RETURN jsonb_build_object(
    'success', true,
    'idempotent', false,
    'receipt_number', v_receipt_number,
    'billing_status', v_payment_status,
    'current_stage', 'queue_waiting',
    'target_location', v_target_location,
    'ticket_number', v_ticket_number,
    'queue_id', v_queue_id,
    'is_referral', false,
    'message', 'Patient routed to ' || v_target_location || ' queue with ticket #' || v_ticket_number
  );

EXCEPTION
  WHEN unique_violation THEN
    -- Handle race condition - likely idempotent retry
    RETURN jsonb_build_object(
      'success', true,
      'idempotent', true,
      'message', 'Payment likely already processed (unique violation caught)',
      'billing_id', p_billing_id
    );
  WHEN OTHERS THEN
    RAISE;
END;
$$;


--
-- Name: admissions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.admissions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    facility_id uuid NOT NULL,
    patient_id uuid NOT NULL,
    encounter_id uuid,
    admission_number character varying(50) NOT NULL,
    admission_date timestamp with time zone DEFAULT now() NOT NULL,
    expected_discharge_date date,
    actual_discharge_date timestamp with time zone,
    admission_type character varying(50) NOT NULL,
    admission_source character varying(50),
    current_ward_id uuid,
    current_bed_id uuid,
    admitting_diagnosis text NOT NULL,
    admitting_diagnosis_icd10 character varying(20),
    secondary_diagnoses jsonb DEFAULT '[]'::jsonb,
    chief_complaint text,
    reason_for_admission text,
    admitting_doctor_id uuid,
    attending_physician_id uuid,
    primary_nurse_id uuid,
    care_team jsonb DEFAULT '[]'::jsonb,
    admission_status character varying(30) DEFAULT 'admitted'::character varying NOT NULL,
    acuity_level character varying(20),
    code_status character varying(30) DEFAULT 'full_code'::character varying,
    isolation_required boolean DEFAULT false,
    isolation_type character varying(50),
    fall_risk_level character varying(20),
    pressure_ulcer_risk character varying(20),
    allergies_snapshot jsonb DEFAULT '[]'::jsonb,
    alerts jsonb DEFAULT '[]'::jsonb,
    diet_type character varying(50),
    diet_restrictions text,
    activity_level character varying(50),
    mobility_status character varying(50),
    discharge_type character varying(50),
    discharge_disposition text,
    discharge_diagnosis text,
    discharge_diagnosis_icd10 character varying(20),
    discharge_summary text,
    discharge_instructions text,
    follow_up_appointments jsonb DEFAULT '[]'::jsonb,
    discharge_medications jsonb DEFAULT '[]'::jsonb,
    discharged_by uuid,
    insurance_verified boolean DEFAULT false,
    pre_authorization_number character varying(100),
    estimated_cost numeric(12,2),
    notes text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    created_by uuid,
    updated_by uuid,
    clinical_request_id uuid,
    idempotency_key public.idempotency_key_t,
    version integer DEFAULT 1 NOT NULL,
    idempotency_created_at timestamp with time zone,
    idempotency_hash character varying(64),
    last_modified_by uuid,
    nhis_approval_status public.nhis_approval_status DEFAULT 'not_required'::public.nhis_approval_status,
    nhis_approval_id uuid,
    daily_bed_rate numeric(10,2),
    nhis_daily_bed_rate numeric(10,2),
    total_bed_charges numeric(12,2),
    nhis_total_bed_charges numeric(12,2),
    CONSTRAINT admissions_acuity_level_check CHECK (((acuity_level)::text = ANY (ARRAY[('low'::character varying)::text, ('moderate'::character varying)::text, ('high'::character varying)::text, ('critical'::character varying)::text]))),
    CONSTRAINT admissions_admission_source_check CHECK (((admission_source)::text = ANY (ARRAY[('emergency'::character varying)::text, ('outpatient'::character varying)::text, ('referral'::character varying)::text, ('transfer'::character varying)::text, ('direct'::character varying)::text]))),
    CONSTRAINT admissions_admission_status_check CHECK (((admission_status)::text = ANY (ARRAY[('admitted'::character varying)::text, ('under_observation'::character varying)::text, ('critical'::character varying)::text, ('stable'::character varying)::text, ('improving'::character varying)::text, ('discharged'::character varying)::text, ('transferred'::character varying)::text, ('deceased'::character varying)::text, ('absconded'::character varying)::text]))),
    CONSTRAINT admissions_admission_type_check CHECK (((admission_type)::text = ANY (ARRAY[('emergency'::character varying)::text, ('elective'::character varying)::text, ('transfer'::character varying)::text, ('observation'::character varying)::text, ('day_case'::character varying)::text]))),
    CONSTRAINT admissions_code_status_check CHECK (((code_status)::text = ANY (ARRAY[('full_code'::character varying)::text, ('dnr'::character varying)::text, ('dni'::character varying)::text, ('dnr_dni'::character varying)::text, ('comfort_care'::character varying)::text]))),
    CONSTRAINT admissions_discharge_type_check CHECK (((discharge_type)::text = ANY (ARRAY[('home'::character varying)::text, ('transfer'::character varying)::text, ('against_medical_advice'::character varying)::text, ('deceased'::character varying)::text, ('skilled_nursing'::character varying)::text, ('rehabilitation'::character varying)::text, ('hospice'::character varying)::text, ('other'::character varying)::text])))
);


--
-- Name: beds; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.beds (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ward_id uuid NOT NULL,
    bed_number character varying(20) NOT NULL,
    bed_type character varying(50) NOT NULL,
    status character varying(30) DEFAULT 'available'::character varying NOT NULL,
    features jsonb DEFAULT '[]'::jsonb,
    daily_rate numeric(10,2),
    current_patient_id uuid,
    current_admission_id uuid,
    location_details text,
    is_active boolean DEFAULT true,
    last_cleaned_at timestamp with time zone,
    last_maintenance_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT beds_bed_type_check CHECK (((bed_type)::text = ANY (ARRAY[('standard'::character varying)::text, ('electric'::character varying)::text, ('icu'::character varying)::text, ('pediatric'::character varying)::text, ('bariatric'::character varying)::text, ('low'::character varying)::text, ('stretcher'::character varying)::text, ('crib'::character varying)::text, ('bassinet'::character varying)::text]))),
    CONSTRAINT beds_status_check CHECK (((status)::text = ANY (ARRAY[('Available'::character varying)::text, ('Occupied'::character varying)::text, ('Cleaning'::character varying)::text, ('Maintenance'::character varying)::text, ('Reserved'::character varying)::text, ('available'::character varying)::text, ('occupied'::character varying)::text, ('cleaning'::character varying)::text, ('maintenance'::character varying)::text, ('reserved'::character varying)::text]))),
    CONSTRAINT chk_bed_rate_non_negative CHECK (((daily_rate IS NULL) OR (daily_rate >= (0)::numeric)))
);


--
-- Name: staff; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.staff (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    staff_id character varying(50),
    email character varying(255) NOT NULL,
    first_name character varying(100) NOT NULL,
    last_name character varying(100) NOT NULL,
    role public.user_role NOT NULL,
    staff_category public.staff_category,
    military_branch public.military_branch,
    rank character varying(100),
    service_number character varying(100),
    department_id uuid,
    phone character varying(50),
    is_active boolean DEFAULT true,
    last_login timestamp with time zone,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    department text,
    user_id uuid,
    facility_id uuid,
    last_activity timestamp with time zone,
    photo_url text,
    specialty_code character varying(50),
    auth_user_id uuid
);


--
-- Name: wards; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.wards (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    facility_id uuid NOT NULL,
    name character varying(100) NOT NULL,
    code character varying(20) NOT NULL,
    ward_type character varying(50) NOT NULL,
    total_beds integer DEFAULT 0 NOT NULL,
    available_beds integer DEFAULT 0 NOT NULL,
    description text,
    floor_number integer,
    building character varying(100),
    nurse_station_phone character varying(20),
    head_nurse_id uuid,
    is_active boolean DEFAULT true,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    created_by uuid,
    updated_by uuid,
    gender_restriction character varying(20),
    price numeric(10,2) DEFAULT 0,
    nhis_price numeric(10,2) DEFAULT 0,
    is_nhis_covered boolean DEFAULT true,
    nhis_percentage integer DEFAULT 50,
    CONSTRAINT available_beds_check CHECK (((available_beds >= 0) AND (available_beds <= total_beds))),
    CONSTRAINT wards_gender_restriction_check CHECK (((gender_restriction)::text = ANY (ARRAY[('male'::character varying)::text, ('female'::character varying)::text, ('none'::character varying)::text]))),
    CONSTRAINT wards_ward_type_check CHECK (((ward_type)::text = ANY (ARRAY[('general'::character varying)::text, ('icu'::character varying)::text, ('pediatric'::character varying)::text, ('maternity'::character varying)::text, ('surgical'::character varying)::text, ('orthopedic'::character varying)::text, ('cardiac'::character varying)::text, ('emergency'::character varying)::text, ('psychiatric'::character varying)::text, ('isolation'::character varying)::text])))
);


--
-- Name: active_admissions_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.active_admissions_view WITH (security_invoker='true') AS
 SELECT a.id AS admission_id,
    a.admission_number,
    a.admission_date,
    a.admission_type,
    a.admission_status,
    a.admitting_diagnosis,
    a.acuity_level,
    a.expected_discharge_date,
    p.id AS patient_id,
    p.first_name,
    p.surname AS last_name,
    p.date_of_birth,
    p.gender,
    p.emr_number AS hospital_id,
    w.name AS ward_name,
    w.ward_type,
    b.bed_number,
    s.first_name AS physician_first_name,
    s.last_name AS physician_last_name,
    a.facility_id,
    a.current_ward_id,
    a.current_bed_id,
    a.encounter_id,
    COALESCE((bo.status)::text, 'Pending'::text) AS billing_status,
    bo.id AS billing_order_id,
    bo.total_amount AS billing_amount
   FROM (((((public.admissions a
     JOIN public.patients p ON ((p.id = a.patient_id)))
     LEFT JOIN public.wards w ON ((w.id = a.current_ward_id)))
     LEFT JOIN public.beds b ON ((b.id = a.current_bed_id)))
     LEFT JOIN public.staff s ON ((s.id = a.attending_physician_id)))
     LEFT JOIN LATERAL ( SELECT orders.id,
            orders.status,
            orders.total_amount
           FROM public.billing_orders orders
          WHERE (((orders.source_module = 'admission'::public.source_module) AND (orders.patient_id = a.patient_id) AND (date(orders.created_at) = date(a.admission_date))) OR ((a.encounter_id IS NOT NULL) AND (orders.encounter_id = a.encounter_id)))
          ORDER BY orders.created_at DESC
         LIMIT 1) bo ON (true))
  WHERE ((a.admission_status)::text <> ALL (ARRAY[('discharged'::character varying)::text, ('deceased'::character varying)::text]));


