--
-- Name: active_encounter_queue; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.active_encounter_queue AS
 SELECT v.id,
    v.visit_id,
    v.patient_id,
    v.clinic_id,
    v.visit_type,
    v.encounter_number,
    v.encounter_date,
    v.priority,
    v.chief_complaint,
    v.payment_category,
    v.insurance_type,
    v.status,
    v.current_stage,
    v.stage_updated_at,
    v.start_time,
    v.end_time,
    v.attending_doctor_id,
    v.registered_by,
    v.opd_classification,
    v.created_at,
    v.updated_at,
    p.id AS p_id,
    p.patient_id AS p_patient_id,
    p.first_name AS p_first_name,
    p.surname AS p_surname,
    p.date_of_birth AS p_date_of_birth,
    p.gender AS p_gender,
    p.contact_phone AS p_contact_phone,
    p.emr_number AS p_emr_number,
    p.nhis_number AS p_nhis_number,
    p.insurance_type AS p_insurance_type,
    p.patient_type AS p_patient_type,
    q.id AS q_id,
    q.status AS q_status,
    q.location AS q_location,
    q.assigned_to AS q_assigned_to,
    q.called_at AS q_called_at,
    q.started_at AS q_started_at,
    q.completed_at AS q_completed_at,
    q.ticket_number AS q_ticket_number,
    q.specialty_code AS q_specialty_code,
    q.notes AS q_notes,
    q.department_id AS q_department_id,
    q.created_at AS q_created_at
   FROM ((public.visits v
     JOIN public.patients p ON ((p.id = v.patient_id)))
     LEFT JOIN LATERAL ( SELECT qinner.id,
            qinner.visit_id,
            qinner.patient_id,
            qinner.department_id,
            qinner.clinic_id,
            qinner.ticket_number,
            qinner.status,
            qinner.priority,
            qinner.location,
            qinner.assigned_to,
            qinner.called_at,
            qinner.started_at,
            qinner.completed_at,
            qinner.notes,
            qinner.created_at,
            qinner.updated_at,
            qinner.wait_start_time,
            qinner.ready_time,
            qinner.consultation_start_time,
            qinner.consultation_end_time,
            qinner.skipped_count,
            qinner.skip_reason,
            qinner.encounter_id,
            qinner.idempotency_key,
            qinner.specialty_code,
            qinner.session_started_at,
            qinner.session_staff_id,
            qinner.session_notes
           FROM public.queue qinner
          WHERE ((qinner.visit_id = v.id) AND (qinner.status = ANY (ARRAY['Waiting'::public.queue_status, 'In Progress'::public.queue_status, 'Called'::public.queue_status])))
          ORDER BY qinner.created_at DESC
         LIMIT 1) q ON (true))
  WHERE (v.status = 'Active'::public.visit_status);


