--
-- Name: billing_record_hierarchy; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.billing_record_hierarchy WITH (security_invoker='true') AS
 SELECT p.id AS patient_uuid,
    p.emr_number,
    (((p.first_name)::text || ' '::text) || (p.surname)::text) AS patient_name,
    p.contact_phone,
    v.id AS encounter_uuid,
    v.encounter_number,
    v.visit_type,
    v.encounter_date,
    v.chief_complaint,
    v.payment_category,
    v.status AS encounter_status,
    i.invoice_id,
    i.invoice_number,
    i.total_amount,
    i.amount_paid,
    i.balance,
    i.status AS invoice_status,
    i.created_at AS invoice_date
   FROM ((public.invoices i
     JOIN public.visits v ON ((i.encounter_id = v.id)))
     JOIN public.patients p ON ((v.patient_id = p.id)))
  ORDER BY i.created_at DESC;


