--
-- Name: eye_exam_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.eye_exam_summary WITH (security_invoker='true') AS
 SELECT ee.patient_id,
    ee.patient_uuid,
    ee.encounter_id,
    v.visit_type,
    v.status AS encounter_status,
    p.first_name,
    p.surname,
    p.emr_number,
    ee.va_right_aided,
    ee.va_left_aided,
    ee.bcva_right,
    ee.bcva_left,
    ee.iop_right,
    ee.iop_left,
    concat(
        CASE
            WHEN (ee.rx_right_sphere >= (0)::numeric) THEN '+'::text
            ELSE ''::text
        END, ee.rx_right_sphere, '/', ee.rx_right_cylinder, 'x', ee.rx_right_axis) AS rx_right,
    concat(
        CASE
            WHEN (ee.rx_left_sphere >= (0)::numeric) THEN '+'::text
            ELSE ''::text
        END, ee.rx_left_sphere, '/', ee.rx_left_cylinder, 'x', ee.rx_left_axis) AS rx_left,
    ee.final_diagnosis,
    ee.glasses_prescribed,
    ee.surgery_recommended,
    ee.created_at AS exam_date
   FROM ((public.eye_exams ee
     LEFT JOIN public.visits v ON ((v.id = ee.encounter_id)))
     LEFT JOIN public.patients p ON (((p.id = ee.patient_uuid) OR ((p.patient_id)::text = (ee.patient_id)::text))));


