--
-- Name: hygiene_compliance_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.hygiene_compliance_view WITH (security_invoker='true') AS
 SELECT h.ward_id,
    w.name AS ward_name,
    (h.activity_category)::text AS activity_category,
    h.shift,
    date(h.performed_time) AS care_date,
    count(*) AS total_records,
    count(*) FILTER (WHERE (h.status = 'Completed'::public.hygiene_status)) AS completed,
    count(*) FILTER (WHERE (h.status = 'Missed'::public.hygiene_status)) AS missed,
    count(*) FILTER (WHERE (h.status = 'Refused'::public.hygiene_status)) AS refused,
    round((((count(*) FILTER (WHERE (h.status = 'Completed'::public.hygiene_status)))::numeric / (NULLIF(count(*), 0))::numeric) * (100)::numeric), 1) AS compliance_rate
   FROM (public.hygiene_care_records h
     LEFT JOIN public.wards w ON ((h.ward_id = w.id)))
  GROUP BY h.ward_id, w.name, h.activity_category, h.shift, (date(h.performed_time))
  ORDER BY (date(h.performed_time)) DESC, w.name;


