--
-- Name: infection_surveillance_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.infection_surveillance_summary WITH (security_invoker='true') AS
 SELECT (infection_type)::text AS infection_type,
    date_trunc('month'::text, (detected_date)::timestamp with time zone) AS month,
    count(*) AS total_cases,
    count(*) FILTER (WHERE (device_related = true)) AS device_related,
    count(*) FILTER (WHERE (surgery_id IS NOT NULL)) AS surgery_related,
    count(*) FILTER (WHERE (outcome = 'Resolved'::public.infection_outcome)) AS resolved,
    count(*) FILTER (WHERE (outcome = 'Ongoing'::public.infection_outcome)) AS ongoing,
    avg(device_days) FILTER (WHERE (device_related = true)) AS avg_device_days
   FROM public.infection_surveillance i
  GROUP BY infection_type, (date_trunc('month'::text, (detected_date)::timestamp with time zone))
  ORDER BY (date_trunc('month'::text, (detected_date)::timestamp with time zone)) DESC, (infection_type)::text;


