    verified_by uuid,
    verified_at timestamp with time zone,
    verification_notes text,
    renewal_required_at timestamp with time zone,
    renewed_from_id uuid,
    attachment_path text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    created_by uuid,
    revoked_by uuid,
    revoked_at timestamp with time zone,
    revocation_reason text,
    is_provisional boolean DEFAULT false,
    provisional_reason text,
    provisional_approved_by uuid,
    provisional_approved_at timestamp with time zone,
    actual_code_received_at timestamp with time zone,
    specific_clinic_code character varying(50),
    specific_service_type character varying(50),
    authorization_source character varying(20),
    CONSTRAINT chk_nhis_auth_service_type CHECK ((((specific_service_type)::text = ANY (ARRAY[('general_outpatient'::character varying)::text, ('dental'::character varying)::text, ('ophthalmology'::character varying)::text, ('physiotherapy'::character varying)::text, ('laboratory'::character varying)::text, ('radiology'::character varying)::text, ('pharmacy'::character varying)::text, ('surgery'::character varying)::text, ('ent'::character varying)::text, ('cardiology'::character varying)::text, ('orthopedics'::character varying)::text, ('obstetrics_gynecology'::character varying)::text, ('pediatrics'::character varying)::text, ('psychiatry'::character varying)::text, ('other'::character varying)::text])) OR (specific_service_type IS NULL))),
    CONSTRAINT chk_nhis_auth_source CHECK ((((authorization_source)::text = ANY (ARRAY[('internal'::character varying)::text, ('external'::character varying)::text])) OR (authorization_source IS NULL)))
);


--
-- Name: nhis_authorization_service_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.nhis_authorization_service_summary WITH (security_invoker='true') AS
 SELECT specific_service_type,
    count(*) FILTER (WHERE ((status = 'active'::public.nhis_auth_status) AND (expiry_date > now()))) AS active_count,
    count(*) FILTER (WHERE ((is_provisional = true) AND (actual_code_received_at IS NULL))) AS provisional_pending_count,
    count(*) FILTER (WHERE ((status = 'expired'::public.nhis_auth_status) OR (expiry_date < now()))) AS expired_count,
    count(*) AS total_count
   FROM public.nhis_authorizations
  WHERE (created_at > (now() - '30 days'::interval))
  GROUP BY specific_service_type
  ORDER BY (count(*) FILTER (WHERE ((status = 'active'::public.nhis_auth_status) AND (expiry_date > now())))) DESC;


