--
-- Name: nhis_authorizations_expiring_soon; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.nhis_authorizations_expiring_soon WITH (security_invoker='true') AS
 SELECT a.id AS authorization_id,
    a.patient_id,
    (((p.first_name)::text || ' '::text) || (p.surname)::text) AS patient_name,
    p.emr_number,
    a.auth_code,
    a.specific_service_type,
    a.is_provisional,
    a.expiry_date,
    date_part('day'::text, (a.expiry_date - now())) AS days_until_expiry,
        CASE
            WHEN (a.expiry_date < now()) THEN 'expired'::text
            WHEN (date_part('day'::text, (a.expiry_date - now())) <= (3)::double precision) THEN 'critical'::text
            ELSE 'warning'::text
        END AS expiry_status
   FROM (public.nhis_authorizations a
     JOIN public.patients p ON ((a.patient_id = p.id)))
  WHERE ((a.status = 'active'::public.nhis_auth_status) AND ((a.expiry_date >= now()) AND (a.expiry_date <= (now() + '7 days'::interval))))
  ORDER BY a.expiry_date;


