    coverage_type character varying(20) DEFAULT 'Full'::character varying,
    facility_id uuid,
    CONSTRAINT nhis_claims_coverage_type_check CHECK (((coverage_type)::text = ANY (ARRAY[('Full'::character varying)::text, ('Partial'::character varying)::text, ('Not Covered'::character varying)::text])))
);


--
-- Name: nhis_claims_comprehensive; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.nhis_claims_comprehensive WITH (security_invoker='true') AS
 SELECT nc.id,
    nc.claim_number,
    nc.encounter_id,
    nc.patient_id,
    p.emr_number,
    concat_ws(' '::text, p.first_name, p.middle_name, p.surname) AS patient_name,
    p.insurance_type,
    p.nhis_number,
    v.encounter_number,
    v.encounter_date,
    v.payment_category,
    nc.hmo_id,
    nc.hmo_name,
    nc.payer_name,
    nc.scheme_type,
    nc.tariff_group,
    na.auth_code AS authorization_code,
    na.status AS authorization_status,
    nc.total_tariff,
    nc.claimable_amount AS nhis_amount,
    nc.patient_pay_amount AS patient_amount,
    nc.coverage_type,
        CASE
            WHEN (nc.total_tariff > (0)::numeric) THEN round(((COALESCE(nc.claimable_amount, (0)::numeric) / (nc.total_tariff)::numeric) * (100)::numeric))
            ELSE (0)::numeric
        END AS coverage_percentage,
    nc.invoice_id,
    nc.invoice_number,
    nc.receipt_id,
    nc.receipt_number,
    nc.status AS claim_status,
    nc.created_at,
    nc.updated_at,
    nc.submitted_at,
    nc.processed_at,
    nc.approved_at,
    nc.rejected_at,
    nc.paid_at,
    (((s_created.first_name)::text || ' '::text) || (s_created.last_name)::text) AS created_by_name,
    (((s_approved.first_name)::text || ' '::text) || (s_approved.last_name)::text) AS approved_by_name,
    (((s_processed.first_name)::text || ' '::text) || (s_processed.last_name)::text) AS processed_by_name,
    (((s_submitted.first_name)::text || ' '::text) || (s_submitted.last_name)::text) AS submitted_by_name,
    nc.rejection_reason,
    (((s_rejected.first_name)::text || ' '::text) || (s_rejected.last_name)::text) AS rejected_by_name
   FROM ((((((((public.nhis_claims nc
     LEFT JOIN public.patients p ON ((p.id = nc.patient_id)))
     LEFT JOIN public.visits v ON ((v.id = nc.encounter_id)))
     LEFT JOIN public.nhis_authorizations na ON ((na.id = nc.auth_id)))
     LEFT JOIN public.staff s_created ON ((s_created.id = nc.created_by)))
     LEFT JOIN public.staff s_approved ON ((s_approved.id = nc.approved_by)))
     LEFT JOIN public.staff s_processed ON ((s_processed.id = nc.processed_by)))
     LEFT JOIN public.staff s_submitted ON ((s_submitted.id = nc.submitted_by)))
     LEFT JOIN public.staff s_rejected ON ((s_rejected.id = nc.rejected_by)));


