--
-- Name: nhis_outgoing_referrals_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.nhis_outgoing_referrals_view WITH (security_invoker='true') AS
 SELECT q.id AS queue_id,
    q.request_type,
    q.status AS queue_status,
    q.referral_direction,
    q.requested_at,
    q.processed_at,
    q.nhis_referral_code,
    q.referral_valid_from,
    q.referral_valid_to,
        CASE
            WHEN ((q.referral_valid_to IS NOT NULL) AND (CURRENT_DATE > q.referral_valid_to)) THEN true
            ELSE false
        END AS is_expired,
    q.destination_facility_name,
    q.destination_facility_nhis_id,
    q.destination_facility_address,
    p.id AS patient_id,
    p.patient_id AS file_number,
    p.emr_number,
    p.first_name,
    p.middle_name,
    p.surname,
    concat_ws(' '::text, p.first_name, p.middle_name, p.surname) AS patient_full_name,
    p.date_of_birth,
    EXTRACT(year FROM age((CURRENT_DATE)::timestamp with time zone, (p.date_of_birth)::timestamp with time zone)) AS patient_age,
    p.gender,
    p.contact_phone,
    p.residential_address,
    p.nhis_number,
    (p.payer_info ->> 'scheme'::text) AS hmo_code,
    (p.payer_info ->> 'enrolee_id'::text) AS nhis_id_no,
    q.chief_complaint AS clinical_findings,
    q.examination_findings,
    q.investigation_findings,
    q.provisional_diagnosis,
    q.diagnosis,
    q.clinical_basis AS reason_for_referral,
    q.clinical_notes,
    rd.id AS referring_doctor_id,
    concat_ws(' '::text, rd.first_name, rd.last_name) AS referring_doctor_name,
    rd.department AS referring_doctor_department,
    q.referring_doctor_signature,
    q.source_encounter_id,
    v.encounter_number,
    v.encounter_date,
    q.printed_at,
    q.printed_by,
    q.print_count,
    ps.first_name AS printed_by_first_name,
    ps.last_name AS printed_by_last_name,
    q.processed_by,
    aps.first_name AS approved_by_first_name,
    aps.last_name AS approved_by_last_name,
    q.processing_notes AS approval_notes
   FROM (((((public.nhis_referral_queue q
     LEFT JOIN public.patients p ON ((q.patient_id = p.id)))
     LEFT JOIN public.staff rd ON ((q.requesting_doctor_id = rd.id)))
     LEFT JOIN public.visits v ON ((q.source_encounter_id = v.id)))
     LEFT JOIN public.staff ps ON ((q.printed_by = ps.id)))
     LEFT JOIN public.staff aps ON ((q.processed_by = aps.id)))
  WHERE ((q.referral_direction)::text = 'outgoing'::text)
  ORDER BY
        CASE q.status
            WHEN 'approved'::text THEN 1
            WHEN 'pending'::text THEN 2
            WHEN 'completed'::text THEN 3
            ELSE 4
        END, q.requested_at DESC;


