--
-- Name: nhis_pending_approvals; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.nhis_pending_approvals WITH (security_invoker='true') AS
 SELECT 'lab'::text AS service_type,
    lr.request_id AS service_id,
    lr.encounter_id,
    lr.patient_id,
    p.emr_number,
    (((p.first_name)::text || ' '::text) || (p.surname)::text) AS patient_name,
    ltc.name AS service_name,
    ltc.code AS service_code,
    (lr.nhis_approval_status)::text AS nhis_approval_status,
    lr.created_at AS requested_at,
    (lr.status)::text AS current_status
   FROM ((public.lab_requests lr
     JOIN public.patients p ON (((lr.patient_id)::text = (p.patient_id)::text)))
     LEFT JOIN public.lab_test_catalogue ltc ON ((lr.test_id = ltc.id)))
  WHERE ((lr.nhis_approval_status)::text = 'pending'::text)
UNION ALL
 SELECT 'radiology'::text AS service_type,
    rr.request_id AS service_id,
    rr.encounter_id,
    rr.patient_id,
    p.emr_number,
    (((p.first_name)::text || ' '::text) || (p.surname)::text) AS patient_name,
    ic.name AS service_name,
    ic.code AS service_code,
    (rr.nhis_approval_status)::text AS nhis_approval_status,
    rr.created_at AS requested_at,
    (rr.status)::text AS current_status
   FROM ((public.radiology_requests rr
     JOIN public.patients p ON (((rr.patient_id)::text = (p.patient_id)::text)))
     LEFT JOIN public.imaging_catalogue ic ON ((rr.imaging_id = ic.id)))
  WHERE ((rr.nhis_approval_status)::text = 'pending'::text)
UNION ALL
 SELECT 'pharmacy'::text AS service_type,
    rx.prescription_id AS service_id,
    rx.encounter_id,
    rx.patient_id,
    p.emr_number,
    (((p.first_name)::text || ' '::text) || (p.surname)::text) AS patient_name,
    dc.name AS service_name,
    dc.code AS service_code,
    (rx.nhis_approval_status)::text AS nhis_approval_status,
    rx.created_at AS requested_at,
    (rx.status)::text AS current_status
   FROM ((public.prescriptions rx
     JOIN public.patients p ON (((rx.patient_id)::text = (p.patient_id)::text)))
     LEFT JOIN public.drug_catalogue dc ON ((rx.drug_id = dc.id)))
  WHERE ((rx.nhis_approval_status)::text = 'pending'::text)
UNION ALL
 SELECT 'procedure'::text AS service_type,
    pr.request_id AS service_id,
    pr.encounter_id,
    pr.patient_id,
    p.emr_number,
    (((p.first_name)::text || ' '::text) || (p.surname)::text) AS patient_name,
    pc.name AS service_name,
    pc.code AS service_code,
    pr.nhis_approval_status,
    pr.created_at AS requested_at,
    pr.status AS current_status
   FROM ((public.procedure_requests pr
     JOIN public.patients p ON (((pr.patient_id)::text = (p.patient_id)::text)))
     LEFT JOIN public.procedure_catalogue pc ON ((pr.procedure_id = pc.id)))
  WHERE (pr.nhis_approval_status = 'pending'::text)
  ORDER BY 10;


--
-- Name: nhis_pending_outgoing_referrals; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.nhis_pending_outgoing_referrals WITH (security_invoker='true') AS
 SELECT q.id AS queue_id,
    q.status,
    q.urgency,
    q.requested_at,
    p.id AS patient_id,
    p.patient_id AS file_number,
    concat_ws(' '::text, p.first_name, p.middle_name, p.surname) AS patient_name,
    p.contact_phone,
    p.nhis_number,
    (p.payer_info ->> 'scheme'::text) AS hmo_scheme,
    (p.payer_info ->> 'enrolee_id'::text) AS hmo_enrolee_id,
    q.provisional_diagnosis,
    q.clinical_basis AS reason_for_referral,
    concat_ws(' '::text, rd.first_name, rd.last_name) AS referring_doctor,
    q.nhis_referral_code,
    q.destination_facility_name,
    q.destination_facility_nhis_id,
    q.referral_valid_from,
    q.referral_valid_to
   FROM ((public.nhis_referral_queue q
     LEFT JOIN public.patients p ON ((q.patient_id = p.id)))
     LEFT JOIN public.staff rd ON ((q.requesting_doctor_id = rd.id)))
  WHERE (((q.referral_direction)::text = 'outgoing'::text) AND ((q.status)::text = 'pending'::text))
  ORDER BY
        CASE q.urgency
            WHEN 'Emergency'::text THEN 1
            WHEN 'Urgent'::text THEN 2
            ELSE 3
        END, q.requested_at;


