--
-- Name: nhis_pending_requests_comprehensive; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.nhis_pending_requests_comprehensive WITH (security_invoker='true') AS
 SELECT q.id AS queue_id,
    q.request_type,
    q.service_type,
    q.service_name,
    q.status AS queue_status,
    q.priority,
    q.urgency,
    q.requested_at,
    q.processed_at,
    q.clinical_request_id,
    cr.request_number AS clinical_request_number,
    p.id AS patient_id,
    p.patient_id AS patient_number,
    p.emr_number,
    p.first_name,
    p.middle_name,
    p.surname,
    p.date_of_birth,
    p.gender,
    p.contact_phone,
    p.residential_address,
    p.nationality,
    p.state_of_origin,
    p.lga,
    p.patient_category,
    p.patient_type,
    p.insurance_type,
    p.service_number,
    p.rank,
    p.unit,
    p.military_branch,
    p.title,
    p.course,
    p.occupation,
    p.employer,
    p.nhis_number,
    p.nhis_patient_source,
    (p.payer_info ->> 'scheme'::text) AS hmo_scheme_name,
    (p.payer_info ->> 'enrolee_id'::text) AS hmo_enrolee_id,
    (p.payer_info ->> 'relationship'::text) AS hmo_relationship,
    (p.payer_info ->> 'expiration_date'::text) AS hmo_expiration_date,
    (p.payer_info ->> 'principal_name'::text) AS principal_name,
    (p.payer_info ->> 'principal_rank'::text) AS principal_rank,
    (p.payer_info ->> 'principal_service_number'::text) AS principal_service_number,
    (p.payer_info ->> 'principal_unit'::text) AS principal_unit,
    p.referral_code AS patient_referral_code,
    p.referring_facility_name AS patient_referring_facility,
    p.referring_facility_nhis_id AS patient_referring_facility_nhis_id,
    p.referral_date AS patient_referral_date,
    p.referral_reason AS patient_referral_reason,
    p.referral_status AS patient_referral_status,
    p.referral_expiry_date AS patient_referral_expiry,
    p.clinical_summary AS patient_clinical_summary,
    np.enrollee_id AS nhis_profile_enrollee_id,
    np.scheme_type AS nhis_scheme_type,
    np.provider_name AS nhis_provider_name,
    np.plan_category AS nhis_plan_category,
    np.tariff_group AS nhis_tariff_group,
    np.status AS nhis_profile_status,
    np.patient_origin AS nhis_patient_origin,
    np.referring_facility_name AS nhis_referring_facility,
    np.referral_code AS nhis_profile_referral_code,
    np.referral_date AS nhis_profile_referral_date,
    np.referral_reason AS nhis_profile_referral_reason,
    q.chief_complaint,
    q.diagnosis,
    q.diagnosis_codes,
    q.examination_findings,
    q.history_of_present_illness,
    q.clinical_basis AS referral_reason,
    q.clinical_notes,
    q.treatment_plan,
    COALESCE(q.chief_complaint, v.chief_complaint) AS effective_chief_complaint,
    COALESCE(q.diagnosis, c.diagnosis_text, array_to_string(c.diagnosis, ', '::text)) AS effective_diagnosis,
    COALESCE(q.examination_findings, c.examination_findings) AS effective_examination_findings,
    COALESCE(q.history_of_present_illness, c.history_of_present_illness) AS effective_hpi,
    q.source_encounter_id,
    v.encounter_number AS source_encounter_number,
    v.encounter_date AS source_encounter_date,
    v.visit_type AS source_visit_type,
    rd.id AS requesting_doctor_id,
    rd.first_name AS requesting_doctor_first_name,
    rd.last_name AS requesting_doctor_last_name,
    rd.department AS requesting_doctor_department,
    q.target_clinic_id,
    tc.clinic_name AS target_clinic_name,
    q.target_doctor_id,
    td.first_name AS target_doctor_first_name,
    td.last_name AS target_doctor_last_name,
    q.specialty_module,
    q.admission_type,
    q.level_of_care,
    q.expected_duration,
    q.referral_code,
    q.referral_date,
    q.referral_source,
    q.referring_clinician,
        CASE
            WHEN (q.referral_date IS NOT NULL) THEN (CURRENT_DATE - q.referral_date)
            ELSE NULL::integer
        END AS days_since_referral,
        CASE
            WHEN ((q.referral_date IS NOT NULL) AND ((CURRENT_DATE - q.referral_date) > 30)) THEN true
            ELSE false
        END AS is_referral_expired,
    q.estimated_cost,
    rs.first_name AS requester_first_name,
    rs.last_name AS requester_last_name,
    ps.first_name AS processor_first_name,
    ps.last_name AS processor_last_name,
    q.processing_notes,
    q.rejection_reason
   FROM ((((((((((public.nhis_referral_queue q
     LEFT JOIN public.patients p ON ((q.patient_id = p.id)))
     LEFT JOIN public.nhis_profiles np ON ((p.id = np.patient_id)))
     LEFT JOIN public.clinical_requests cr ON ((q.clinical_request_id = cr.id)))
     LEFT JOIN public.visits v ON ((COALESCE(q.source_encounter_id, cr.encounter_id) = v.id)))
     LEFT JOIN public.consultations c ON ((v.id = c.encounter_id)))
     LEFT JOIN public.staff rd ON ((COALESCE(q.requesting_doctor_id, cr.requesting_doctor_id) = rd.id)))
     LEFT JOIN public.clinics tc ON ((q.target_clinic_id = tc.id)))
     LEFT JOIN public.staff td ON ((q.target_doctor_id = td.id)))
     LEFT JOIN public.staff rs ON ((q.requested_by = rs.id)))
     LEFT JOIN public.staff ps ON ((q.processed_by = ps.id)))
  ORDER BY
        CASE q.urgency
            WHEN 'Emergency'::text THEN 1
            WHEN 'Urgent'::text THEN 2
            WHEN 'Routine'::text THEN 3
            ELSE 4
        END, q.requested_at;


