--
-- Name: nhis_provisional_awaiting_code; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.nhis_provisional_awaiting_code WITH (security_invoker='true') AS
 SELECT a.id AS authorization_id,
    a.patient_id,
    (((p.first_name)::text || ' '::text) || (p.surname)::text) AS patient_name,
    p.emr_number,
    a.specific_service_type,
    a.provisional_reason,
    a.provisional_approved_at,
    (((s.first_name)::text || ' '::text) || (s.last_name)::text) AS approved_by_name,
    a.expiry_date,
    (EXTRACT(epoch FROM (now() - a.provisional_approved_at)) / (3600)::numeric) AS hours_since_approval,
        CASE
            WHEN ((EXTRACT(epoch FROM (now() - a.provisional_approved_at)) / (3600)::numeric) > (48)::numeric) THEN 'overdue'::text
            WHEN ((EXTRACT(epoch FROM (now() - a.provisional_approved_at)) / (3600)::numeric) > (24)::numeric) THEN 'urgent'::text
            ELSE 'normal'::text
        END AS urgency_status
   FROM ((public.nhis_authorizations a
     JOIN public.patients p ON ((a.patient_id = p.id)))
     LEFT JOIN public.staff s ON ((a.provisional_approved_by = s.id)))
  WHERE ((a.is_provisional = true) AND (a.actual_code_received_at IS NULL) AND (a.status = 'active'::public.nhis_auth_status))
  ORDER BY a.provisional_approved_at;


