CREATE TABLE public.physio_sessions (
    session_id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    plan_id uuid NOT NULL,
    assessment_id uuid NOT NULL,
    patient_id character varying(50) NOT NULL,
    encounter_id uuid NOT NULL,
    facility_id uuid,
    session_number integer NOT NULL,
    session_date timestamp with time zone DEFAULT now(),
    pain_score_before integer,
    subjective_report text,
    interval_history text,
    objective_findings text,
    rom_changes text,
    strength_changes text,
    functional_changes text,
    treatment_provided text NOT NULL,
    modalities_used text[],
    modality_parameters jsonb,
    exercises_performed text,
    exercise_sets_reps text,
    manual_techniques_used text,
    patient_response text,
    pain_score_after integer,
    tolerance character varying(50),
    adverse_reactions text,
    progress_notes text,
    goals_addressed text[],
    next_session_plan text,
    home_program_modified boolean DEFAULT false,
    home_program_changes text,
    attendance_status public.attendance_status DEFAULT 'Attended'::public.attendance_status,
    missed_reason text,
    make_up_scheduled boolean DEFAULT false,
    duration_minutes integer,
    treated_by uuid,
    supervised_by uuid,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    compliance_level character varying(50),
    plan_modifications text,
    next_session_focus text,
    outcome_measure_used character varying(100),
    outcome_measure_score numeric(10,2),
    treated_at timestamp with time zone,
    specialty_code character varying(50) DEFAULT 'PHYSIOTHERAPY'::character varying,
    scheduled_date date,
    is_pre_generated boolean DEFAULT false,
    changes_since_last text,
    swelling character varying(20) DEFAULT NULL::character varying,
    tenderness character varying(20) DEFAULT NULL::character varying,
    functional_limitations text,
    gait_assessment text,
    progress_indicator character varying(20) DEFAULT NULL::character varying,
    home_exercise_instructions text,
    plan_for_next_visit text,
    CONSTRAINT physio_sessions_pain_score_after_check CHECK (((pain_score_after >= 0) AND (pain_score_after <= 10))),
    CONSTRAINT physio_sessions_pain_score_before_check CHECK (((pain_score_before >= 0) AND (pain_score_before <= 10))),
    CONSTRAINT physio_sessions_progress_indicator_check CHECK (((progress_indicator)::text = ANY (ARRAY[('Improved'::character varying)::text, ('No_Change'::character varying)::text, ('Worse'::character varying)::text]))),
    CONSTRAINT physio_sessions_swelling_check CHECK (((swelling)::text = ANY (ARRAY[('None'::character varying)::text, ('Mild'::character varying)::text, ('Moderate'::character varying)::text, ('Severe'::character varying)::text]))),
    CONSTRAINT physio_sessions_tenderness_check CHECK (((tenderness)::text = ANY (ARRAY[('None'::character varying)::text, ('Mild'::character varying)::text, ('Moderate'::character varying)::text, ('Severe'::character varying)::text])))
);


--
-- Name: physio_patient_journey; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.physio_patient_journey WITH (security_invoker='true') AS
 SELECT pa.patient_id,
    pa.encounter_id,
    v.visit_type,
    v.status AS encounter_status,
    p.first_name,
    p.surname,
    p.emr_number,
    pa.assessment_id,
    pa.chief_complaint,
    pa.physio_diagnosis,
    pa.pain_score AS initial_pain,
    pa.estimated_sessions,
    pa.status AS assessment_status,
    pa.created_at AS assessment_date,
    pp.plan_id,
    pp.treatment_approach,
    pp.status AS plan_status,
    ( SELECT count(*) AS count
           FROM public.physio_sessions ps
          WHERE (ps.plan_id = pp.plan_id)) AS sessions_completed,
    ( SELECT max(ps.session_date) AS max
           FROM public.physio_sessions ps
          WHERE (ps.plan_id = pp.plan_id)) AS last_session,
    ( SELECT pa.pain_score
           FROM public.physio_sessions ps
          WHERE (ps.plan_id = pp.plan_id)
          ORDER BY ps.session_date DESC
         LIMIT 1) AS current_pain,
    (pd.discharge_id IS NOT NULL) AS is_discharged,
    pd.discharge_date,
    pd.discharge_reason
   FROM ((((public.physio_assessments pa
     LEFT JOIN public.visits v ON ((v.id = pa.encounter_id)))
     LEFT JOIN public.patients p ON (((p.patient_id)::text = (pa.patient_id)::text)))
     LEFT JOIN public.physio_plans pp ON ((pp.assessment_id = pa.assessment_id)))
     LEFT JOIN public.physio_discharge pd ON ((pd.assessment_id = pa.assessment_id)));


