--
-- Name: physio_sessions_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.physio_sessions_summary WITH (security_invoker='true') AS
 SELECT ps.plan_id,
    pa.patient_id,
    pa.encounter_id,
    v.visit_type,
    v.status AS encounter_status,
    p.first_name,
    p.surname,
    p.emr_number,
    count(*) AS total_sessions,
    count(*) FILTER (WHERE (ps.attendance_status = 'Attended'::public.attendance_status)) AS attended,
    count(*) FILTER (WHERE (ps.attendance_status = 'Missed'::public.attendance_status)) AS missed,
    count(*) FILTER (WHERE (ps.attendance_status = 'Cancelled'::public.attendance_status)) AS cancelled,
    avg(ps.pain_score_before) AS avg_pain_before,
    avg(ps.pain_score_after) AS avg_pain_after,
    avg(ps.duration_minutes) AS avg_session_duration,
    min(ps.session_date) AS first_session,
    max(ps.session_date) AS last_session
   FROM ((((public.physio_sessions ps
     JOIN public.physio_plans pp ON ((pp.plan_id = ps.plan_id)))
     JOIN public.physio_assessments pa ON ((pa.assessment_id = pp.assessment_id)))
     LEFT JOIN public.visits v ON ((v.id = pa.encounter_id)))
     LEFT JOIN public.patients p ON (((p.patient_id)::text = (pa.patient_id)::text)))
  GROUP BY ps.plan_id, pa.patient_id, pa.encounter_id, v.visit_type, v.status, p.first_name, p.surname, p.emr_number;


