    CONSTRAINT pregnancy_outcomes_place_of_delivery_check CHECK (((place_of_delivery)::text = ANY (ARRAY[('this_facility'::character varying)::text, ('other_hospital'::character varying)::text, ('home'::character varying)::text, ('en_route'::character varying)::text])))
