ALTER TABLE ONLY public.receipts REPLICA IDENTITY FULL;


--
-- Name: receipts_by_category; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.receipts_by_category WITH (security_invoker='true') AS
 SELECT r.receipt_id,
    r.receipt_number,
    r.patient_id,
    r.encounter_id,
    r.billing_order_id,
    r.amount_paid,
    r.payment_method,
    r.issued_by,
    r.issue_date,
    bi.item_type AS category,
    sum(bi.total_price) AS category_total,
    sum(COALESCE(bi.nhis_payable, (0)::numeric)) AS category_nhis_amount,
    sum(COALESCE(bi.patient_payable, bi.total_price)) AS category_patient_amount,
    count(bi.id) AS item_count,
    array_agg(DISTINCT bi.item_name) AS item_names
   FROM ((public.receipts r
     LEFT JOIN public.billing_orders bo ON ((bo.id = r.billing_order_id)))
     LEFT JOIN public.billing_items bi ON ((bi.billing_order_id = bo.id)))
  WHERE (r.receipt_id IS NOT NULL)
  GROUP BY r.receipt_id, r.receipt_number, r.patient_id, r.encounter_id, r.billing_order_id, r.amount_paid, r.payment_method, r.issued_by, r.issue_date, bi.item_type;


