    reason,
    metadata
   FROM public.audit_logs al
  WHERE (created_at > (now() - '24:00:00'::interval))
  ORDER BY created_at DESC;


--
-- Name: referral_encounters_view; Type: VIEW; Schema: public; Owner: -
