CREATE VIEW public.security_audit_events AS
 SELECT id,
    category,
    action,
    severity,
    user_id,
    user_role,
    user_name,
    user_ip,
    user_agent,
    session_id,
    request_id,
    resource_type,
    resource_id,
    resource_name,
    patient_id,
    patient_name,
    encounter_id,
