    old_values,
    new_values,
    changed_fields,
    metadata,
    reason,
    authorization_ref,
    created_at,
    retention_until,
    is_archived
   FROM public.audit_logs
  WHERE ((category = ANY (ARRAY['authentication'::public.audit_category, 'access_control'::public.audit_category, 'emergency'::public.audit_category])) OR (severity = ANY (ARRAY['warning'::public.audit_severity, 'alert'::public.audit_severity, 'critical'::public.audit_severity])))
  ORDER BY created_at DESC;


