CREATE VIEW public.security_services_patients_view WITH (security_invoker='true') AS
 SELECT p.id,
    p.patient_id,
    p.emr_number,
    concat(p.first_name, ' ', COALESCE(((p.middle_name)::text || ' '::text), ''::text), p.surname) AS full_name,
    p.first_name,
    p.surname,
    p.gender,
    p.date_of_birth,
    p.contact_phone,
    p.insurance_type,
    p.patient_category,
    p.security_organization,
    p.security_service_number,
    so.name AS security_org_name,
    so.short_name AS security_org_short_name,
    so.category AS security_org_category,
    (p.payer_info ->> 'scheme'::text) AS hmo_scheme,
    (p.payer_info ->> 'enrolee_id'::text) AS nhis_enrolee_id,
    p.created_at,
    p.updated_at
   FROM (public.patients p
     LEFT JOIN public.security_organizations so ON (((p.security_organization)::text = (so.code)::text)))
  WHERE (((p.insurance_type)::text = 'Security_Services_NHIS'::text) AND (p.status <> 'Inactive'::public.patient_status))
  ORDER BY so.display_order, p.surname, p.first_name;


