--
-- Name: specialty_examination_stats; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.specialty_examination_stats WITH (security_invoker='true') AS
 SELECT specialty_code,
    specialty_name,
    exam_table_name,
    icon_name,
    color_class,
        CASE
            WHEN ((exam_table_name)::text = 'consultations'::text) THEN ( SELECT count(*) AS count
               FROM (public.consultations c
                 LEFT JOIN public.visits v ON ((v.id = c.encounter_id)))
              WHERE (((c.specialty_code)::text = (sd.specialty_code)::text) AND ((c.consultation_date)::date = CURRENT_DATE) AND ((v.status IS NULL) OR (v.status = ANY (ARRAY['Active'::public.visit_status, 'Closed'::public.visit_status])))))
            ELSE (0)::bigint
        END AS exams_today,
        CASE
            WHEN ((exam_table_name)::text = 'consultations'::text) THEN ( SELECT count(*) AS count
               FROM (public.consultations c
                 LEFT JOIN public.visits v ON ((v.id = c.encounter_id)))
              WHERE (((c.specialty_code)::text = (sd.specialty_code)::text) AND (c.consultation_date >= (CURRENT_DATE - '7 days'::interval)) AND ((v.status IS NULL) OR (v.status = ANY (ARRAY['Active'::public.visit_status, 'Closed'::public.visit_status])))))
            ELSE (0)::bigint
        END AS exams_week,
        CASE
            WHEN ((exam_table_name)::text = 'consultations'::text) THEN ( SELECT count(*) AS count
               FROM (public.consultations c
                 LEFT JOIN public.visits v ON ((v.id = c.encounter_id)))
              WHERE (((c.specialty_code)::text = (sd.specialty_code)::text) AND (c.consultation_date >= (CURRENT_DATE - '30 days'::interval)) AND ((v.status IS NULL) OR (v.status = ANY (ARRAY['Active'::public.visit_status, 'Closed'::public.visit_status])))))
            ELSE (0)::bigint
        END AS exams_month
   FROM public.specialty_departments sd
  WHERE (is_active = true)
  ORDER BY display_order;


