--
-- Name: specialty_patients_unified; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.specialty_patients_unified WITH (security_invoker='true') AS
 SELECT c.specialty_code,
    COALESCE(sd.specialty_name, c.specialty_code) AS specialty_name,
    c.patient_id,
    p.id AS patient_uuid,
    c.encounter_id,
    v.visit_type,
    v.current_stage AS encounter_stage,
    v.status AS encounter_status,
    p.first_name,
    p.surname,
    p.emr_number,
    (c.consultation_id)::text AS record_id,
    'consultations'::text AS source_table,
    COALESCE(c.complaints, c.subjective) AS chief_complaint,
    COALESCE(c.diagnosis_text, array_to_string(c.diagnosis, ', '::text)) AS diagnosis,
    (c.status)::text AS status,
    c.consultation_date AS created_at,
    c.doctor_id AS created_by
   FROM (((public.consultations c
     LEFT JOIN public.specialty_departments sd ON (((sd.specialty_code)::text = (c.specialty_code)::text)))
     LEFT JOIN public.visits v ON ((v.id = c.encounter_id)))
     LEFT JOIN public.patients p ON (((p.patient_id)::text = (c.patient_id)::text)))
  WHERE (c.specialty_code IS NOT NULL);


--
-- Name: specialty_procedures_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.specialty_procedures_view WITH (security_invoker='true') AS
 SELECT sd.specialty_code,
    sd.specialty_name,
    sd.icon_name,
    sd.color_class,
    cr.id AS request_id,
    cr.request_number,
    cr.encounter_id,
    v.visit_type,
    v.current_stage AS encounter_stage,
    v.status AS encounter_status,
    cr.procedure_name,
    cr.request_type AS procedure_type,
    cr.status,
    cr.urgency,
    cr.clinical_reason,
    cr.created_at AS requested_at,
    cr.scheduled_date,
    p.first_name AS patient_first_name,
    p.surname AS patient_last_name,
    p.emr_number,
    s.first_name AS requested_by_first,
    s.last_name AS requested_by_last
   FROM ((((public.clinical_requests cr
     JOIN public.specialty_departments sd ON (((sd.specialty_code)::text = (cr.target_specialty_code)::text)))
     LEFT JOIN public.visits v ON ((v.id = cr.encounter_id)))
     JOIN public.patients p ON ((p.id = cr.patient_id)))
     LEFT JOIN public.staff s ON ((s.id = cr.requesting_doctor_id)))
  WHERE ((cr.request_type = 'Procedure'::public.clinical_request_type) AND ((v.status IS NULL) OR (v.status = ANY (ARRAY['Active'::public.visit_status, 'Closed'::public.visit_status]))))
  ORDER BY cr.urgency DESC, cr.created_at;


--
-- Name: specialty_queue_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.specialty_queue_view WITH (security_invoker='true') AS
 SELECT q.id,
    q.ticket_number,
    q.status,
    q.priority,
    q.specialty_code,
    q.location,
    q.created_at,
    q.called_at,
    q.completed_at,
    q.assigned_to,
    sd.specialty_name,
    sd.icon_name,
    sd.color_class,
    (((p.first_name)::text || ' '::text) || (p.surname)::text) AS patient_name,
    p.emr_number,
    p.patient_id AS display_patient_id
   FROM ((public.queue q
     LEFT JOIN public.specialty_departments sd ON (((sd.specialty_code)::text = (q.specialty_code)::text)))
     JOIN public.patients p ON ((p.id = q.patient_id)))
  WHERE (q.status = ANY (ARRAY['Waiting'::public.queue_status, 'In Progress'::public.queue_status, 'Called'::public.queue_status]));


