);


--
-- Name: staff_messages_inbox_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.staff_messages_inbox_view WITH (security_invoker='true') AS
 SELECT sm.id,
    sm.subject,
    sm.message,
    sm.priority,
    sm.created_at,
    sm.thread_id,
    sm.parent_message_id,
    sm.patient_id,
    sm.encounter_id,
    sm.metadata,
    sm.attachments,
    sm.recipient_department_id,
    sm.recipient_department_name,
    sm.recipient_role,
    sm.sender_id,
    (((s.first_name)::text || ' '::text) || (s.last_name)::text) AS sender_name,
    s.role AS sender_role,
    sd.name AS sender_department,
    mr.recipient_id,
    mr.is_read,
    mr.read_at,
    mr.is_archived,
    (((p.first_name)::text || ' '::text) || (p.surname)::text) AS patient_name,
    p.emr_number AS patient_emr_number
   FROM ((((public.staff_messages sm
     JOIN public.message_recipients mr ON ((sm.id = mr.message_id)))
     JOIN public.staff s ON ((sm.sender_id = s.id)))
     LEFT JOIN public.departments sd ON ((sm.sender_department_id = sd.id)))
     LEFT JOIN public.patients p ON ((sm.patient_id = p.id)))
  WHERE ((NOT mr.is_deleted) AND (sm.deleted_at IS NULL))
  ORDER BY sm.created_at DESC;


