--
-- Name: surgery_dashboard_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.surgery_dashboard_view WITH (security_invoker='true') AS
 SELECT s.id,
    s.surgery_number,
    s.primary_procedure,
    s.status,
    s.priority,
    s.scheduled_date,
    s.scheduled_time,
    s.theatre_room,
    s.consent_obtained,
    s.preop_checklist_completed,
    s.requires_nhis_approval,
    s.nhis_authorization_code,
    p.id AS patient_id,
    (((p.first_name)::text || ' '::text) || (p.surname)::text) AS patient_name,
    p.emr_number,
    p.insurance_type,
    (((surgeon.first_name)::text || ' '::text) || (surgeon.last_name)::text) AS surgeon_name,
    s.facility_id,
    s.created_at,
        CASE
            WHEN (s.status = 'Planned'::public.surgery_status) THEN 1
            WHEN (s.status = 'Pre_Op'::public.surgery_status) THEN 2
            WHEN (s.status = 'In_Theatre'::public.surgery_status) THEN 3
            WHEN (s.status = 'Recovery'::public.surgery_status) THEN 4
            ELSE 5
        END AS status_order
   FROM ((public.surgeries s
     JOIN public.patients p ON ((s.patient_id = p.id)))
     JOIN public.staff surgeon ON ((s.primary_surgeon_id = surgeon.id)))
  ORDER BY
        CASE s.priority
            WHEN 'Emergency'::text THEN 1
            WHEN 'Urgent'::text THEN 2
            WHEN 'Routine'::text THEN 3
            ELSE 4
        END, s.scheduled_date, s.scheduled_time;


