--
-- Name: system_performance_stats; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.system_performance_stats WITH (security_invoker='true') AS
 SELECT 'visits'::text AS table_name,
    ( SELECT count(*) AS count
           FROM public.visits) AS row_count,
    ( SELECT count(*) AS count
           FROM public.visits
          WHERE (visits.created_at > (now() - '24:00:00'::interval))) AS last_24h
UNION ALL
 SELECT 'patients'::text AS table_name,
    ( SELECT count(*) AS count
           FROM public.patients) AS row_count,
    ( SELECT count(*) AS count
           FROM public.patients
          WHERE (patients.created_at > (now() - '24:00:00'::interval))) AS last_24h
UNION ALL
 SELECT 'billing_orders'::text AS table_name,
    ( SELECT count(*) AS count
           FROM public.billing_orders) AS row_count,
    ( SELECT count(*) AS count
           FROM public.billing_orders
          WHERE (billing_orders.created_at > (now() - '24:00:00'::interval))) AS last_24h
UNION ALL
 SELECT 'lab_requests'::text AS table_name,
    ( SELECT count(*) AS count
           FROM public.lab_requests) AS row_count,
    ( SELECT count(*) AS count
           FROM public.lab_requests
          WHERE (lab_requests.created_at > (now() - '24:00:00'::interval))) AS last_24h;


