    CONSTRAINT theatre_schedules_schedule_status_check CHECK (((schedule_status)::text = ANY (ARRAY[('Scheduled'::character varying)::text, ('Confirmed'::character varying)::text, ('In_Progress'::character varying)::text, ('Completed'::character varying)::text, ('Cancelled'::character varying)::text, ('Delayed'::character varying)::text])))
);


--
-- Name: theatre_schedule_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.theatre_schedule_view WITH (security_invoker='true') AS
 SELECT ts.id AS schedule_id,
    ts.scheduled_date,
    ts.start_time,
    ts.end_time,
    ts.schedule_status,
    tr.room_code,
    tr.room_name,
    (tr.room_type)::text AS room_type,
    s.id AS surgery_id,
    s.surgery_number,
    s.primary_procedure,
    s.status AS surgery_status,
    s.priority,
    p.id AS patient_id,
    (((p.first_name)::text || ' '::text) || (p.surname)::text) AS patient_name,
    p.emr_number,
    (((surgeon.first_name)::text || ' '::text) || (surgeon.last_name)::text) AS surgeon_name,
    (((anest.first_name)::text || ' '::text) || (anest.last_name)::text) AS anesthetist_name,
    ts.notes
   FROM (((((public.theatre_schedules ts
     JOIN public.theatre_rooms tr ON ((ts.theatre_room_id = tr.id)))
     JOIN public.surgeries s ON ((ts.surgery_id = s.id)))
     JOIN public.patients p ON ((s.patient_id = p.id)))
     JOIN public.staff surgeon ON ((s.primary_surgeon_id = surgeon.id)))
     LEFT JOIN public.staff anest ON ((s.anesthetist_id = anest.id)))
  ORDER BY ts.scheduled_date, ts.start_time;


--
-- Name: todays_procedures; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.todays_procedures AS
 SELECT pr.id AS procedure_id,
    pr.procedure_number,
    pr.procedure_name,
    pr.scheduled_date,
    pr.scheduled_duration_minutes,
    pr.priority,
    pr.status,
    pr.location,
    pr.room_number,
    pr.anesthesia_type,
    p.id AS patient_id,
    p.first_name,
    p.surname AS last_name,
    p.emr_number AS hospital_id,
    s.first_name AS surgeon_first_name,
    s.last_name AS surgeon_last_name,
    pr.facility_id
   FROM ((public.procedures pr
     JOIN public.patients p ON ((p.id = pr.patient_id)))
     LEFT JOIN public.staff s ON ((s.id = pr.primary_surgeon_id)))
  WHERE ((date(pr.scheduled_date) = CURRENT_DATE) AND ((pr.status)::text <> ALL (ARRAY[('cancelled'::character varying)::text, ('completed'::character varying)::text])))
  ORDER BY pr.scheduled_date;


