--
-- Name: unified_billing_activity; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.unified_billing_activity WITH (security_invoker='true') AS
 SELECT 'invoice'::text AS source_type,
    (i.invoice_id)::text AS record_id,
    i.invoice_number AS display_number,
    (i.patient_id)::text AS patient_id,
    NULL::text AS visit_id,
    (i.encounter_id)::text AS encounter_id,
    NULL::text AS source_module,
    i.total_amount,
    i.amount_paid,
    i.balance,
    (i.status)::text AS status,
    i.created_at,
    i.updated_at,
    (i.created_by)::text AS created_by
   FROM public.invoices i
UNION ALL
 SELECT 'billing_order'::text AS source_type,
    (bo.id)::text AS record_id,
    bo.order_number AS display_number,
    (bo.patient_id)::text AS patient_id,
    (bo.visit_id)::text AS visit_id,
    (bo.encounter_id)::text AS encounter_id,
    (bo.source_module)::text AS source_module,
    COALESCE(bo.net_amount, bo.total_amount, (0)::numeric) AS total_amount,
    COALESCE(bo.paid_amount, (0)::numeric) AS amount_paid,
    COALESCE(bo.balance_amount, (0)::numeric) AS balance,
    (bo.status)::text AS status,
    bo.created_at,
    bo.updated_at,
    (bo.created_by)::text AS created_by
   FROM public.billing_orders bo;


