--

CREATE TRIGGER trg_enforce_patient_duplicate_guard_update BEFORE UPDATE ON public.patients FOR EACH ROW WHEN ((((new.nhis_number)::text IS DISTINCT FROM (old.nhis_number)::text) OR ((new.national_id)::text IS DISTINCT FROM (old.national_id)::text) OR ((new.service_number)::text IS DISTINCT FROM (old.service_number)::text) OR ((new.first_name)::text IS DISTINCT FROM (old.first_name)::text) OR ((new.surname)::text IS DISTINCT FROM (old.surname)::text) OR (new.date_of_birth IS DISTINCT FROM old.date_of_birth) OR (new.gender IS DISTINCT FROM old.gender) OR ((new.contact_phone)::text IS DISTINCT FROM (old.contact_phone)::text) OR ((new.email)::text IS DISTINCT FROM (old.email)::text))) EXECUTE FUNCTION public.enforce_patient_duplicate_guard();


